const labels={content:'Short Question & Answer',mcq:'MCQ Quiz Test',viva:'Viva Preparation'},bnLabels={content:'সংক্ষিপ্ত প্রশ্ন ও উত্তর',mcq:'MCQ কুইজ টেস্ট',viva:'ভাইভা প্রস্তুতি'};let openChapter=0,activeChapter=0,activeSection='content',query='',quizState={},language=localStorage.getItem('ecm-language')||'en';try{quizState=JSON.parse(localStorage.getItem('ecm-quiz-state'))||{}}catch{}
const banglaHelp={
3:[
{concept:'Electrical Safety মানে শুধু সাবধানে কাজ করা নয়; কাজ শুরুর আগে Hazard শনাক্ত করা, supply isolate করা, unexpected energization বন্ধ করা এবং উপযুক্ত tester দিয়ে Voltage নেই নিশ্চিত করা। কোনো switch OFF দেখালেই circuit নিরাপদ ধরে নেওয়া যাবে না।',example:'Socket বদলানোর আগে শুধু wall switch নয়, সংশ্লিষ্ট breaker isolate করে competent person tester দিয়ে অবস্থা যাচাই করবে। Battery, generator বা solar back-feed থাকলে সেগুলোকেও আলাদা করতে হবে।',remember:'চেনো → Isolate করো → Verify করো → তারপর কাজ করো।'},
{concept:'Electrical Hazard হলো ক্ষতির উৎস; Risk হলো সেই ক্ষতি ঘটার সম্ভাবনা ও ফলের তীব্রতা। Shock ছাড়াও short circuit, overload, Earth Fault, Arc Flash, fire এবং capacitor বা battery-তে জমা energy বিপজ্জনক।',example:'ঢিলা terminal-এ Resistance ও heating বেড়ে fire হতে পারে। Wet hand-এ skin Resistance কমে একই Voltage-এ body Current বাড়তে পারে। Motor বন্ধ থাকলেও capacitor charged থাকতে পারে।',remember:'Hazard দেখা না গেলেও থাকতে পারে; OFF মানেই zero energy নয়।'},
{concept:'PPE অবশিষ্ট Risk কমানোর শেষ protective layer। Gloves, eye/face protection, helmet, footwear ও Arc-Rated clothing কাজ, Voltage এবং assessed energy অনুযায়ী নির্বাচন করতে হয়। PPE isolation-এর বিকল্প নয়।',example:'Cracked insulating glove বা ভুল Arc rating নিরাপত্তার মিথ্যা ধারণা দেয়। তাই ব্যবহারের আগে damage, test date, rating, fit এবং compatibility পরীক্ষা করা জরুরি।',remember:'আগে eliminate/isolate/control; তারপর সঠিক PPE।'},
{concept:'Electrical symbol component-এর physical shape নয়, তার electrical function বোঝায়। Diagram-এ cell, resistor, switch, junction, fuse, Earth, Ammeter ও Voltmeter-এর standard representation দেখে circuit বুঝতে হয়।',example:'দুটি wire crossing-এর জায়গায় dot থাকলে সাধারণত connection বোঝায়; dot না থাকলে drawing convention দেখে নিশ্চিত হতে হয়। Protective Earth ও Circuit Ground একই উদ্দেশ্যের নাও হতে পারে।',remember:'Symbol পড়ার সময় standard, legend ও drawing context দেখো।'},
{concept:'সঠিক tool নিরাপত্তা ও connection quality দুটোই বাড়ায়। Screwdriver tip, stripper slot, cutter capacity এবং crimping die conductor ও terminal-এর সঙ্গে মিলতে হবে। Handle insulated দেখালেই energized work-এর জন্য rated ধরে নেওয়া যাবে না।',example:'ভুল stripper slot conductor strand কেটে দেয়; সাধারণ pliers দিয়ে crimp করলে loose joint তৈরি হয়ে heating হতে পারে। Cracked handle বা worn jaw-এর tool service থেকে সরাতে হবে।',remember:'সঠিক Tool + সঠিক Size + সঠিক Rating + ভালো Condition।'},
{concept:'Ammeter branch Current মাপে এবং series-এ বসে; Voltmeter দুই point-এর Potential Difference মাপে এবং parallel-এ বসে। Ohmmeter নিজের test source ব্যবহার করে, তাই energized circuit-এ ব্যবহার করা যাবে না। Multimeter-এর function, range, socket ও lead একসঙ্গে ঠিক করতে হয়।',example:'Current socket-এ lead রেখে battery-এর দুই terminal-এ probe ধরলে meter low-Resistance short path বানাতে পারে। Clamp Meter দিয়ে load Current মাপতে সাধারণত একটি conductor jaw-এর মধ্যে নিতে হয়।',remember:'Ammeter—Series; Voltmeter—Parallel; Ohmmeter—Power OFF।'},
{concept:'Safe measurement শুরু হয় expected value ও AC/DC জানার মাধ্যমে। Meter body, fuse, leads, probe guard, category ও range পরীক্ষা করে তারপর connection করতে হয়। Absence of Voltage verification-এ approved procedure অনুসারে tester কাজ করছে কি না নিশ্চিত করা জরুরি।',example:'Resistance মাপার আগে source isolate, stored energy discharge এবং Voltage absence verify করতে হবে। Probe ধরার সময় আঙুল guard-এর পেছনে রেখে adjacent terminal bridge হওয়া ঠেকাতে হবে।',remember:'Plan → Inspect → Select → Connect → Test → Record।'},
{concept:'Quantity হলো যা মাপি, quantity symbol equation-এ তাকে প্রকাশ করে, আর unit তার পরিমাণ জানায়। Current-এর unit ampere (A), Voltage-এর volt (V), Resistance-এর ohm (Ω), Power-এর watt (W)। Prefix-এর uppercase/lowercase বদলালে মান বদলে যায়।',example:'250 mA = 0.250 A, 4.7 kΩ = 4700 Ω। এখানে m = 10⁻³, k = 10³ এবং M = 10⁶। তাই 5 mA ও 5 MA এক নয়।',remember:'Value ও unit-এর মাঝে space: 230 V; m ছোট, M বড়।'},
{concept:'Home, laboratory ও industry-তে একই মূলনীতি থাকলেও control level আলাদা। Home-এ wet hand ও overload এড়ানো, lab-এ wiring change-এর সময় supply OFF রাখা, industry-তে permit, LOTO, verification, boundary ও team communication অনুসরণ করা দরকার।',example:'Shock victim source-এর সঙ্গে যুক্ত থাকলে সরাসরি ধরলে rescuer-ও Current path হতে পারে। আগে নিরাপদভাবে source control করে emergency help ডাকতে হবে। Energized electrical equipment-এ পানি ব্যবহার করা যাবে না।',remember:'পরিস্থিতি plan-এর বাইরে গেলে Stop, Assess, Control এবং Authorize।'}],
1:[
{concept:'Electricity কোনো আলাদা পদার্থ নয়; এটি electric charge-এর উপস্থিতি ও চলাচলের সঙ্গে সম্পর্কিত একটি physical phenomenon। কোনো conductor-এর দুই প্রান্তে Voltage প্রয়োগ করে closed path তৈরি করলে free electron চলতে শুরু করে। এই নিয়ন্ত্রিত charge flow-কে Electric Current বলা হয়। Current-এর মাধ্যমে source থেকে load-এ electrical energy পৌঁছে এবং lamp, motor বা heater কাজ করে। তাই Electricity ও Electric Current একই বিষয় নয়—Electricity বড় ধারণা, আর Current হলো চলমান charge।',example:'Battery, switch ও lamp দিয়ে circuit তৈরি করলে switch বন্ধ করার পর electron চলাচল করে এবং lamp জ্বলে। Battery energy দেয়, wire current-এর পথ দেয় এবং lamp সেই energy-কে আলো ও তাপে রূপান্তর করে।',remember:'Electricity = Charge-এর উপস্থিতি বা চলাচল; Electric Current = Charge-এর প্রবাহ।'},
{concept:'Atom হলো কোনো element-এর এমন ক্ষুদ্রতম একক যা সেই element-এর chemical properties ধরে রাখে। Atom-এর কেন্দ্রে Nucleus থাকে; সেখানে positively charged Proton ও electrically neutral Neutron থাকে। Negatively charged Electron nucleus-এর চারদিকে বিভিন্ন energy level-এ অবস্থান করে। Electrical Engineering-এ বাইরের shell-এর Electron সবচেয়ে গুরুত্বপূর্ণ, কারণ কিছু material-এ এগুলো atom-এর সঙ্গে দুর্বলভাবে যুক্ত থাকে এবং সহজে চলতে পারে।',example:'Copper atom-এর outer electron তুলনামূলকভাবে সহজে মুক্ত হয়ে conductor-এর মধ্যে চলতে পারে। এই free electron-এর চলাচলই metallic wire-এ Electric Current তৈরি করে। Proton nucleus-এ শক্তভাবে আবদ্ধ থাকায় wire-এর ভেতর দিয়ে current বহন করে না।',remember:'Nucleus = Proton + Neutron; Current বহনের প্রধান কণা = Free Electron।'},
{concept:'Electric Charge পদার্থের একটি মৌলিক electrical property, যার কারণে attraction বা repulsion তৈরি হয়। Charge দুই ধরনের—Positive এবং Negative। একই ধরনের charge পরস্পরকে দূরে ঠেলে দেয়, আর বিপরীত charge পরস্পরকে আকর্ষণ করে। Electron negative charge বহন করে, Proton positive charge বহন করে এবং Neutron-এর net charge নেই। Charge-এর SI unit Coulomb (C)।',example:'দুটি balloon ঘষে একই ধরনের charge দিলে তারা একে অপরকে repel করতে পারে। আবার charged balloon ছোট কাগজের টুকরোকে কাছে টানতে পারে। Battery-এর দুই terminal-এ charge separation থাকার কারণে circuit-এ Voltage তৈরি হয়।',remember:'Like Charge → Repel; Unlike Charge → Attract; Unit → Coulomb।'},
{concept:'Material-এর ভেতরে charge carrier কত সহজে চলতে পারে তার ওপর electrical behavior নির্ভর করে। Conductor-এ অনেক free electron থাকে, তাই current সহজে চলে। Insulator-এ electron শক্তভাবে atom-এর সঙ্গে যুক্ত থাকে, তাই current প্রবাহ খুব কম। Semiconductor-এর conductivity conductor ও insulator-এর মাঝামাঝি এবং temperature, light বা doping দিয়ে নিয়ন্ত্রণ করা যায়।',example:'Copper wire-এর ভেতর দিয়ে current যায়, কিন্তু wire-এর PVC covering current বাইরে যেতে বাধা দেয়। Silicon-এর conductivity নিয়ন্ত্রণ করে diode, transistor ও integrated circuit তৈরি করা হয়। ফলে একই electrical system-এ conductor, insulator ও semiconductor—তিন ধরনের material-ই প্রয়োজন হয়।',remember:'Copper → Conductor; PVC/Rubber → Insulator; Silicon → Semiconductor।'},
{concept:'Static Electricity হলো কোনো material-এর পৃষ্ঠে electric charge জমে থাকা, যেখানে charge continuous circuit-এর মতো প্রবাহিত হয় না। Friction, contact বা induction-এর কারণে এক বস্তু থেকে অন্য বস্তুতে Electron transfer হলে charge imbalance তৈরি হয়। জমে থাকা charge উপযুক্ত পথ পেলে হঠাৎ discharge হতে পারে এবং ছোট spark দেখা যায়।',example:'শুকনো আবহাওয়ায় carpet-এর ওপর হাঁটার পর metal handle ধরলে ছোট shock লাগতে পারে। Electronic component handling-এর সময় এই Electrostatic Discharge বা ESD sensitive chip নষ্ট করতে পারে, তাই technicianরা antistatic wrist strap ব্যবহার করেন।',remember:'Static = Charge at Rest; ESD = জমে থাকা charge-এর হঠাৎ discharge।'},
{concept:'Electric Current হলো conductor-এর কোনো cross-section দিয়ে প্রতি unit time-এ কত electric charge অতিক্রম করছে তার হার। Formula I = Q/t, যেখানে I হলো Current, Q হলো Charge এবং t হলো Time। Current-এর SI unit Ampere (A)। Metallic conductor-এ electron negative terminal থেকে positive terminal-এর দিকে চলে, কিন্তু conventional current direction ধরা হয় positive থেকে negative।',example:'একটি 12 V battery lamp-এর সঙ্গে closed circuit-এ যুক্ত করলে charge flow শুরু হয়। Ammeter current মাপতে circuit-এর সঙ্গে series-এ যুক্ত করা হয়, কারণ load-এর মধ্য দিয়ে যে current যায়, meter-এর মধ্য দিয়েও একই current যেতে হবে।',remember:'Current = Charge/Time; Symbol = I; Unit = Ampere; Ammeter → Series।'}],
2:[
{concept:'Voltage হলো circuit-এর দুই point-এর মধ্যে প্রতি unit charge-এর electrical energy difference। Formula V = W/Q; অর্থাৎ এক Coulomb charge এক point থেকে অন্য point-এ গেলে যত Joule energy transfer হয়, সেটিই Voltage নির্ধারণ করে। Water-pressure analogy দিয়ে সহজে বোঝা যায়: pressure difference যেমন পানি চালায়, Voltage difference তেমনি closed circuit-এ current চালাতে পারে। তবে Voltage নিজে current নয়।',example:'একটি 12 V battery প্রতি Coulomb charge-কে আদর্শভাবে 12 Joule energy দিতে পারে। Voltmeter বা DMM দিয়ে Voltage মাপতে দুই probe দুই point-এ বসাতে হয় এবং meter-কে parallel-এ connect করতে হয়।',remember:'Voltage = Energy per Charge; 1 V = 1 J/C; Voltmeter → Parallel।'},
{concept:'Electromotive Force বা EMF হলো battery, generator বা solar cell-এর মতো source প্রতি unit charge-কে যে electrical energy সরবরাহ করে। নামের মধ্যে “Force” থাকলেও এটি mechanical force নয়; EMF-এর unit Newton নয়, Volt। Source-এর ভেতরে chemical, mechanical বা light energy electrical energy-তে convert হয়ে charge-কে lower potential থেকে higher potential-এ নেয়।',example:'Battery open-circuit অবস্থায় কোনো load current না দিলে terminal-এ মাপা Voltage প্রায় EMF-এর সমান হয়। Load connect করলে internal resistance-এর কারণে Ir drop তৈরি হয় এবং terminal voltage হয় V = E − Ir। তাই দুর্বল battery load দিলে Voltage বেশি কমে যেতে পারে।',remember:'EMF = Source-supplied Energy per Charge; Loaded Source: V = E − Ir।'},
{concept:'Potential Difference হলো circuit-এর দুই point-এর মধ্যে প্রতি unit charge কত electrical energy transfer বা convert হচ্ছে। EMF সাধারণত source-এর energy supply বোঝায়, আর Potential Difference সাধারণত load বা দুই circuit point-এর মধ্যে energy change বোঝায়। দুটির unit একই—Volt। Voltage শব্দটি practical engineering-এ Potential Difference বোঝাতে সবচেয়ে বেশি ব্যবহৃত হয়।',example:'Lamp-এর দুই terminal-এর Potential Difference থাকার কারণে current lamp-এর filament দিয়ে যায় এবং electrical energy আলো ও তাপে রূপান্তরিত হয়। Fuse-এর দুই পাশে প্রায় zero Voltage থাকলে fuse ভালো হতে পারে; supply থাকা অবস্থায় বড় Voltage পাওয়া গেলে fuse open হওয়ার সম্ভাবনা আছে।',remember:'EMF → Source energy supply; Potential Difference → দুই point-এর energy difference।'},
{concept:'Resistance হলো material বা component-এর এমন property যা Electric Current-এর প্রবাহকে বাধা দেয়। Ohmic component-এর ক্ষেত্রে R = V/I। Resistance বেশি হলে একই Voltage-এ Current কম হয়। Electron material-এর atomic lattice-এর সঙ্গে collision করলে electrical energy-এর একটি অংশ heat-এ convert হয়। Resistance-এর symbol R এবং SI unit Ohm (Ω)।',example:'LED-এর সঙ্গে resistor ব্যবহার করে অতিরিক্ত current সীমিত করা হয়। Heater-এ high-resistance Nichrome element ব্যবহার করা হয় যাতে electrical energy heat-এ রূপান্তরিত হয়। Ohmmeter দিয়ে Resistance মাপার আগে circuit de-energize করতে হয়, কারণ meter নিজেই test current দেয়।',remember:'Resistance → Current-এর বাধা; Unit = Ohm; Resistance measurement → Power OFF।'},
{concept:'Uniform conductor-এর Resistance R = ρL/A formula দিয়ে বোঝানো যায়। এখানে ρ হলো material-এর Resistivity, L হলো Length এবং A হলো cross-sectional Area। একই material-এর wire লম্বা হলে electron-এর পথ দীর্ঘ হয়, তাই Resistance বাড়ে। Wire মোটা হলে current চলার জন্য বেশি path পাওয়া যায়, তাই Resistance কমে। Temperature-ও গুরুত্বপূর্ণ; অধিকাংশ metal গরম হলে Resistance বাড়ে।',example:'দীর্ঘ cable run-এ Resistance ও Voltage drop বেশি হয়, তাই engineer বড় cross-sectional area-এর cable নির্বাচন করেন। Copper-এর resistivity কম বলে wiring-এ ব্যবহার হয়। Nichrome-এর resistivity বেশি ও উচ্চ temperature সহ্য করতে পারে বলে heater element-এ ব্যবহার হয়। RTD metal-এর predictable resistance change ব্যবহার করে temperature মাপে।',remember:'Length ↑ → R ↑; Area ↑ → R ↓; Metal Temperature ↑ → R ↑।'},
{concept:'Ohm\'s Law বলে—temperature ও অন্যান্য physical condition constant থাকলে conductor-এর Current তার দুই প্রান্তের Voltage-এর directly proportional। Formula V = IR; এখান থেকে I = V/R এবং R = V/I পাওয়া যায়। তাই Resistance স্থির রেখে Voltage বাড়ালে Current বাড়ে, আর Voltage স্থির রেখে Resistance বাড়ালে Current কমে।',example:'12 V source-এর সঙ্গে 6 Ω resistor যুক্ত করলে I = V/R = 12/6 = 2 A। আবার একই 12 V source-এ 12 Ω resistor দিলে Current হয় 1 A। এতে বোঝা যায় Resistance দ্বিগুণ করলে constant Voltage-এ Current অর্ধেক হয়। Diode বা গরম filament lamp-এর Resistance constant নয়, তাই সব অবস্থায় সরল Ohm\'s Law মানে না।',remember:'V = IR; Constant R-এ V ↑ → I ↑; Constant V-তে R ↑ → I ↓।'}],
5:[
{concept:'Electrical Power বোঝায় কোনো electrical system কত দ্রুত Energy transfer, convert বা consume করছে। Formula P = E/t এবং DC circuit-এ P = VI। একই পরিমাণ Energy কম সময়ে ব্যবহার করলে Power বেশি হয়। তাই Watt মোট Energy নয়; এটি Energy ব্যবহারের rate। Resistive load-এর জন্য Ohm\'s Law ব্যবহার করে P = I²R এবং P = V²/R-ও পাওয়া যায়।',example:'12 V supply থেকে 2 A current নেওয়া lamp-এর Power P = 12 × 2 = 24 W। অর্থাৎ lamp প্রতি second-এ 24 Joule electrical energy গ্রহণ করে আলো ও তাপে convert করছে। Wattmeter circuit-এর Power সরাসরি মাপতে পারে।',remember:'Power = Energy/Time; DC Power = Voltage × Current; Unit = Watt।'},
{concept:'Electrical Energy হলো নির্দিষ্ট সময় ধরে transfer বা consume হওয়া মোট electrical work। Formula E = Pt। SI unit Joule হলেও বাসা, দোকান ও শিল্পের practical consumption সাধারণত Wh বা kWh-এ হিসাব করা হয়। 1 kWh মানে 1 kW Power এক ঘণ্টা ব্যবহার করা এবং এটি 3.6 × 10⁶ Joule-এর সমান।',example:'100 W lamp 5 ঘণ্টা চললে Energy = 100 × 5 = 500 Wh = 0.5 kWh। একই lamp 10 ঘণ্টা চললে 1 kWh Energy ব্যবহার করবে। Energy meter সময়ের সঙ্গে এই consumption জমা করে দেখায়।',remember:'Energy = Power × Time; 1 kWh = 3.6 MJ = 1 unit electricity।'},
{concept:'Power এবং Energy এক নয়। Power হলো Energy transfer-এর rate, আর Energy হলো সেই rate নির্দিষ্ট সময় ধরে চলার মোট ফল। Formula E = Pt থেকে বোঝা যায় Energy consumption কমাতে Power, operating time অথবা দুটোই কমাতে হয়। High-Power device অল্প সময় চললে কখনো Low-Power device-এর দীর্ঘ সময়ের চেয়ে কম Energy ব্যবহার করতে পারে।',example:'2 kW heater 30 মিনিট চললে 2 × 0.5 = 1 kWh ব্যবহার করে। 100 W lamp 10 ঘণ্টা চললেও 0.1 × 10 = 1 kWh ব্যবহার করে। Power rating ভিন্ন হলেও Power ও Time-এর গুণফল সমান হওয়ায় Energy একই।',remember:'Power → কত দ্রুত; Energy → মোট কত; kWh = kW × hour।'},
{concept:'Efficiency দেখায় মোট input-এর কত অংশ useful output-এ পরিণত হয়েছে। Formula η = Useful Output/Input × 100%। Practical motor, transformer, lamp বা converter-এ কিছু Energy heat, friction, sound বা magnetic loss হিসেবে নষ্ট হয়, তাই Efficiency সাধারণত 100%-এর কম। একই useful output-এর জন্য Efficiency বেশি হলে প্রয়োজনীয় input এবং running cost কম হয়।',example:'Motor 1000 W input নিয়ে 800 W mechanical output দিলে Efficiency = 800/1000 × 100% = 80%। বাকি 200 W প্রধানত heat, friction ও magnetic loss হিসেবে বের হয়। উন্নত bearing, ভালো conductor ও সঠিক maintenance loss কমাতে পারে।',remember:'Input = Useful Output + Loss; Higher Efficiency → Same Output-এর জন্য Lower Input।'},
{concept:'Energy Consumption ও Billing হিসাব করতে প্রতিটি appliance-এর Power-কে kW-এ এবং operating time-কে hour-এ নিয়ে E = Pt ব্যবহার করতে হয়। Energy meter-এর final reading থেকে initial reading বাদ দিলে billing period-এর kWh পাওয়া যায়। Basic energy charge হলো consumed kWh × tariff rate; তবে fixed charge, demand charge, tax বা slab rate আলাদাভাবে যোগ হতে পারে।',example:'1.5 kW heater প্রতিদিন 2 ঘণ্টা করে 30 দিন চললে consumption = 1.5 × 2 × 30 = 90 kWh। Rate 8 টাকা/kWh হলে শুধু energy charge 720 টাকা; বাস্তব bill-এ এলাকার current tariff অনুযায়ী অন্য charge যোগ হতে পারে।',remember:'Consumption = Final Reading − Initial Reading; Energy Charge = kWh × Rate।'},
{concept:'Power ও Energy-এর ধারণা equipment selection, cable ও protection sizing, motor operation, lighting, solar system, battery backup এবং Energy management-এ সরাসরি ব্যবহৃত হয়। Power rating বলে system তাৎক্ষণিক load সামলাতে পারবে কি না; stored Energy বলে কতক্ষণ load চালানো যাবে। বাস্তবে conversion loss, starting surge এবং safety margin-ও ধরতে হয়।',example:'2.4 kWh usable battery ideal অবস্থায় 600 W বা 0.6 kW load প্রায় 2.4/0.6 = 4 ঘণ্টা চালাতে পারে। কিন্তু inverter loss ও battery limit থাকলে actual backup time কম হবে। একইভাবে generator বা inverter-এর Power capacity total running load ও motor surge অনুযায়ী নির্বাচন করতে হয়।',remember:'Power Rating → Load Capacity; Energy Capacity → Runtime; Practical Design → Loss + Surge + Safety Margin।'}],
4:[
{concept:'Electric Circuit হলো source, conductor, load, control ও protection device-এর এমন সংযোগ যেখানে electrical energy source থেকে load-এ পৌঁছাতে পারে। Current চলার জন্য Voltage source এবং সম্পূর্ণ conducting path দুটোই দরকার। Source energy দেয়, wire পথ তৈরি করে, load সেই energy-কে light, heat বা motion-এ convert করে। Switch path নিয়ন্ত্রণ করে এবং fuse বা breaker abnormal Current হলে circuit বিচ্ছিন্ন করে।',example:'Battery, switch, fuse ও lamp series path-এ যুক্ত করলে switch বন্ধ অবস্থায় complete circuit তৈরি হয়। Battery Potential Difference দেয়, wire দিয়ে Current চলে এবং lamp আলো দেয়। Switch খুললে path ভেঙে গিয়ে lamp বন্ধ হয়।',remember:'Circuit = Source + Conducting Path + Load; Control ও Protection প্রয়োজন অনুযায়ী যোগ হয়।'},
{concept:'Open Circuit-এ conducting path কোথাও বিচ্ছিন্ন থাকে, তাই ideal অবস্থায় continuous Current শূন্য। তবে open point-এর দুই পাশে Voltage থাকতে পারে। তাই Current না চললেও circuit নিরাপদ বা de-energized ধরে নেওয়া যাবে না। Open switch ইচ্ছাকৃত হতে পারে; broken wire, loose terminal, blown fuse বা burned filament অনিচ্ছাকৃত open fault তৈরি করে।',example:'Room light-এর switch OFF করলে contact আলাদা হয় এবং Current বন্ধ হয়। আবার fuse পুড়ে গেলে switch ON থাকলেও lamp জ্বলে না। De-energized circuit-এ continuity test দিয়ে broken path খোঁজা যায়; energized testing কেবল প্রশিক্ষিত ব্যক্তি নিরাপদ পদ্ধতিতে করবেন।',remember:'Open Path → I = 0; কিন্তু open point-এ Voltage থাকতে পারে।'},
{concept:'Closed Circuit-এ source থেকে load হয়ে source-এ ফেরার complete conducting path থাকে। Source Voltage প্রয়োগ করলে finite Resistance-এর মধ্য দিয়ে Current চলে এবং load কাজ করে। Ideal closed switch-এর Resistance প্রায় zero ও Voltage drop খুব কম। তবে normal Closed Circuit-এর মধ্যে intended load থাকে; abnormal low-resistance bypass হলে সেটি Short Circuit।',example:'Torch-এর switch ON করলে battery, switch ও bulb-এর path সম্পূর্ণ হয়। I = V/R অনুযায়ী Current চলে এবং bulb জ্বলে। Switch OFF করলে একই circuit Open Circuit হয়ে যায়।',remember:'Closed Path + Applied Voltage + Finite Resistance → Normal Current Flow।'},
{concept:'Short Circuit হলো different potential-এর pointগুলোর মধ্যে unintended খুব কম Resistance-এর path। Ohm\'s Law অনুযায়ী R খুব কম হলে Current অনেক বেড়ে যেতে পারে। Practical Fault Current source impedance, cable impedance ও system impedance দ্বারা সীমিত হলেও conductor heating, arc, fire ও equipment damage ঘটাতে পারে। Fuse বা circuit breaker উপযুক্ত interrupting capacity নিয়ে fault বিচ্ছিন্ন করে।',example:'Damaged insulation-এর কারণে phase ও neutral conductor স্পর্শ করলে load bypass হয়ে high Fault Current তৈরি হতে পারে। Ammeter-এর internal Resistance খুব কম, তাই সেটিকে source-এর across connect করলে বিপজ্জনক short তৈরি হতে পারে।',remember:'Short Circuit → Low-Impedance Fault Path; Ammeter → কখনো source-এর across নয়।'},
{concept:'Series Circuit-এ সব component end-to-end যুক্ত হয়ে একটিমাত্র Current path তৈরি করে। তাই I total = I₁ = I₂ = ...। Total Resistance সরাসরি যোগ হয় এবং source Voltage componentগুলোর Resistance অনুযায়ী ভাগ হয়। একই Current চলায় বড় Resistance-এর Voltage drop বেশি। কোনো একটি component open হলে সম্পূর্ণ series path বন্ধ হয়।',example:'2 Ω, 3 Ω ও 5 Ω series-এ হলে R total = 10 Ω। 20 V source দিলে Current 2 A এবং Voltage drops হয় 4 V, 6 V ও 10 V; যোগফল 20 V। LED-এর সঙ্গে current-limiting resistor একটি পরিচিত series application।',remember:'Series → One Path, Same Current; R total = R₁ + R₂ + ...।'},
{concept:'Parallel Circuit-এ প্রতিটি branch একই দুই node-এর মধ্যে যুক্ত থাকে, তাই সব branch-এর Voltage সমান। Current branchগুলোর Resistance অনুযায়ী ভাগ হয় এবং I total = I₁ + I₂ + ...। বেশি conducting path যোগ হওয়ায় equivalent Resistance smallest branch Resistance-এর চেয়েও কম হয়। একটি branch open হলেও অন্য complete branchগুলো চলতে পারে।',example:'6 Ω ও 3 Ω parallel-এ 12 V দিলে দুই branch-এই 12 V থাকে। Currents হয় 2 A ও 4 A, total 6 A এবং equivalent Resistance 2 Ω। বাসার lamp ও socket parallel-এ থাকে যাতে rated Voltage ও independent control পাওয়া যায়।',remember:'Parallel → Same Two Nodes, Same Voltage; Total Current = Branch Currents-এর যোগফল।'},
{concept:'Series-Parallel Circuit-এ কিছু component same Current path share করে এবং কিছু component same two nodes share করে। Analysis-এর সময় প্রথমে সবচেয়ে সহজ series বা parallel group-এর equivalent Resistance বের করে network replace করতে হয়। এভাবে total Resistance ও source Current বের করে reverse direction-এ branch Voltage ও Current হিসাব করা হয়।',example:'4 Ω resistor series-এ এবং 6 Ω ও 3 Ω parallel group হলে parallel equivalent 2 Ω, তাই total 6 Ω। 12 V source-এ total Current 2 A; series resistor-এ 8 V drop এবং parallel branch দুটিতে 4 V থাকে।',remember:'Identify → Reduce → Total Current → Work Backward → Verify।'},
{concept:'Series ও Parallel connection-এর মূল পার্থক্য topology-তে। Series-এ one path, same Current, divided Voltage এবং added Resistance থাকে। Parallel-এ multiple paths, same Voltage, divided Current এবং lower equivalent Resistance থাকে। Series path-এর একটি open সব load বন্ধ করতে পারে; parallel branch-এর open সাধারণত শুধু সেই branch-কে প্রভাবিত করে।',example:'পুরোনো series decorative light string-এর একটি lamp open হলে পুরো string বন্ধ হতে পারে। Household wiring parallel হওয়ায় একটি lamp নষ্ট হলেও অন্য lamp ও appliance চলতে পারে। তবে নতুন parallel load যোগ করলে source-এর total Current বাড়ে।',remember:'Series → Same I; Parallel → Same V; connection diagram দেখে সিদ্ধান্ত নিতে হবে, physical position দেখে নয়।'},
{concept:'Practical system-এ Series, Parallel ও Series-Parallel arrangement একসঙ্গে ব্যবহৃত হয়। Household load parallel, load switch series, measurement instrument connection নির্দিষ্ট এবং protection normal Current path-এ থাকে। Battery series করলে Voltage বাড়ে; compatible cell parallel করলে capacity ও current capability বাড়তে পারে। Design-এ rating, cable size, Voltage drop, Fault Current, protection ও applicable code বিবেচনা করতে হয়।',example:'Distribution board থেকে আলাদা parallel lighting ও socket branch যায়; প্রতিটি branch-এ breaker series protection দেয়। Ammeter load-এর series-এ, Voltmeter measurement point-এর parallel-এ এবং Ohmmeter de-energized circuit-এ ব্যবহার করা হয়।',remember:'Ammeter → Series; Voltmeter → Parallel; Ohmmeter/Continuity → Power OFF ও safe isolation।'}],
6:[
{concept:'Kirchhoff’s Current Law বা KCL হলো charge conservation-এর circuit form। কোনো Node-এ যত Current প্রবেশ করে, ঠিক তত Current বের হয়; তাই algebraic sum শূন্য। Equation লেখার আগে প্রতিটি branch Current-এর reference direction স্থির করতে হয়। সমাধানে Current negative হলে calculation ভুল নয়—actual direction অনুমানের বিপরীত।',example:'একটি node-এ 5 A ঢুকছে এবং দুই branch দিয়ে 2 A ও I বের হচ্ছে। KCL অনুযায়ী 5 = 2 + I, তাই I = 3 A।',remember:'Node-এ Incoming Current = Outgoing Current; ΣI = 0।'},
{concept:'Kirchhoff’s Voltage Law বা KVL হলো energy conservation-এর circuit form। একটি closed Loop সম্পূর্ণ ঘুরে সব Voltage rise ও drop algebraic signসহ যোগ করলে ফল শূন্য হয়। Loop ঘোরার direction এবং resistor ও source-এর polarity শুরুতেই নির্ধারণ করলে sign error কমে।',example:'12 V source ও series-এ 4 V এবং 8 V drop থাকলে KVL: +12 − 4 − 8 = 0। অর্থাৎ source যে energy দেয়, loads মোট সেই energy গ্রহণ করে।',remember:'Closed Loop-এ ΣV = 0; Voltage Rise = মোট Voltage Drop।'},
{concept:'Node হলো দুই বা ততোধিক element terminal-এর common connection point। Branch হলো দুই Node-এর মাঝের এমন path যেখানে একটি বা একাধিক element থাকে এবং একই branch Current চলে। Essential Node-এ তিন বা ততোধিক branch যুক্ত থাকে। Circuit topology বোঝার জন্য physical drawing নয়, electrical connection অনুসরণ করতে হয়।',example:'একটি junction থেকে তিনটি resistor আলাদা পথে গেলে junctionটি essential node এবং প্রতিটি resistor path একটি branch। একই wire দিয়ে যুক্ত সব ideal point একই node ধরা হয়।',remember:'Node = Common Connection; Branch = দুই Node-এর মাঝের Current Path।'},
{concept:'Loop হলো circuit-এর যেকোনো closed path যা একই node একবারের বেশি অতিক্রম করে না। Mesh হলো planar circuit-এর এমন smallest loop যার ভেতরে আর কোনো loop নেই। সব Mesh Loop, কিন্তু সব Loop Mesh নয়। KVL যেকোনো closed loop-এ প্রয়োগ করা যায়; Mesh Analysis বিশেষভাবে planar circuit-এর meshগুলো ব্যবহার করে।',example:'দুটি পাশাপাশি rectangular loop থাকলে প্রত্যেক ছোট rectangle একটি mesh; দুইটিকে ঘিরে বাইরের বড় closed path একটি loop হলেও mesh নয়।',remember:'Mesh = Smallest Loop; সব Mesh Loop, সব Loop Mesh নয়।'},
{concept:'KCL দিয়ে DC Circuit Analysis করতে সাধারণত একটি reference node নির্বাচন করে unknown node voltage ধরা হয়। Ohm’s Law দিয়ে প্রতিটি branch Current-কে node voltage-এর মাধ্যমে প্রকাশ করে node-এ KCL equation লেখা হয়। Equation solve করে node voltage এবং পরে branch current নির্ণয় করা যায়।',example:'একটি node V থেকে 2 Ω ও 4 Ω resistor ground-এ এবং 6 A source node-এ current দিলে KCL: V/2 + V/4 = 6। তাই 3V/4 = 6 এবং V = 8 V। Branch currents 4 A ও 2 A।',remember:'Node বাছুন → Current direction ধরুন → I=(V₁−V₂)/R → KCL solve করুন।'},
{concept:'KVL দিয়ে DC Circuit Analysis করতে independent loop বা mesh নির্বাচন করে loop-current direction ধরা হয়। প্রতিটি source rise ও resistor drop-এর sign লিখে KVL equation তৈরি করা হয়। Shared resistor থাকলে voltage drop সংশ্লিষ্ট mesh currents-এর difference দিয়ে প্রকাশ করতে হয়।',example:'10 V source এবং 2 Ω ও 3 Ω series resistor-এর loop-এ KVL: 10 − 2I − 3I = 0। তাই I = 2 A; drops 4 V ও 6 V, যাদের যোগফল 10 V।',remember:'Loop direction → Polarity → ΣV=0 → Equation solve → Result verify।'},
{concept:'Kirchhoff’s Laws complex network design, PCB troubleshooting, automotive wiring, battery system, sensor network ও power distribution analysis-এ ব্যবহৃত হয়। KCL abnormal current path শনাক্ত করতে এবং KVL unexpected voltage drop বা open connection খুঁজতে সাহায্য করে। Practical measurement-এর আগে safe isolation ও instrument rating নিশ্চিত করতে হয়।',example:'একটি distribution node-এর measured incoming current ও outgoing branch currents না মিললে leakage, wiring error বা measurement সমস্যা সন্দেহ করা যায়। Closed loop-এ source voltage ও measured drops না মিললে loose connection বা hidden resistance থাকতে পারে।',remember:'KCL দিয়ে Current balance, KVL দিয়ে Voltage balance; শেষে Ohm’s Law ও Power balance দিয়ে যাচাই।'}],
7:[
{concept:'Network Theorem হলো জটিল linear DC circuit-কে এমন সহজ equivalent model-এ প্রকাশ করার পদ্ধতি, যাতে নির্দিষ্ট terminal বা load-এর Voltage–Current আচরণ অপরিবর্তিত থাকে। কোন theorem ব্যবহার হবে তা নির্ভর করে লক্ষ্যটির ওপর—আলাদা source-এর প্রভাব, একটি load port, maximum power, নাকি এমন resistor network যা সরাসরি series-parallel করা যায় না।',example:'একটি বড় battery-resistor network থেকে শুধু একটি sensor-এর current জানতে হলে পুরো network বারবার solve না করে sensor terminal-এ Thevenin equivalent তৈরি করা যায়। এরপর sensor Resistance বদলালেও একটি সহজ series circuit solve করলেই হবে।',remember:'প্রথমে লক্ষ্য ও terminal ঠিক করুন; তারপর সবচেয়ে কম ও সহজ equation দেয় এমন theorem বেছে নিন।'},
{concept:'Superposition Theorem-এ একটি করে independent source active রেখে অন্য independent source-গুলো zero করা হয়। Ideal Voltage source zero করলে short circuit, Ideal Current source zero করলে open circuit হয়; কিন্তু dependent source সবসময় active থাকে। প্রতিটি source-এর কারণে পাওয়া Voltage বা Current signসহ algebraic যোগ করলে total response পাওয়া যায়।',example:'দুটি source-এর কারণে একটি branch-এ প্রথম source একা 3 A ডানদিকে এবং দ্বিতীয় source একা 1 A বামদিকে তৈরি করলে, ডানদিক positive ধরে total current = 3 − 1 = 2 A ডানদিকে। পৃথক power যোগ করা যাবে না; total current থেকে শেষে power হিসাব করতে হবে।',remember:'এক source করে চালান → response-এর sign রাখুন → শেষে Voltage/Current যোগ করুন; Power সরাসরি superimpose নয়।'},
{concept:'Thevenin’s Theorem অনুযায়ী যেকোনো linear two-terminal network-কে একটি Vth source ও series Rth দিয়ে প্রতিস্থাপন করা যায়। Load খুলে terminal-এর open-circuit Voltage হলো Vth। Independent source deactivate করে terminal থেকে দেখা Resistance হলো Rth; dependent source থাকলে test source পদ্ধতি ব্যবহার করা নিরাপদ।',example:'Vth = 12 V এবং Rth = 3 Ω হলে RL = 9 Ω সংযোগে load current IL = 12/(3+9) = 1 A এবং load Voltage VL = 9 V। একই port-এ অন্য RL বসালে শুধু এই ছোট equivalent circuit solve করতে হবে।',remember:'Load খুলুন → Vth = Voc বের করুন → Rth দেখুন → load পুনরায় যুক্ত করে ফল নির্ণয় করুন।'},
{concept:'Norton’s Theorem একই linear two-terminal network-কে IN Current source এবং parallel RN দিয়ে প্রকাশ করে। Terminal short করে পাওয়া Current হলো IN = Isc এবং RN = Rth। Thevenin ও Norton form আলাদা দেখতে হলেও একই load দিলে একই terminal Voltage ও Current দেয়।',example:'Vth = 10 V এবং Rth = 5 Ω হলে equivalent Norton current IN = Vth/Rth = 2 A এবং RN = 5 Ω। 5 Ω load দিলে current division অনুযায়ী load current 1 A—Thevenin form দিয়েও একই ফল পাওয়া যায়।',remember:'IN = Isc, RN = Rth; Vth = INRN এবং IN = Vth/Rth।'},
{concept:'Resistive DC circuit-এ load সর্বোচ্চ Power পায় যখন RL = Rth। এই অবস্থায় load Voltage Vth/2 এবং maximum Power Pmax = Vth²/(4Rth)। তবে load ও source-equivalent Resistance সমান Power loss করে বলে efficiency মাত্র 50%; তাই maximum power মানেই maximum efficiency নয়।',example:'Vth = 20 V এবং Rth = 5 Ω হলে maximum power-এর জন্য RL = 5 Ω। Current = 20/(5+5) = 2 A এবং load power = I²RL = 20 W, যা 20²/(4×5) = 20 W-এর সমান।',remember:'Maximum Power: RL = Rth; Pmax = Vth²/(4Rth); simple resistive model-এ efficiency = 50%।'},
{concept:'Source Transformation-এ Vs Voltage source ও series R-কে Is = Vs/R Current source ও একই parallel R-তে বদলানো হয়, অথবা উল্টোটি করা হয়। শুধু সঠিক source–Resistance pair transform করতে হবে এবং terminal polarity ও current direction ঠিক রাখতে হবে।',example:'12 V source-এর সঙ্গে series 6 Ω থাকলে equivalent current source 12/6 = 2 A এবং তার parallel Resistance 6 Ω। যেকোনো একই external load দুই model-এই একই terminal result পাবে।',remember:'Voltage form: Vs series R; Current form: Is parallel R; Resistance-এর মান বদলায় না।'},
{concept:'Delta (Δ) network সরাসরি series-parallel না হলে তাকে Star (Y)-তে বদলালে simplification সহজ হতে পারে। প্রতিটি Y arm = ওই terminal-এ যুক্ত দুই Δ Resistance-এর product ÷ তিনটি Δ Resistance-এর sum। Terminal label ভুল হলে পুরো conversion ভুল হবে।',example:'Balanced Delta-র প্রতিটি Resistance 9 Ω হলে প্রতিটি Star arm = (9×9)/(9+9+9) = 3 Ω। অর্থাৎ balanced ক্ষেত্রে RY = RΔ/3।',remember:'Δ→Y: adjacent দুই Δ-এর গুণফল ÷ সব Δ-এর যোগফল; আগে a, b, c label করুন।'},
{concept:'Star (Y) network-কে Delta (Δ)-তে বদলাতে S = RaRb + RbRc + RcRa হিসাব করা হয়। প্রতিটি Delta side = S ÷ সেই side-এর বিপরীত Star arm। Balanced network-এ প্রতিটি Delta Resistance সংশ্লিষ্ট Star Resistance-এর তিন গুণ।',example:'Balanced Star-র প্রতিটি arm 4 Ω হলে equivalent Delta-র প্রতিটি side = 3×4 = 12 Ω। General formula-তেও S = 4×4 + 4×4 + 4×4 = 48 এবং 48/4 = 12 Ω।',remember:'Y→Δ: pairwise product-গুলোর sum ÷ opposite Y arm; balanced হলে RΔ = 3RY।'},
{concept:'Practical circuit simplification শুরু হয় required quantity ও load port চিহ্নিত করে। এরপর direct series-parallel reduction, source transformation, Δ–Y, Superposition অথবা Thevenin/Norton—যে পদ্ধতিতে কম equation লাগে সেটি ব্যবহার করা হয়। শেষে original circuit-এর polarity, KCL, KVL ও Power balance দিয়ে ফল যাচাই করতে হয়।',example:'একটি bridge circuit-এ মাঝের resistor থাকার কারণে direct series-parallel সম্ভব না হলে আগে একটি Δ অংশকে Y-তে বদলানো যায়। নতুন circuit-এ series ও parallel combination তৈরি হলে সেগুলো reduce করে load current বের করা সহজ হয়।',remember:'Define → Label → Simplify → Solve → KCL/KVL/Power দিয়ে Verify।'},
{concept:'Network Theorems বাস্তবে battery model, power supply regulation, sensor loading, audio/communication load matching, bridge measurement এবং fault diagnosis-এ ব্যবহৃত হয়। Equivalent model calculation কমায়, কিন্তু component rating, nonlinearity, temperature change ও safety limitation আলাদাভাবে বিবেচনা করতে হয়।',example:'একটি battery-কে ideal Vth ও internal Rth দিয়ে model করলে load current বাড়ার সঙ্গে terminal Voltage কেন কমে তা বোঝা যায়। আবার sensor input Resistance কম হলে source-এর ওপর loading বাড়ে—Thevenin model দিয়ে সেই measurement error দ্রুত অনুমান করা যায়।',remember:'Equivalent circuit terminal behavior বোঝায়; বাস্তব rating, safety ও model limitation বাদ দেয় না।'}],
8:[
{concept:'Capacitor হলো দুইটি conductive plate ও মাঝখানের insulating dielectric দিয়ে তৈরি energy-storage component। Source যুক্ত হলে এক plate-এ positive এবং অন্য plate-এ negative charge জমে Electric Field তৈরি হয়। Capacitor-এর Voltage হঠাৎ বদলাতে পারে না; constant DC-তে অনেক সময় পরে ideal Capacitor দিয়ে Current শূন্য হয়ে যায়, তাই সেটি open circuit-এর মতো আচরণ করে।',example:'Phone charger-এর output Capacitor rectifier pulse-এর মাঝখানে load-কে energy দিয়ে ripple কমায়। Supply খুলে ফেললেও Capacitor কিছু সময় charge ধরে রাখতে পারে, তাই terminal নিরাপদ ধরে নেওয়া যাবে না।',remember:'Capacitor Electric Field-এ energy রাখে; Voltage continuous; DC final state-এ ideal C open।'},
{concept:'Capacitance বোঝায় প্রতি Volt-এ Capacitor কত charge রাখতে পারে: C=Q/V। Parallel-plate model-এ C=εA/d; অর্থাৎ plate area বা dielectric permittivity বাড়লে C বাড়ে, separation বাড়লে C কমে। Unit Farad, তবে বাস্তবে µF, nF ও pF বেশি ব্যবহৃত হয়।',example:'10 µF Capacitor-এ 12 V দিলে Q=CV=10×10⁻⁶×12=120 µC charge জমে। একই geometry-তে বেশি permittivity-এর dielectric দিলে বেশি charge রাখা সম্ভব।',remember:'C=Q/V; C=εA/d; বড় A ও ε → বড় C, বড় d → ছোট C।'},
{concept:'Capacitor type নির্বাচন শুধু Capacitance দেখে করা যায় না। Ceramic high-frequency bypass-এর জন্য, Electrolytic বড় Capacitance ও DC filtering-এর জন্য, Film stability ও pulse duty-এর জন্য, Mica precision RF-এর জন্য এবং Supercapacitor স্বল্প সময়ের energy backup-এর জন্য ব্যবহৃত হয়। Polarized type-এ polarity ভুল হলে failure হতে পারে।',example:'Power-supply bulk filtering-এ Electrolytic Capacitor ব্যবহার হলেও microcontroller pin-এর কাছে ছোট Ceramic Capacitor বসানো হয়। দুটির কাজ ও frequency behavior আলাদা, তাই একটি দিয়ে অন্যটির সব কাজ হয় না।',remember:'Value + Voltage + Polarity + ESR + Ripple Current + Temperature দেখে Capacitor বাছুন।'},
{concept:'Parallel Capacitor-গুলোর Voltage একই এবং তাদের Capacitance সরাসরি যোগ হয়। Series Capacitor-এ ideal charge magnitude একই, reciprocal formula ব্যবহার হয় এবং equivalent value সবচেয়ে ছোট Capacitor-এর চেয়েও কম। Series-এ ছোট Capacitance-এর ওপর বেশি Voltage পড়ে।',example:'6 µF ও 3 µF Parallel করলে 9 µF, কিন্তু Series করলে (6×3)/(6+3)=2 µF। Practical Series bank-এ leakage difference-এর কারণে Voltage অসম হতে পারে, তাই balancing resistor প্রয়োজন হতে পারে।',remember:'Capacitor: Parallel-এ direct sum; Series-এ reciprocal sum; ছোট Series C-তে বড় Voltage।'},
{concept:'Inductor সাধারণত coil আকারের conductor; Current চললে Magnetic Field তৈরি করে এবং সেখানে energy জমা রাখে। Current বদলালে changing Flux Linkage থেকে self-induced EMF তৈরি হয়, যা Lenz’s Law অনুযায়ী change-কে oppose করে। Ideal Inductor-এর Current হঠাৎ বদলাতে পারে না এবং constant DC final state-এ এটি short circuit-এর মতো আচরণ করে।',example:'Relay coil energize করলে Current ধীরে বাড়ে ও magnetic force armature টানে। Switch খুললে coil আগের Current ধরে রাখতে চায়, তাই protection না থাকলে high Voltage তৈরি হতে পারে।',remember:'Inductor Magnetic Field-এ energy রাখে; Current continuous; DC final state-এ ideal L short।'},
{concept:'Inductance হলো changing Current-এর বিরুদ্ধে coil কতটা induced Voltage তৈরি করে তার measure। vL=L(di/dt), তাই একই L-তে Current যত দ্রুত বদলাবে Voltage তত বেশি হবে। Linear model-এ L=NΦ/I; turn, core permeability ও area বাড়ালে সাধারণত L বাড়ে।',example:'0.5 H coil-এর Current 0.2 s-এ 4 A বদলালে induced Voltage magnitude 0.5×4/0.2=10 V। Current খুব দ্রুত interrupt হলে di/dt বড় হওয়ায় Voltage অনেক বেশি হতে পারে।',remember:'L-এর unit Henry; vL=L(di/dt); দ্রুত Current change → বড় induced Voltage।'},
{concept:'Air-core Inductor saturation এড়ায় ও RF-এ উপযোগী। Iron core low-frequency-তে বেশি Inductance দেয়, Ferrite high resistivity-এর কারণে high-frequency switching-এ Eddy Current কমায়, Powdered Iron DC bias-এ energy storage-এ উপযোগী এবং Toroidal core magnetic leakage কমাতে সাহায্য করে।',example:'Phone charger-এর switching converter-এ Ferrite power Inductor দেখা যায়। Rating-এ শুধু L নয়—RMS Current, saturation Current, DC Resistance, core loss ও temperature rise পরীক্ষা করতে হয়।',remember:'Core বাছুন frequency ও energy অনুযায়ী; Current rating এবং saturation আলাদাভাবে দেখুন।'},
{concept:'Mutual coupling negligible হলে Series Inductor-গুলোর L সরাসরি যোগ হয় এবং Parallel Inductor-এ reciprocal sum লাগে। Coil কাছাকাছি বা একই core-এ থাকলে shared Flux থেকে Mutual Inductance তৈরি হয়; তখন simple formula যথেষ্ট নয় এবং winding orientation/dot convention বিবেচনা করতে হয়।',example:'6 mH ও 3 mH uncoupled Inductor Series-এ 9 mH, Parallel-এ 2 mH। কিন্তু একই magnetic core-এ wound হলে equivalent value coupling-এর কারণে এর চেয়ে আলাদা হতে পারে।',remember:'Uncoupled L: Series direct sum, Parallel reciprocal sum; coupling থাকলে নতুন analysis দরকার।'},
{concept:'Capacitor-এর Electric Field energy WC=½CV² এবং Inductor-এর Magnetic Field energy WL=½LI²। Formula-তে Voltage বা Current square হওয়ায় এগুলো দ্বিগুণ করলে energy চারগুণ হয়। Supply OFF হলেও stored energy থাকতে পারে।',example:'100 µF Capacitor 20 V-তে 0.02 J energy রাখে। 0.2 H Inductor 3 A-তে 0.9 J রাখে। Capacitor নিরাপদ discharge path এবং Inductor Current-এর জন্য flyback/snubber path না থাকলে shock বা switching damage হতে পারে।',remember:'C: ½CV²; L: ½LI²; double V বা I → four times energy।'},
{concept:'RC Circuit-এ resistor Capacitor-এর charging/discharging Current সীমিত করে এবং response speed নির্ধারণ করে। Initially uncharged C-এর Voltage 0 থেকে final value-এর দিকে exponentialভাবে বাড়ে; Current প্রথমে V/R, পরে কমে শূন্যের দিকে যায়। General analysis-এ initial Voltage, final Voltage ও τ=RthC বের করতে হয়।',example:'Power-on reset Circuit-এ Capacitor Voltage ধীরে বাড়ে। R বা C বাড়ালে Time Constant বাড়ে এবং reset delay দীর্ঘ হয়। Capacitor Voltage-কে straight line ধরে হিসাব করলে ভুল হবে।',remember:'RC: vC continuous; charging-এ vC rises, i falls; τ=RthC।'},
{concept:'RL Circuit-এ Inductor Current change oppose করে। Initially unenergized coil-এ switch ON করার মুহূর্তে Current zero থেকে শুরু করে final V/R-এর দিকে exponentialভাবে বাড়ে; একই সময়ে Inductor Voltage source value থেকে zero-এর দিকে কমে। Time Constant τ=L/Rth।',example:'Contactor coil ON করলে magnetic Current instantaneously final value হয় না। OFF করার সময় flyback diode বা rated suppression network coil energy-কে নিরাপদ পথে dissipate করে switch-এর ওপর high Voltage কমায়।',remember:'RL: iL continuous; energizing-এ i rises, vL falls; τ=L/Rth।'},
{concept:'Initially uncharged Capacitor charging-এর সময় vC=V(1−e⁻ᵗ/τ), আর V₀ থেকে discharge হলে vC=V₀e⁻ᵗ/τ। এক Time Constant-এ মোট পরিবর্তনের 63.2% সম্পন্ন হয় এবং 36.8% বাকি থাকে; প্রায় 5τ-তে response practically complete ধরা হয়।',example:'R=100 kΩ ও C=10 µF হলে τ=1 s। Charging-এ 1 s পরে final Voltage-এর 63.2%, 5 s পরে প্রায় 99.3% পাওয়া যায়। Discharge-এ 1 s পরে initial Voltage-এর 36.8% থাকে।',remember:'1τ: 63.2% change complete; 5τ: প্রায় 99.3% complete।'},
{concept:'DC Transient হলো switching বা source/load change-এর পর নতুন steady state আসা পর্যন্ত Voltage ও Current-এর time-dependent behavior। 0⁻ মানে switching-এর ঠিক আগে, 0⁺ ঠিক পরে। C-এর Voltage ও L-এর Current continuity মানে initial stored energy analysis না করে এগুলোকে স্বয়ংক্রিয় zero ধরা যাবে না।',example:'Pre-switch Circuit থেকে vC(0⁻) বা iL(0⁻) বের করুন; continuity দিয়ে 0⁺ value নিন; post-switch final state, Rth ও τ বের করে x(t)=x(∞)+[x(0⁺)−x(∞)]e⁻ᵗ/τ লিখুন।',remember:'Initial → Continuity → Final → Rth → τ → Response → Verify।'},
{concept:'Time Constant first-order response কত দ্রুত initial থেকে final value-এর দিকে যাবে তা জানায়। RC-তে τ=RthC এবং RL-তে τ=L/Rth। Rth storage element-এর terminal থেকে post-switch Circuit-এ দেখা Resistance; independent source deactivate করতে হয়, dependent source active থাকে।',example:'20 kΩ ও 50 µF RC-তে τ=1 s এবং practical settling প্রায় 5 s। 2 H ও 10 Ω RL-তে τ=0.2 s এবং practical settling প্রায় 1 s। একই R বাড়ালে RC ধীর হয়, কিন্তু RL দ্রুত হয়।',remember:'RC-তে R গুণ, RL-তে R ভাগ; Rth সবসময় element-এর port থেকে দেখুন।'},
{concept:'Capacitor filtering, decoupling, timing, motor ও energy backup-এ ব্যবহৃত হয়; Inductor Current smoothing, relay/solenoid, converter ও noise choke-এ ব্যবহৃত হয়। Reliable design-এর জন্য nominal value-এর পাশাপাশি loss, thermal limit, Voltage/Current rating, tolerance, environment ও stored-energy protection দেখতে হয়।',example:'Switch-mode converter-এ Inductor switching interval-এ energy store/transfer করে এবং Capacitor output Voltage smooth করে। Saturated Inductor বা বেশি-ESR Capacitor overheating, ripple ও failure ঘটাতে পারে।',remember:'সঠিক component value যথেষ্ট নয়—rating, loss, temperature, lifetime ও protection একসঙ্গে যাচাই করুন।'}],
9:[
{concept:'Magnetism হলো moving electric charge, atomic magnetic moment এবং Magnetic Field-এর সঙ্গে সম্পর্কিত physical phenomenon। একটি সাধারণ magnet-এর North ও South—দুই pole থাকে। একই pole পরস্পরকে repel করে, বিপরীত pole attract করে। Magnet ভাঙলেও আলাদা একক pole পাওয়া যায় না; প্রতিটি অংশ আবার N ও S pole-সহ ছোট magnet হয়।',example:'Compass needle নিজে একটি ছোট Permanent Magnet। পৃথিবীর Magnetic Field-এর সঙ্গে align হওয়ায় এটি direction দেখায়। Motor, speaker ও magnetic door catch-এ attraction, repulsion বা magnetic force ব্যবহার হয়।',remember:'Like Poles → Repel; Unlike Poles → Attract; সাধারণ magnet-এর সবসময় N ও S থাকে।'},
{concept:'Magnetic Material-এর response atomic structure ও domain alignment-এর ওপর নির্ভর করে। Diamagnetic material weakly repel, Paramagnetic weakly attract এবং Ferromagnetic material শক্তভাবে magnetized হতে পারে। Soft Magnetic material সহজে magnetize-demagnetize হয়, তাই transformer/relay core-এ উপযোগী; Hard Magnetic material demagnetization প্রতিরোধ করে, তাই Permanent Magnet-এ ব্যবহৃত হয়।',example:'Transformer core-এ soft magnetic steel ব্যবহার করলে alternating field-এ কম Hysteresis Loss হয়। Neodymium alloy high-coercivity hard material হওয়ায় compact কিন্তু শক্তিশালী Permanent Magnet তৈরি করে। Ferrite-এর electrical Resistivity বেশি বলে high-frequency core-এ Eddy Current কমে।',remember:'Soft Magnetic → Changing Field/Core; Hard Magnetic → Permanent Magnet।'},
{concept:'Magnetic Field হলো এমন region যেখানে magnet, moving charge বা Current-carrying conductor magnetic force অনুভব করতে পারে। Flux Density B field-এর strength ও direction বোঝায়; unit Tesla। Field Strength H হলো magnetizing influence; unit A/m। Linear medium-এ B = μH, কিন্তু ferromagnetic core সাধারণত nonlinear এবং saturation হতে পারে।',example:'Straight wire-এ Current চললে তার চারদিকে circular field তৈরি হয়। Right-hand grip rule-এ thumb conventional Current-এর দিকে এবং curled fingers field-এর দিকে দেখায়। Coil-এর turnগুলোর field একসঙ্গে যোগ হয়ে bar magnet-এর মতো শক্তিশালী field তৈরি করে।',remember:'B → Tesla; H → A/m; Right-Hand Grip: Thumb = I, Fingers = B।'},
{concept:'Magnetic Flux Φ হলো নির্বাচিত surface-এর মধ্য দিয়ে মোট Magnetic Field passing-এর measure; unit Weber। Uniform field-এর জন্য Φ = BA cos θ, যেখানে θ field ও surface normal-এর angle। একই Flux যদি coil-এর Nটি turn link করে, Flux Linkage λ = NΦ। Flux change হলেই induction-এর মূল শর্ত তৈরি হয়।',example:'Field surface-এর perpendicular হলে Flux maximum; surface-এর parallel হলে ideal Flux zero। Transformer winding-এর বেশি turn একই core Flux link করলে বেশি Flux Linkage হয় এবং একই rate of change-এ বেশি induced EMF পাওয়া যায়।',remember:'Flux Φ → Weber; Flux Density B → Tesla; Flux Linkage λ = NΦ।'},
{concept:'Electromagnetism দেখায় Electric Current কীভাবে Magnetic Field ও force তৈরি করে। Coil-এর Magnetomotive Force MMF = NI; তাই safe limit-এর মধ্যে turn বা Current বাড়ালে magnetic effect বাড়ে। Soft Iron core ও ছোট air gap Flux ও pulling force বাড়াতে পারে, তবে saturation এবং coil heating limit মানতে হয়।',example:'Relay coil energize করলে core magnetized হয়ে armature টানে এবং contact change করে। Solenoid valve একই principle-এ plunger সরিয়ে fluid flow control করে। Current reverse করলে electromagnet-এর North-South polarity reverse হয়।',remember:'MMF = NI; Reverse Current → Reverse Polarity; rating-এর বাইরে Current নয়।'},
{concept:'Electromagnetic Induction হলো Flux Linkage change হলে conductor বা coil-এ EMF তৈরি হওয়া। Magnet বা coil নড়ানো, field strength বদলানো, area/angle বদলানো বা nearby coil-এর Current বদলানো—সবই Flux Linkage change করতে পারে। Open coil-এ induced Voltage থাকতে পারে, কিন্তু continuous Current-এর জন্য closed path প্রয়োজন।',example:'Magnet দ্রুত coil-এর ভিতর ঢোকালে meter বেশি deflection দেখায়, ধীরে ঢোকালে কম। Magnet স্থির রাখলে steady Flux-এর কারণে continuous EMF থাকে না। Transformer-এ coil স্থির থাকলেও AC primary Current core Flux বদলায় এবং secondary Voltage induce করে।',remember:'Changing Flux Linkage → Induced EMF; Closed Path হলে Induced Current।'},
{concept:'Faraday-এর First Law বলে Flux Linkage change হলে EMF induce হয়। Second Law বলে induced EMF-এর magnitude Flux Linkage কত দ্রুত বদলাচ্ছে তার সমান: e = −d(NΦ)/dt। Turn বেশি বা Flux দ্রুত change হলে EMF বেশি হয়। Negative sign magnitude নয়—Lenz’s Law অনুযায়ী polarity বোঝায়।',example:'200-turn coil-এর Flux 5 mWb থেকে 1 mWb-এ 0.02 s-এ বদলালে average EMF magnitude = 200×4×10⁻³/0.02 = 40 V। Polarity নির্ধারণে Flux direction ও increase/decrease দেখে Lenz’s Law প্রয়োগ করতে হয়।',remember:'Faraday: Rate of Flux-Linkage Change → EMF; |eavg| = N|ΔΦ|/Δt।'},
{concept:'Lenz’s Law বলে induced Current এমন direction-এ field তৈরি করে যা causing Flux change-কে oppose করে। এটি original field-কে সবসময় oppose করে না; Flux বাড়লে increase oppose করে, Flux কমলে decrease oppose করে। এই opposition conservation of energy নিশ্চিত করে এবং Faraday equation-এর negative sign দিয়ে প্রকাশ করা হয়।',example:'North Pole coil-এর দিকে এলে near face North হয়ে approach repel করে। North Pole দূরে গেলে near face South হয়ে তাকে attract করে এবং Flux decrease oppose করে। Conductive tube-এ falling magnet Eddy Current তৈরি করায় ধীরে নামে।',remember:'Lenz → Change-কে oppose করে; Faraday → Magnitude, Lenz → Direction।'},
{concept:'Electromagnetism আধুনিক energy conversion, control ও sensing-এর ভিত্তি। Motor magnetic force দিয়ে electrical-to-mechanical conversion করে; Generator motion দিয়ে Flux Linkage বদলে mechanical-to-electrical conversion করে; Transformer Mutual Induction দিয়ে AC energy transfer করে। Relay, solenoid, speaker, microphone, induction heater ও sensor একই family-এর practical application।',example:'Power station generator electricity তৈরি করে, transformer Voltage level বদলায়, motor pump চালায় এবং contactor coil motor circuit switch করে। Induction cooker Eddy Current দিয়ে vessel গরম করে; wireless charger coupled coil-এর changing field দিয়ে energy transfer করে।',remember:'Motor: Electrical→Mechanical; Generator: Mechanical→Electrical; Transformer: Mutual Induction।'}],
11:[
{concept:'Complex Number একটি Real component এবং একটি Imaginary component-কে একসঙ্গে প্রকাশ করে: z=a+jb। Electrical Engineering-এ j=√−1 ব্যবহার করা হয়, কারণ i সাধারণত Current বোঝায়। Complex Plane-এ a horizontal Real axis এবং b vertical Imaginary axis-এ থাকে।',example:'AC Impedance Z=6+j8 Ω লিখলে একই expression-এ 6 Ω Resistance ও +8 Ω Inductive Reactance রাখা যায়। তাই Voltage/Current-এর magnitude ও phase calculation compact হয়।',remember:'Complex Number = Real + Imaginary; Electrical Engineering-এ j²=−1।'},
{concept:'a+jb-তে Real Part হলো a এবং Imaginary Part হলো b—jb নয়। +jb Real axis-এর ওপরে এবং −jb নিচে থাকে। Powers of j চার ধাপ পরপর repeat করে: j, −1, −j, 1। Complex Conjugate Imaginary sign উল্টায়।',example:'z=8−j6 হলে Re(z)=8, Im(z)=−6 এবং conjugate z*=8+j6। Conjugate দিয়ে division বা Complex Power-এর calculation সহজ হয়।',remember:'Im(a+jb)=b; conjugate a+jb ↔ a−jb।'},
{concept:'Rectangular Form z=a+jb Complex quantity-কে perpendicular Real ও Imaginary component হিসেবে দেখায়। Component-এর sign দেখে quadrant জানা যায়। Addition/subtraction-এ একই ধরনের component আলাদাভাবে যোগ বা বিয়োগ করা যায় বলে এই form সবচেয়ে সুবিধাজনক।',example:'Series Impedance Z₁=5+j4 Ω ও Z₂=3−j2 Ω হলে ZT=(5+3)+j(4−2)=8+j2 Ω। Magnitude সরাসরি যোগ করলে এই ফল পাওয়া যাবে না।',remember:'Rectangular Form → a+jb; add/subtract করার সেরা form।'},
{concept:'Polar Form z=r∠θ quantity-এর magnitude r ও positive Real axis থেকে angle θ দেখায়। r=√(a²+b²), আর angle বের করার সময় a,b-এর sign দেখে correct quadrant নিতে হয়। Polar Form multiplication/division-এ সুবিধাজনক।',example:'3+j4-এর magnitude 5 এবং angle tan⁻¹(4/3)=53.13°, তাই 5∠53.13°। Calculator degree/radian mode ভুল হলে angle সম্পূর্ণ ভুল হতে পারে।',remember:'Polar Form → magnitude∠angle; quadrant এবং angle mode অবশ্যই check করুন।'},
{concept:'Rectangular থেকে Polar করতে magnitude ও correct quadrant angle বের করা হয়। Polar থেকে Rectangular করতে a=r cosθ এবং b=r sinθ ব্যবহার হয়। দুই form একই quantity বোঝায়—শুধু calculation-এর সুবিধার জন্য presentation বদলায়।',example:'−3+j4 Quadrant II-তে, তাই 5∠126.87°। আবার 10∠−30° = 10cos(−30°)+j10sin(−30°)=8.66−j5। Back-conversion দিয়ে result verify করা যায়।',remember:'a+jb→r∠θ: magnitude+quadrant; r∠θ→a+jb: cos+sin।'},
{concept:'Complex addition/subtraction সবসময় component-wise করা সহজ। Real-এর সঙ্গে Real এবং Imaginary-এর সঙ্গে Imaginary combine করতে হয়। Polar angle আলাদা হলে magnitude বা angle সরাসরি যোগ করা যাবে না; আগে Rectangular-এ convert করতে হবে।',example:'(4+j3)+(2−j5)=6−j2। Subtraction-এ bracket-এর উভয় component-এ minus প্রয়োগ করতে হবে: (8−j2)−(3+j4)=5−j6।',remember:'Polar → Rectangular → component-wise add/subtract → প্রয়োজনে Polar।'},
{concept:'Polar multiplication-এ magnitude গুণ ও angle যোগ হয়; division-এ magnitude ভাগ ও denominator angle বিয়োগ হয়। Rectangular multiplication-এ ordinary algebra এবং j²=−1 লাগে। Division-এ denominator conjugate ব্যবহার করলে denominator Real হয়।',example:'(4∠30°)(2∠−20°)=8∠10°। 100∠0° V কে 5∠30° Ω দিয়ে ভাগ করলে I=20∠−30° A—Current reference Voltage-এর থেকে 30° lag করে।',remember:'Multiply: magnitudes ×, angles +; Divide: magnitudes ÷, angles −।'},
{concept:'Phasor হলো একই frequency-এর sinusoidal quantity-এর magnitude ও phase-এর Complex representation। Common time factor ωt লেখা হয় না, কিন্তু frequency হারিয়ে যায় না—আলাদাভাবে জানা থাকতে হয়। Basic Phasor analysis sinusoidal steady-state-এর জন্য, switching transient-এর জন্য নয়।',example:'V=100∠0° V reference হলে I=5∠−30° A Current 30° lag করে। I=5∠+30° হলে Current 30° lead করে। সাধারণ power calculation-এ RMS Phasor ব্যবহৃত হয়।',remember:'Phasor = magnitude+phase at one frequency; negative relative angle lag, positive lead।'},
{concept:'Cosine reference-এ x(t)=Xm cos(ωt+φ) হলে RMS Phasor X=(Xm/√2)∠φ। Sine waveform-কে cosine reference-এ আনতে angle থেকে 90° বিয়োগ করতে হয়। RMS ও Peak convention মিশিয়ে ফেললে magnitude ও power ভুল হয়।',example:'141.4 cos(ωt+30°) V → 100∠30° V RMS। 14.14 sin(ωt−20°) A → 14.14 cos(ωt−110°), তাই 10∠−110° A RMS।',remember:'Peak→RMS: ÷√2; sine→cosine: phase−90°।'},
{concept:'Phasor addition-এর আগে frequency ও RMS/Peak convention একই কিনা নিশ্চিত করতে হয়। এরপর Rectangular component যোগ করে result Polar-এ convert করা যায়। Different angle-এর magnitude সরাসরি যোগ করলে ভুল হয়।',example:'10∠0°=10+j0 এবং 10∠90°=j10। Sum=10+j10=14.14∠45°, 20 V নয়। KCL-এ Current Phasor এবং KVL-এ Voltage Phasor একইভাবে component-wise combine হয়।',remember:'Same frequency → Rectangular components যোগ → resultant magnitude/angle।'},
{concept:'Euler’s Formula eʲθ=cosθ+j sinθ Polar/Exponential representation-কে Rectangular component-এর সঙ্গে যুক্ত করে। reʲθ এবং r∠θ একই অর্থ বহন করে। Complex exponential-এর multiplication Complex Plane-এ rotation হিসেবে বোঝা যায়।',example:'5eʲ⁶⁰°=5(cos60°+j sin60°)=2.5+j4.33। Basic AC analysis-এর জন্য advanced proof নয়, formগুলোর connection বোঝাই প্রধান।',remember:'eʲθ=cosθ+j sinθ; Exponential ↔ Polar ↔ Rectangular।'},
{concept:'AC Circuit-এ Complex Impedance Z=R+jX, যেখানে +jX Inductive ও −jX Capacitive। Series Impedance Rectangular-এ যোগ করে Polar-এ convert করা যায়; তারপর Phasor Ohm’s Law I=V/Z দিয়ে Current magnitude ও phase পাওয়া যায়।',example:'V=120∠0° V এবং Z=6+j8=10∠53.13° Ω হলে I=12∠−53.13° A। এই calculation Chapter-12-তে Reactance, RLC, Power Factor ও Power Triangle analysis-এর ভিত্তি।',remember:'Series Z add in Rectangular; V/Z calculate in Polar; result-এর phase physically interpret করুন।'}],
10:[
{concept:'Alternating Current বা AC সময়ের সঙ্গে magnitude বদলায় এবং নির্দিষ্ট interval পরপর direction reverse করে। Positive ও negative sign নির্বাচিত reference direction বোঝায়; negative value কোনো ভুল নয়। একটি positive এবং একটি negative alternation মিলে সম্পূর্ণ Cycle হয়।',example:'Power station-এর alternator AC তৈরি করে। প্রথম half-cycle-এ load current একদিকে এবং পরের half-cycle-এ বিপরীত দিকে যায়, কিন্তু heater দুই direction-এই heat তৈরি করে।',remember:'AC = Changing Magnitude + Periodic Direction Reversal।'},
{concept:'Alternating Voltage সময়ের সঙ্গে পরিবর্তিত হয় এবং terminal polarity পর্যায়ক্রমে reverse করে। Sinusoidal voltage v(t)=Vm sin(ωt+φ), যেখানে Vm peak এবং φ initial phase। Equipment-এর AC voltage rating সাধারণত RMS value বোঝায়।',example:'230 V AC outlet-এর 230 V হলো RMS, peak নয়; pure sine হলে peak প্রায় 325 V। Voltmeter parallel-এ এবং suitable category/range-এ connect করতে হয়।',remember:'Rated AC Voltage সাধারণত RMS; Voltmeter → Parallel।'},
{concept:'AC Waveform graph দেখায় Voltage বা Current time বা electrical angle-এর সঙ্গে কীভাবে বদলায়। এক Cycle 360° বা 2π radian। Zero crossing-এ value zero হয়ে sign change করে; positive ও negative half-cycle reference অনুযায়ী নির্ধারিত।',example:'Oscilloscope-এর vertical axis Voltage এবং horizontal axis Time দেখায়। Sine, square, triangular ও distorted waveform-এর shape আলাদা হওয়ায় তাদের RMS/Average factor-ও আলাদা।',remember:'1 Cycle = 360° = 2π rad; waveform shape গুরুত্বপূর্ণ।'},
{concept:'Frequency হলো প্রতি second-এ সম্পূর্ণ Cycle-এর সংখ্যা; symbol f, unit Hertz। Angular frequency ω=2πf। Frequency motor speed, transformer flux, reactance ও timing-এ সরাসরি প্রভাব ফেলে।',example:'50 Hz supply প্রতি second-এ 50 Cycle সম্পন্ন করে। 4-pole rotating field-এর synchronous speed Ns=120f/P=1500 rpm।',remember:'Frequency f → Hz; ω=2πf।'},
{concept:'Time Period T হলো এক Cycle সম্পন্ন করতে প্রয়োজনীয় সময়। T=1/f হওয়ায় Frequency বাড়লে Period কমে। 50 Hz-এ T=20 ms এবং 60 Hz-এ প্রায় 16.67 ms।',example:'Oscilloscope-এ এক Cycle 4 division এবং scale 5 ms/div হলে T=20 ms, তাই f=1/0.02=50 Hz।',remember:'T=1/f; 50 Hz → 20 ms।'},
{concept:'Amplitude বা Peak Value হলো zero reference থেকে waveform-এর সর্বোচ্চ magnitude। Symmetrical waveform-এ Peak-to-Peak value দুই Peak-এর সমান: Vpp=2Vp। Peak insulation এবং semiconductor stress নির্ধারণে গুরুত্বপূর্ণ।',example:'100 V peak sine wave-এর peak-to-peak 200 V। একই RMS হলেও high crest-factor waveform-এর peak বেশি হতে পারে।',remember:'Amplitude = Peak; Symmetrical Wave: Vpp=2Vp।'},
{concept:'RMS বা Root Mean Square হলো AC-এর effective heating value। Pure sine-এর জন্য Vrms=Vm/√2≈0.707Vm। এই factor distorted বা অন্য shape-এর waveform-এ সরাসরি ব্যবহার করা যাবে না।',example:'10 A RMS AC একটি fixed resistor-এ 10 A steady DC-এর সমান average heat তৈরি করে। 230 V RMS sine-এর peak প্রায় 325 V।',remember:'Sine RMS=0.707 Peak; rating ও heating calculation-এ RMS।'},
{concept:'Average Value নির্দিষ্ট interval-এর algebraic mean। Symmetrical sine-এর full-cycle average zero, কারণ positive ও negative area cancel করে; positive half-cycle average 0.637 Peak। Rectification করলে cancellation বন্ধ হয়ে non-zero DC component পাওয়া যায়।',example:'Full-wave rectifier negative half-কে positive দিকে উল্টে দেয়, তাই output-এর average zero থাকে না এবং DC load চালানো যায়।',remember:'Sine Full-Cycle Average=0; Half-Cycle Average=0.637 Peak।'},
{concept:'Phase waveform-এর angular position; Phase Difference একই Frequency-এর দুই waveform-এর relative displacement। আগে corresponding point-এ পৌঁছালে lead এবং পরে পৌঁছালে lag বলে। φ=(Δt/T)×360°।',example:'50 Hz-এ T=20 ms। দুই waveform-এর Δt=5 ms হলে Phase Difference 90°। Ideal resistor-এ V ও I in phase; capacitor-এ I leads এবং inductor-এ I lags।',remember:'Lead = আগে; Lag = পরে; Phase=(Δt/T)×360°।'},
{concept:'AC generation, transformer, transmission, distribution, motor, heating, lighting এবং communication-এ ব্যবহৃত হয়। Transformer Voltage বাড়িয়ে fixed power-এর Current কমাতে পারে, ফলে I²R transmission loss কমে। Power electronics AC-DC এবং DC-AC conversion নিয়ন্ত্রণ করে।',example:'Grid alternator AC তৈরি করে, step-up transformer transmission Voltage বাড়ায়, distribution transformer ব্যবহারযোগ্য level-এ নামায় এবং motor pump বা fan চালায়। Solar inverter DC-কে grid-compatible AC-তে বদলায়।',remember:'AC → Generation, Transformation, Transmission, Motors ও Power Conversion।'}],
15:[
{concept:'Transformer একটি static electromagnetic device, যা Mutual Induction দিয়ে AC energy এক circuit থেকে অন্য circuit-এ transfer করে। এটি Voltage ও Current level বদলায়, কিন্তু Frequency বদলায় না। Primary input নেয় এবং Secondary load-কে output দেয়।',example:'Power grid-এ step-up transformer transmission Voltage বাড়ায় এবং distribution transformer বাসা বা কারখানার উপযোগী level-এ নামায়।',remember:'Transformer → AC energy transfer; Frequency অপরিবর্তিত।'},
{concept:'Primary-তে AC দিলে core-এ changing Magnetic Flux তৈরি হয়। সেই Flux Secondary winding link করলে Faraday’s Law অনুযায়ী EMF induce হয়। Load connect করলে Primary অতিরিক্ত Current নেয়, যাতে Main Flux প্রায় স্থির থাকে।',example:'Secondary open থাকলেও ছোট No-Load Current core Flux ও Core Loss supply করে। Load বাড়লে Secondary এবং reflected Primary Current বাড়ে।',remember:'Changing Flux + Coupled Windings = Mutual Induction।'},
{concept:'Transformer-এর মূল অংশ হলো laminated magnetic core, Primary-Secondary winding, insulation, terminal/bushing এবং cooling system। Power-frequency core laminate করলে Eddy Current কমে। LV winding অনেক design-এ core-এর কাছে থাকে, যাতে core insulation কম লাগে।',example:'Large liquid-immersed unit-এ tank, radiator, insulating liquid ও Tap Changer থাকে; dry-type unit solid insulation ও air cooling ব্যবহার করে।',remember:'Core guides Flux; winding carries Current; insulation ও cooling নিরাপত্তা দেয়।'},
{concept:'Step-Up Voltage বাড়ায়, Step-Down কমায়। Isolation Transformer separate winding দিয়ে galvanic separation দেয়; Autotransformer shared tapped winding ব্যবহার করে এবং isolation দেয় না। CT ও VT measurement/protection-এর জন্য scaled Current বা Voltage দেয়।',example:'Substation-এ power transformer, বাড়ির supply-তে distribution transformer, panel-এ control transformer এবং relay system-এ CT/VT ব্যবহৃত হয়।',remember:'Autotransformer ≠ Isolation; energized CT Secondary open নয়।'},
{concept:'Sinusoidal core Flux-এর জন্য RMS EMF equation E=4.44fNΦm। EMF Frequency, turns ও maximum Flux-এর proportional। Fixed turns-এ Voltage বেশি বা Frequency কম হলে Flux বেড়ে saturation ও overheating হতে পারে।',example:'50 Hz, 500 turns এবং 2 mWb maximum Flux হলে E=4.44×50×500×0.002=222 V।',remember:'E=4.44fNΦm; safe operation-এ V/f গুরুত্বপূর্ণ।'},
{concept:'Ideal Transformer-এ V₂/V₁=N₂/N₁। Current ratio inverse: I₂/I₁=N₁/N₂। তাই Voltage step-up করলে একই ideal VA-তে available Current step-down হয়। Load Impedance turns ratio-এর square অনুযায়ী অন্য side-এ referred হয়।',example:'1000 primary turn, 100 secondary turn এবং 230 V input হলে ideal output 23 V।',remember:'Voltage follows turns; Current ratio inverse; Impedance ratio squared।'},
{concept:'Core Loss-এর প্রধান অংশ Hysteresis ও Eddy-Current Loss; fixed V/f-এ প্রায় constant ধরা হয়। Copper Loss winding-এর I²R এবং load Current-এর square অনুযায়ী বদলায়। Stray ও Dielectric Loss-ও practical unit-এ থাকে।',example:'Half rated Current-এ Copper Loss full-load value-এর (0.5)²=0.25 বা এক-চতুর্থাংশ হয়।',remember:'Core Loss ≈ constant; Copper Loss ∝ I²।'},
{concept:'Efficiency η=Pout/Pin×100%, যেখানে input=output+loss। Fixed V/f-এ maximum Efficiency প্রায় তখন হয় যখন variable Copper Loss constant Core Loss-এর সমান। Distribution transformer-এর varying daily load-এর জন্য All-Day Efficiency গুরুত্বপূর্ণ।',example:'9.5 kW output ও 0.5 kW total loss হলে input 10 kW এবং Efficiency 95%।',remember:'Maximum η: Copper Loss = Core Loss।'},
{concept:'Voltage Regulation No-Load থেকে specified load-এ Secondary terminal Voltage change বোঝায়। Internal Resistance ও Leakage Reactance drop সৃষ্টি করে। Lagging load সাধারণত positive regulation এবং sufficiently leading load negative regulation দিতে পারে।',example:'VNL=240 V ও VFL=230 V হলে regulation=(240−230)/230×100≈4.35%।',remember:'Regulation load magnitude, internal Impedance ও Power Factor-এর ওপর নির্ভর করে।'},
{concept:'Transformer power grid, distribution, control panel, charger, UPS, renewable energy, measurement, protection ও isolation-এ ব্যবহৃত হয়। Selection-এ kVA, Voltage, Frequency, phase, Impedance, cooling, insulation ও environment মিলাতে হয়।',example:'Solar plant-এর inverter output transformer grid Voltage-এ match করে; CT protective relay-কে scaled Current দেয়; control transformer contactor coil supply করে।',remember:'Correct rating + Protection + Grounding + Cooling + Maintenance।'}]};
const languageText={en:{book:'Book Content',subtitle:'A structured collection for Electrical Engineering learning, examinations and interview preparation.',chapters:'Chapters',topics:'Topics',side:'Book Chapters',results:'SEARCH RESULTS',all:'ALL CHAPTERS',menu:'Chapters',correct:'Correct',wrong:'Wrong',answered:'Answered',reset:'Reset Quiz',search:'Search chapter…',found:'found'},bn:{book:'বইয়ের কনটেন্ট',subtitle:'Electrical Engineering শেখা, পরীক্ষা এবং interview preparation-এর সাজানো সংগ্রহ।',chapters:'অধ্যায়',topics:'টপিক',side:'বইয়ের অধ্যায়',results:'সার্চ ফলাফল',all:'সব অধ্যায়',menu:'অধ্যায়',correct:'সঠিক',wrong:'ভুল',answered:'উত্তর দেওয়া',reset:'কুইজ রিসেট',search:'অধ্যায় খুঁজুন…',found:'টি পাওয়া গেছে'}};
banglaHelp[13]=[
{concept:'রেজোন্যান্স হলো এমন একটি নির্দিষ্ট ফ্রিকোয়েন্সির অবস্থা, যেখানে ইন্ডাক্টিভ রিঅ্যাকট্যান্স X_L এবং ক্যাপাসিটিভ রিঅ্যাকট্যান্স X_C সমান হয়। তখন ইন্ডাক্টর ও ক্যাপাসিটরের বিপরীতধর্মী প্রভাব পরস্পরকে বাতিল করে এবং সার্কিটের আচরণ প্রধানত রেজিস্ট্যান্সের ওপর নির্ভর করে।',example:'রেডিও টিউনারে অসংখ্য সিগন্যালের মধ্য থেকে একটি স্টেশনের ফ্রিকোয়েন্সি নির্বাচন করতে LC রেজোন্যান্স ব্যবহার করা হয়।',remember:'রেজোন্যান্সের মূল শর্ত: X_L = X_C; অর্থাৎ 2πfL = 1/(2πfC)।'},
{concept:'Series RLC সার্কিটে রেজোন্যান্সের সময় মোট রিঅ্যাকট্যান্স শূন্য, ইম্পিড্যান্স সর্বনিম্ন এবং কারেন্ট সর্বোচ্চ হয়। উৎসের দৃষ্টিতে সার্কিটটি resistive হওয়ায় voltage ও current একই phase-এ থাকে এবং power factor unity হয়।',example:'একটি series-tuned receiver কাঙ্ক্ষিত ফ্রিকোয়েন্সিতে বেশি কারেন্ট প্রবাহিত করে সেই সিগন্যালকে শক্তিশালীভাবে গ্রহণ করতে পারে।',remember:'Series resonance: Z সর্বনিম্ন, I সর্বোচ্চ, power factor = 1।'},
{concept:'Parallel resonance-এ inductive ও capacitive branch current বিপরীত phase-এ থেকে উৎসের কাছে প্রায় বাতিল হয়। ফলে ideal সার্কিটে input impedance সর্বোচ্চ এবং source current সর্বনিম্ন হয়, যদিও শাখাগুলোর মধ্যে বড় circulating current থাকতে পারে।',example:'টিউনড amplifier ও oscillator-এর tank circuit একটি নির্দিষ্ট ফ্রিকোয়েন্সিতে উচ্চ impedance তৈরি করে।',remember:'Parallel resonance: input Z সর্বোচ্চ, source I সর্বনিম্ন; তাই একে rejector circuit-ও বলা হয়।'},
{concept:'Resonant frequency হলো সেই ফ্রিকোয়েন্সি যেখানে X_L = X_C। Ideal RLC সার্কিটে f_r = 1/(2π√LC)। L বা C বাড়ালে resonant frequency কমে এবং যেকোনো একটির মান কমালে resonant frequency বাড়ে।',example:'L = 10 mH এবং C = 1 µF হলে সূত্রে মান বসিয়ে প্রায় 1.59 kHz resonant frequency পাওয়া যায়।',remember:'f_r, L ও C-এর বর্গমূলের ব্যস্তানুপাতিক; unit সবসময় আগে SI-তে রূপান্তর করো।'},
{concept:'Quality Factor বা Q রেজোন্যান্স কতটা তীক্ষ্ণ এবং সার্কিটে সঞ্চিত শক্তির তুলনায় কত কম শক্তি নষ্ট হচ্ছে তা নির্দেশ করে। High-Q response সরু ও তীক্ষ্ণ; low-Q response চওড়া এবং কম selective।',example:'একটি radio receiver-এর high-Q tuned circuit পাশাপাশি থাকা দুই station-কে ভালোভাবে আলাদা করতে পারে।',remember:'Q বেশি হলে সাধারণত bandwidth কম এবং selectivity বেশি হয়।'},
{concept:'Bandwidth হলো lower half-power frequency f_1 এবং upper half-power frequency f_2-এর পার্থক্য: BW = f_2 − f_1। এই দুই সীমায় power সর্বোচ্চ মানের অর্ধেক এবং amplitude সাধারণত সর্বোচ্চের প্রায় 0.707 গুণ হয়।',example:'যদি f_1 = 950 Hz এবং f_2 = 1050 Hz হয়, তবে bandwidth = 100 Hz।',remember:'Bandwidth সবসময় দুই −3 dB বা half-power frequency-এর মধ্যবর্তী পরিসর।'},
{concept:'Selectivity হলো একটি সার্কিটের কাঙ্ক্ষিত frequency বা frequency band গ্রহণ এবং পাশের অনাকাঙ্ক্ষিত frequency প্রত্যাখ্যান করার ক্ষমতা। Response যত তীক্ষ্ণ, কাছাকাছি signal আলাদা করার ক্ষমতা তত বেশি।',example:'FM receiver একটি নির্দিষ্ট station গ্রহণ করে, কিন্তু পাশের channel-এর signal কমিয়ে দেয়—এটাই selectivity-এর ব্যবহার।',remember:'উচ্চ Q → সরু bandwidth → বেশি selectivity, তবে practical loading বিবেচনা করতে হবে।'},
{concept:'Filter একটি frequency-selective circuit। এটি কিছু frequency সহজে পার হতে দেয় এবং অন্যগুলো attenuate করে। Response graph-এ passband, stopband, transition band ও cutoff frequency দেখে filter-এর কাজ বোঝা যায়।',example:'Audio system-এ bass, mid এবং treble আলাদা করতে বিভিন্ন filter ব্যবহার করা হয়।',remember:'Filter-এর নাম দেখে আগে বোঝো কোন frequency pass করে, তারপর cutoff বা band নির্ণয় করো।'},
{concept:'Low Pass Filter cutoff-এর নিচের frequency পাস করে এবং উপরের frequency কমায়। প্রথম-order RC low-pass circuit-এ output capacitor-এর ওপর নেওয়া হয় এবং f_c = 1/(2πRC)।',example:'DC power supply-এর output ripple ও sensor signal-এর high-frequency noise কমাতে low-pass filter ব্যবহৃত হয়।',remember:'RC low-pass: output C-এর ওপর; low frequency pass, high frequency attenuate।'},
{concept:'High Pass Filter cutoff-এর উপরের frequency পাস করে এবং DC ও নিচের frequency কমায়। প্রথম-order RC high-pass circuit-এ output resistor-এর ওপর নেওয়া হয়।',example:'Audio amplifier-এর coupling capacitor DC আটকে রেখে পরিবর্তনশীল audio signal পরবর্তী stage-এ পাঠায়।',remember:'RC high-pass: output R-এর ওপর; DC block, high frequency pass।'},
{concept:'Band Pass Filter কেবল lower ও upper cutoff-এর মাঝের একটি frequency band পাস করে। Center frequency-এর কাছাকাছি response সর্বোচ্চ হয়; bandwidth দুই cutoff-এর ব্যবধান।',example:'Wireless receiver নির্দিষ্ট communication channel বা microphone system নির্দিষ্ট audio range বেছে নিতে band-pass filter ব্যবহার করে।',remember:'Band-pass = মাঝের band পাস; এর বাইরে low ও high frequency attenuate।'},
{concept:'Band Stop Filter একটি নির্দিষ্ট frequency band প্রত্যাখ্যান করে কিন্তু তার নিচের ও উপরের frequency পাস করে। খুব সরু stopband হলে একে notch filter বলা হয়।',example:'Measurement system থেকে 50 Hz mains hum সরাতে 50 Hz notch filter ব্যবহার করা যায়।',remember:'Band-stop = মাঝের band বন্ধ; narrow band-stop = notch filter।'},
{concept:'রেজোন্যান্স ও filter radio tuning, communication, audio crossover, noise reduction, instrumentation, induction heating এবং power electronics-এ ব্যবহৃত হয়। বাস্তব design-এ component tolerance, coil resistance, source impedance ও load-এর প্রভাব হিসাব করা জরুরি।',example:'একটি sensor interface-এ low-pass filter noise কমায়, আর communication receiver-এর tuned circuit কাঙ্ক্ষিত carrier নির্বাচন করে।',remember:'Practical response ideal সূত্র থেকে বদলাতে পারে—calculation-এর পরে simulation বা measurement দিয়ে যাচাই করো।'}];
banglaHelp[14]=[
{concept:'Three-Phase AC System-এ একই frequency-এর তিনটি sinusoidal voltage বা current থাকে, যেগুলো পরস্পর 120° দূরে অবস্থান করে। Balanced অবস্থায় তিনটির magnitude সমান হওয়ায় মোট power প্রায় স্থির থাকে এবং motor-এ smooth torque পাওয়া যায়।',example:'বিদ্যুৎকেন্দ্র, transmission grid এবং বড় factory motor-এ Three-Phase supply ব্যবহার করা হয়। বাড়িতে সাধারণত একটি phase ব্যবহার হলেও building-এর মূল distribution Three-Phase হতে পারে।',remember:'Balanced Three-Phase = সমান magnitude + একই frequency + 120° phase difference।'},
{concept:'Alternator-এর stator-এ তিনটি winding 120 electrical degree দূরে বসানো হয়। Rotor-এর magnetic field ঘুরলে Faraday’s Law অনুযায়ী winding তিনটিতে একই frequency-এর কিন্তু 120° displaced EMF তৈরি হয়।',example:'4-pole generator 1500 rpm-এ চললে f = PN/120 = 50 Hz উৎপন্ন করে।',remember:'Rotating magnetic field + 120° spaced windings = Three-Phase voltage।'},
{concept:'Phase Sequence হলো তিন phase কোন ক্রমে positive peak বা একই reference point-এ পৌঁছায়। ABC ও ACB বিপরীত sequence; যেকোনো দুই line বদলালে sequence এবং সাধারণত motor rotation উল্টে যায়।',example:'Pump motor commissioning-এর আগে Phase Sequence Indicator দিয়ে order পরীক্ষা করা হয়, যাতে pump উল্টো দিকে না ঘোরে।',remember:'দুটি line interchange → phase sequence reverse; কাজটি অবশ্যই supply isolate করে করতে হবে।'},
{concept:'Star বা Y connection-এ তিন phase element-এর একটি করে প্রান্ত common Neutral point-এ যুক্ত থাকে। Balanced Star-এ VL = √3Vph এবং IL = Iph; neutral থাকলে line-to-neutral ও line-to-line দুই ধরনের supply পাওয়া যায়।',example:'400 V line supply-এর Star phase voltage প্রায় 400/√3 = 231 V।',remember:'Star: Voltage-এ √3, Current সমান; neutral point পাওয়া যায়।'},
{concept:'Delta connection-এ তিন phase element একটি বন্ধ triangle তৈরি করে। প্রতিটি phase সরাসরি দুই line-এর মাঝে থাকে, তাই VL = Vph; balanced অবস্থায় IL = √3Iph। Basic Delta-তে neutral থাকে না।',example:'400 V Delta motor winding-এর প্রতিটি phase 400 V পায়; phase current 10 A হলে line current প্রায় 17.32 A।',remember:'Delta: Voltage সমান, Line Current = √3 × Phase Current।'},
{concept:'Line Voltage দুই line conductor-এর মধ্যকার voltage; Phase Voltage একটি winding বা load phase-এর ওপর voltage। Star-এ phasor difference-এর কারণে line voltage phase voltage-এর √3 গুণ, কিন্তু Delta-তে দুটো সমান।',example:'415 V system-এ Star phase voltage প্রায় 240 V, আর Delta phase voltage 415 V।',remember:'Connection না জেনে কখনো Line/Phase voltage formula প্রয়োগ করো না।'},
{concept:'Line Current supply conductor দিয়ে প্রবাহিত হয়, আর Phase Current একটি phase element-এর ভেতর দিয়ে যায়। Star-এ একই current সরাসরি flow করে; Delta junction-এ দুই phase current-এর phasor difference থেকে line current তৈরি হয়।',example:'Delta phase current 12 A হলে line current √3×12 ≈ 20.78 A। Clamp Meter দিয়ে একবারে একটি line conductor মাপতে হয়।',remember:'Star: IL=Iph; Delta: IL=√3Iph। Neutral current balance ও harmonics-এর ওপর নির্ভর করে।'},
{concept:'Balanced Three-Phase real power P=√3VLILcosφ, reactive power Q=√3VLILsinφ এবং apparent power S=√3VLIL। Unbalanced load হলে প্রতিটি phase-এর power আলাদাভাবে বের করে যোগ করতে হয়।',example:'400 V, 20 A, PF 0.8 load-এর real power প্রায় √3×400×20×0.8 = 11.09 kW।',remember:'P-তে cosφ, Q-তে sinφ, S-তে কোনোটিই নয়; balanced Line formula-তে √3 থাকবে।'},
{concept:'Three-Phase system balanced load-এ প্রায় constant power দেয়, conductor material কার্যকরভাবে ব্যবহার করে এবং naturally rotating magnetic field তৈরি করে। তাই বড় motor, generator ও transformer তুলনামূলক compact ও efficient হয়।',example:'Factory pump, compressor ও conveyor-এ Three-Phase induction motor smooth torque এবং নির্ভরযোগ্য operation দেয়।',remember:'Three-Phase-এর বড় সুবিধা: conductor economy, constant power ও self-starting motor field।'},
{concept:'বাস্তবে Three-Phase system generation থেকে industrial load পর্যন্ত ব্যবহৃত হয়। নিরাপদ operation-এর জন্য load balancing, phase loss/reversal protection, correct cable rating, earthing এবং approved measurement procedure জরুরি।',example:'Building-এর single-phase load তিন phase-এ সমানভাবে ভাগ করলে neutral current, voltage unbalance ও transformer heating কমে।',remember:'Measure all three phases; neutral-কে current-free ধরে নেবে না; energized অবস্থায় phase connection বদলাবে না।'}];
banglaHelp[17]=[
{concept:'Three-Phase Induction Motor-এ stator-এর balanced তিন phase current Rotating Magnetic Field তৈরি করে। এই field rotor conductor-এ current induce করে এবং torque তৈরি হয়। Rotor সাধারণত synchronous speed-এর নিচে চলে।',example:'Factory pump, fan, compressor ও conveyor-এ robust Squirrel-Cage Induction Motor সবচেয়ে বেশি ব্যবহৃত হয়।',remember:'Stator supply নেয়; Rotor induction-এর মাধ্যমে torque তৈরি করে।'},
{concept:'Operating sequence হলো: Three-Phase supply → RMF → Rotor EMF → Rotor Current → electromagnetic torque। Rotor synchronous speed-এ পৌঁছালে relative motion ও torque শূন্য হবে, তাই slip দরকার।',example:'Load বাড়লে rotor সামান্য ধীর হয়, slip ও induced current বাড়ে এবং Motor বেশি torque তৈরি করে।',remember:'Induction torque-এর জন্য relative speed অপরিহার্য।'},
{concept:'Motor-এর প্রধান অংশ frame, laminated stator core, winding, rotor, air gap, shaft, bearing, fan ও terminal box। সঠিক alignment ও cooling machine life নির্ধারণ করে।',example:'Blocked fan বা uneven air gap overheating, noise ও vibration তৈরি করতে পারে।',remember:'Uniform air gap + sound bearing + clear airflow = reliable Motor।'},
{concept:'Stator stationary এবং সরাসরি Three-Phase supply নেয়; Rotor rotating এবং induced current বহন করে। Stator frequency f, Rotor frequency fr=sf।',example:'50 Hz Motor 4% slip-এ চললে Rotor current frequency মাত্র 2 Hz।',remember:'Stator RMF তৈরি করে; Rotor torque দেয়।'},
{concept:'Cage Rotor-এ bars ও End Rings থাকে—brush নেই, তাই maintenance কম। Slip-Ring Rotor-এ wound rotor ও rings/brushes থাকে; external resistance দিয়ে high starting torque পাওয়া যায়।',example:'Pump-এ Cage Rotor, heavy crane বা mill start-এ Slip-Ring Motor ব্যবহার হতে পারে।',remember:'Cage = simple; Slip Ring = controllable heavy start কিন্তু বেশি maintenance।'},
{concept:'120° displaced stator windings ও balanced current-এর field যোগ হয়ে constant-magnitude RMF তৈরি করে। এর speed Ns=120f/P এবং direction phase sequence-এর ওপর নির্ভর করে।',example:'50 Hz, 4-pole Motor-এর RMF speed 1500 rpm। দুই line বদলালে direction উল্টে যায়।',remember:'Frequency বাড়লে Ns বাড়ে; pole বাড়লে Ns কমে।'},
{concept:'Slip s=(Ns−N)/Ns। Standstill-এ s=1, synchronous speed-এ s=0 এবং normal motoring-এ 0<s<1। Rotor frequency fr=sf।',example:'Ns=1500 rpm, N=1440 rpm হলে slip=4% এবং 50 Hz supply-তে fr=2 Hz।',remember:'Load বাড়লে সাধারণত speed কমে ও slip বাড়ে।'},
{concept:'Torque–speed curve-এ starting torque, stable operating region, rated point ও Breakdown Torque থাকে। Load torque maximum capability ছাড়ালে Motor stall করতে পারে।',example:'Undervoltage-এ torque capability প্রায় V² অনুযায়ী কমে, ফলে loaded conveyor start নাও নিতে পারে।',remember:'Rated point Breakdown Torque-এর নিরাপদ নিচে থাকতে হবে।'},
{concept:'DOL full voltage দেয়; Star-Delta current ও torque কমায়; Soft Starter voltage ramp করে; VFD voltage ও frequency দুটো নিয়ন্ত্রণ করে; Slip-Ring Motor rotor resistance ব্যবহার করতে পারে।',example:'Small pump-এ DOL, smooth water pump start-এ Soft Starter, variable-speed fan-এ VFD উপযোগী।',remember:'Starter নির্বাচন load torque ও supply strength দেখে করতে হবে।'},
{concept:'VFD frequency বদলে synchronous speed নিয়ন্ত্রণ করে। Base speed-এর নিচে প্রায় constant V/f রাখলে air-gap flux বজায় থাকে; above base speed-এ torque capability কমে।',example:'Fan speed 50 Hz থেকে 40 Hz করলে speed কমে এবং process অনুযায়ী বড় energy saving হতে পারে।',remember:'VFD হলো speed control; Soft Starter মূলত start/stop control।'},
{concept:'Losses হলো stator copper, core, rotor copper, friction, windage ও stray loss। Rotor copper loss=sPg এবং developed mechanical power=(1−s)Pg।',example:'20 kW input ও 2 kW total loss হলে output 18 kW এবং efficiency 90%।',remember:'η=Pout/Pin×100%; loss মানেই heat বা unavailable output।'},
{concept:'Induction Motor-এর সুবিধা robust, self-starting, efficient ও low maintenance। Limitation হলো inrush current, slip, light-load poor PF এবং variable speed-এর জন্য সাধারণত VFD দরকার।',example:'General factory duty-তে Cage Motor সুবিধাজনক, কিন্তু very heavy start-এ special design বা Slip-Ring/VFD প্রয়োজন হতে পারে।',remember:'Motor suitability duty, environment ও lifecycle cost দিয়ে বিচার করো।'},
{concept:'Common fault-এর মধ্যে phase loss, overload, unbalance, low voltage, blocked cooling, bearing wear ও misalignment আছে। তিন phase-এর voltage/current তুলনা না করে diagnosis সম্পূর্ণ নয়।',example:'এক phase fuse open হলে Motor চলতে থাকলেও remaining current বেড়ে দ্রুত overheating হতে পারে।',remember:'Protection বারবার reset নয়—root cause খুঁজে বের করো।'},
{concept:'Maintenance-এর আগে supply, VFD DC link, heater, control ও mechanical energy isolate করতে হবে। Discharge time শেষে absence of voltage verify এবং automatic restart disable করতে হবে।',example:'VFD input OFF হলেও capacitor-এ hazardous voltage থাকতে পারে; manufacturer নির্দেশিত সময় অপেক্ষা ও test জরুরি।',remember:'Isolate → discharge → verify → secure → maintain।'},
{concept:'Industrial application-এ Motor নির্বাচন torque-speed curve, inertia, starting frequency, duty, enclosure, VFD compatibility ও efficiency দেখে করা হয়।',example:'Pump/fan-এ Cage+VFD, conveyor-এ controlled acceleration এবং crane-এ high starting torque ও braking দরকার।',remember:'Load requirement থেকে Motor, starter ও drive নির্বাচন শুরু করো।'}];
banglaHelp[18]=[
{concept:'Single-Phase Motor এক phase AC supply থেকে electrical energy নিয়ে shaft-এ mechanical rotation দেয়। ছোট ও মাঝারি household load-এর জন্য এটি সবচেয়ে বেশি ব্যবহৃত হয়, কারণ বাসাবাড়িতে সাধারণত Three-Phase supply থাকে না।',example:'Ceiling fan, refrigerator, washing machine, domestic water pump ও ছোট workshop machine-এ Single-Phase Motor দেখা যায়। Nameplate-এর Voltage, frequency, Current, Power ও Capacitor rating মিলিয়ে connection দিতে হয়।',remember:'Single-Phase supply সুবিধাজনক, কিন্তু Motor type ও starting system load অনুযায়ী নির্বাচন করতে হবে।'},
{concept:'Stator winding-এ AC flow করলে alternating magnetic flux তৈরি হয়। এই flux Rotor bar-এ EMF ও Current induce করে। Starting arrangement Rotor-কে একটি direction দিলে Stator Flux ও Rotor Current-এর interaction continuous torque তৈরি করে।',example:'Pump চালু হওয়ার সময় Capacitor phase shift তৈরি করে Rotor ঘোরায়; speed উঠলে forward torque dominant হয়ে Motor চলতে থাকে।',remember:'Stator Flux → Rotor EMF → Rotor Current → Torque।'},
{concept:'একটি মাত্র Single-Phase winding rotating field নয়, pulsating field তৈরি করে। Double-Revolving-Field theory অনুযায়ী এটি সমান forward ও backward field-এর সমষ্টি। Standstill-এ দুই field সমান বিপরীত torque দেয়, তাই net starting torque শূন্য।',example:'Fan Capacitor নষ্ট হলে Motor hum করতে পারে কিন্তু নিজে ঘুরতে পারে না। হাতে সামান্য ঘুরিয়ে দিলে চলা শুরু করা start-circuit fault-এর গুরুত্বপূর্ণ লক্ষণ।',remember:'Standstill-এ Tf=Tb, তাই Tstart=0; phase splitting দরকার।'},
{concept:'Motor-এর main parts হলো laminated Stator Core, Main Winding, Auxiliary Winding, Squirrel-Cage Rotor, Air Gap, Shaft, Bearing, Cooling Fan এবং starting Capacitor/switch। প্রতিটি অংশ electrical, magnetic বা mechanical কাজ করে।',example:'Bearing tight হলে shaft ঘুরতে বাধা পায়; Capacitor weak হলে phase shift কমে; blocked airflow winding overheating ঘটায়।',remember:'Main winding run করে, Auxiliary winding start করায়, Rotor torque দেয়।'},
{concept:'Main ও Auxiliary winding প্রায় 90 electrical degree দূরে বসানো হয়। তাদের Current-এর মধ্যেও phase difference তৈরি করলে দুই Flux মিলে approximate Rotating Magnetic Field হয়। এর speed Ns=120f/P।',example:'50 Hz, 4-pole Motor-এর synchronous speed 1500 rpm; induction Rotor বাস্তবে এর একটু নিচে চলে।',remember:'Spatial displacement + Current phase displacement = starting RMF।'},
{concept:'Split-Phase Motor moderate starting torque দেয়; Capacitor-Start high starting torque দেয়; Capacitor-Start Capacitor-Run strong start ও smooth run দেয়; Shaded-Pole সহজ কিন্তু weak; Universal Motor AC/DC-তে high speed দেয়।',example:'Small blower-এ Split-Phase, pump/compressor-এ Capacitor-Start, tiny fan-এ Shaded-Pole এবং drill/mixer-এ Universal Motor ব্যবহার হয়।',remember:'এক Motor সব load-এর জন্য নয়—starting torque, efficiency, noise ও maintenance compare করো।'},
{concept:'Starting method-এর উদ্দেশ্য zero starting torque দূর করে একটি direction তৈরি করা। Resistance split, Capacitor phase shift, permanent run Capacitor, shading coil বা commutator arrangement দিয়ে এটি করা যায়।',example:'Start Capacitor short-time duty; centrifugal switch stuck closed থাকলে Capacitor ও Auxiliary winding দ্রুত overheat করতে পারে।',remember:'Start circuit শুধু torque তৈরি নয়—সঠিক সময়ে connect/disconnect হওয়াও জরুরি।'},
{concept:'Speed control Motor ও load অনুযায়ী হতে হবে। Frequency control Ns পরিবর্তন করে; winding tap fixed speed দেয়; Voltage control torque কমায় এবং মূলত fan-type load-এ উপযোগী; Universal Motor suitable electronic controller দিয়ে নিয়ন্ত্রিত হতে পারে।',example:'Ceiling fan regulator Voltage/control waveform বদলায়, কিন্তু heavy constant-torque pump-এ ভুল controller দিলে Motor stall ও overheat করতে পারে।',remember:'Controller compatibility না জেনে speed control প্রয়োগ করো না।'},
{concept:'Starting Torque zero speed-এ, Accelerating Torque Tacc=Tm−TL এবং Breakdown Torque maximum stable torque। Simplified induction condition-এ torque প্রায় V²-এর proportional, তাই low Voltage-এ starting capability দ্রুত কমে।',example:'Motor torque 8 N·m এবং load torque 5 N·m হলে accelerating torque 3 N·m। Voltage 10% কমলে available torque প্রায় 19% কমতে পারে।',remember:'Motor accelerate করতে Tm>TL হতে হবে; stall অবস্থায় high Current বিপজ্জনক।'},
{concept:'Single-Phase Motor-এর সুবিধা হলো domestic supply-তে সহজে ব্যবহার ও ছোট load-এ কম initial cost। Limitation হলো extra starting parts, তুলনামূলক কম efficiency, বেশি torque pulsation এবং সীমিত practical Power range।',example:'ছোট home pump Single-Phase-এ যুক্তিসঙ্গত, কিন্তু বড় continuous industrial pump Three-Phase Motor-এ বেশি efficient ও reliable।',remember:'Convenience-এর পাশাপাশি duty, energy cost ও maintenance বিচার করো।'},
{concept:'Common fault হলো no start, humming, overheating, slow speed, vibration ও repeated tripping। Diagnosis-এ supply, protection, Capacitor, winding, switch, bearing এবং driven load ধারাবাহিকভাবে পরীক্ষা করতে হয়।',example:'Pump hum করলে বারবার ON না করে isolate করে shaft free কিনা, Capacitor value, terminal Voltage ও winding condition পরীক্ষা করতে হবে।',remember:'Symptom দেখে part বদল নয়—safe systematic diagnosis করো।'},
{concept:'Maintenance-এর আগে সব energy source isolate, absence of Voltage verify, Capacitor approved method-এ discharge এবং automatic restart prevent করতে হবে। Cooling path, bearing, terminal, earth, insulation ও starting parts নিয়মিত inspect করা জরুরি।',example:'Supply OFF হলেও Capacitor charge ধরে রাখতে পারে এবং thermal protector ঠান্ডা হলে Motor নিজে restart করতে পারে।',remember:'Isolate → verify → discharge → secure → maintain → guard restore।'},
{concept:'Application নির্বাচন starting torque, speed, duty, noise, environment ও lifecycle cost দেখে হয়। Fan quiet running চায়, pump ও compressor strong start চায়, portable tool high speed ও compact construction চায়।',example:'Ceiling fan-এ PSC, water pump-এ Capacitor-Start, compressor-এ two-Capacitor arrangement এবং drill-এ Universal Motor উপযোগী।',remember:'Load requirement থেকে Motor type নির্বাচন শুরু করো, শুধু watt rating থেকে নয়।'},
{concept:'Three-Phase Motor balanced supply থেকে naturally rotating field তৈরি করে এবং self-starting; Single-Phase induction type phase-splitting component চায়। Three-Phase Motor সাধারণত smoother torque, বেশি efficiency ও বড় industrial duty দেয়।',example:'বাসার fan Single-Phase, কিন্তু factory conveyor বা বড় compressor Three-Phase drive ব্যবহার করে।',remember:'Single phase = small-load convenience; Three phase = smoother, efficient industrial performance।'}];
banglaHelp[19]=[
{concept:'Synchronous Machine-এ Rotor magnetic field Stator-এর Rotating Magnetic Field-এর সঙ্গে একই speed-এ locked থাকে। একই machine mechanical input পেলে Generator এবং electrical input পেলে Motor হিসেবে কাজ করতে পারে।',example:'Power station-এর Alternator mechanical energy থেকে AC তৈরি করে; বড় compressor-এর Synchronous Motor AC নিয়ে shaft torque দেয়।',remember:'Generator: mechanical→electrical; Motor: electrical→mechanical; steady slip=0।'},
{concept:'Generator mode-এ rotating Rotor Flux Stator winding-এ Three-Phase EMF induce করে। Motor mode-এ Stator RMF এবং excited Rotor field-এর interaction torque তৈরি করে। Field দুটির angular separation-কে Power Angle বলা হয়।',example:'Grid-connected Generator-এ turbine torque বাড়ালে Rotor angle বাড়ে এবং real Power output বাড়ে, কিন্তু speed grid frequency-এর সঙ্গে locked থাকে।',remember:'Induction Generator action তৈরি করে; magnetic locking Motor torque তৈরি করে।'},
{concept:'প্রধান অংশ হলো laminated Stator Core, Three-Phase Armature Winding, Rotor Field, Air Gap, Shaft, Bearing, Exciter, Cooling ও terminal system। High Voltage Armature Stator-এ রাখলে insulation ও connection সহজ হয়।',example:'Turbo-Alternator-এ strong cooling ও accurate Rotor balance জরুরি; সামান্য imbalance-ও high speed-এ বড় vibration করতে পারে।',remember:'Stator AC Power বহন করে; Rotor DC field বহন করে।'},
{concept:'Stator stationary Armature: Generator-এ output দেয়, Motor-এ input নেয়। Rotor rotating field: Generator-এ prime mover ঘোরায়, Motor-এ Stator field-এর সঙ্গে lock হয়ে load চালায়।',example:'Main load Current Slip Ring দিয়ে না নিয়ে stationary Stator terminal দিয়ে নেওয়ায় large Alternator নিরাপদ ও practical হয়।',remember:'Armature সাধারণত Stator-এ, Field সাধারণত Rotor-এ।'},
{concept:'Salient-Pole Rotor-এ projecting pole, বহু pole, বড় diameter ও non-uniform Air Gap থাকে—low-speed hydro/diesel duty-তে উপযোগী। Cylindrical Rotor smooth, সাধারণত 2/4 pole এবং high-speed turbine-এর centrifugal stress সহ্য করে।',example:'100 rpm hydro turbine অনেক pole-এর Salient Rotor চালায়; steam turbine 3000 rpm-এ 2-pole Cylindrical Rotor চালাতে পারে।',remember:'Low speed→Salient; High speed→Cylindrical।'},
{concept:'Synchronous Speed Ns=120f/P এবং Generator frequency f=PN/120। Frequency বাড়লে speed বাড়ে; pole বাড়লে একই frequency-তে speed কমে। Synchronous Motor steady state-এ ঠিক Ns-এ চলে।',example:'50 Hz, 6-pole Motor-এর Ns=1000 rpm; 12-pole Generator 500 rpm-এ ঘুরলে f=50 Hz।',remember:'Ns=120f/P; f=PN/120।'},
{concept:'Alternator prime mover-এর mechanical Power-কে Three-Phase AC-তে বদলায়। Phase EMF Eph=4.44kwfΦT। Grid connection-এর পর governor/torque মূলত real Power এবং excitation মূলত reactive Power ও Voltage support নিয়ন্ত্রণ করে।',example:'Diesel Generator isolated load-এ governor দিয়ে 50 Hz এবং AVR দিয়ে rated Voltage বজায় রাখে।',remember:'Mechanical input→MW; Excitation→Voltage/MVAr।'},
{concept:'Synchronous Motor locked অবস্থায় exact Ns-এ চলে, কিন্তু basic machine self-starting নয়। Damper winding, pony motor বা VFD দিয়ে speed তুলে field apply করে synchronism-এ আনা হয়। Excitation বদলে lagging, unity বা leading PF পাওয়া যায়।',example:'Large compressor Motor overexcited চালিয়ে একই সঙ্গে mechanical load ও factory Power-Factor correction করা যায়।',remember:'Load বাড়লে speed নয়—Power Angle বাড়ে; অতিরিক্ত load-এ pull-out হয়।'},
{concept:'Excitation System Rotor Field Current supply ও regulate করে। Static system Slip Ring ব্যবহার করতে পারে; Brushless system shaft exciter ও rotating diode ব্যবহার করে। AVR measured Voltage অনুযায়ী field adjust করে।',example:'Terminal Voltage কমার tendency হলে AVR field Current বাড়াতে পারে, তবে Rotor/Stator thermal limiter safe limit বজায় রাখে।',remember:'Excitation controls Flux; loss of excitation গুরুতর protection event।'},
{concept:'Synchronization-এর আগে incoming Generator-এর Voltage, Frequency, Phase Sequence এবং phase angle busbar-এর সঙ্গে match করতে হয়। Excitation দিয়ে Voltage, prime-mover speed দিয়ে frequency এবং synchronizer দিয়ে closing instant ঠিক করা হয়।',example:'Bus 400 V, 50 Hz হলে incoming machine-কে প্রায় একই V/f-এ এনে slow synchroscope movement-এ approved in-phase point-এ breaker close করা হয়।',remember:'Match V + f + sequence + angle; ভুল sequence অপেক্ষা করে ঠিক হয় না।'},
{concept:'Hunting হলো disturbance-এর পর Rotor Angle-এর সামনে-পেছনে oscillation। Damper bars-এ relative motion Current induce করে এবং Lenz’s Law অনুযায়ী opposing torque দিয়ে oscillation কমায়; starting-এ induction torque-ও দেয়।',example:'Compressor load হঠাৎ বদলালে Rotor angle oscillate করতে পারে; damper ও control system নতুন stable point-এ settle করতে সাহায্য করে।',remember:'Damper winding = starting assistance + oscillation damping।'},
{concept:'সুবিধা: exact speed, large-rating efficiency, adjustable PF এবং generation/grid support। সীমাবদ্ধতা: starting arrangement, excitation complexity, synchronization, specialized protection এবং loss-of-synchronism risk।',example:'Large continuous compressor-এ efficiency ও PF benefit complexity justify করতে পারে; small general load-এ Cage Motor সহজ।',remember:'Lifecycle benefit থাকলেই Synchronous Machine নির্বাচন করো।'},
{concept:'Synchronous Motor Ns-এ zero slip-এ চলে এবং DC excitation/magnet চায়; Induction Motor positive slip-এ চলে ও Rotor Current induction-এ পায়। Induction Motor self-starting ও simple; Synchronous Motor reactive Power control করতে পারে।',example:'Factory pump/conveyor-এ Cage Motor, কিন্তু constant-speed high-Power compressor বা grid support-এ Synchronous Machine ব্যবহৃত হতে পারে।',remember:'Synchronous=special performance; Induction=general-purpose simplicity।'},
{concept:'Common fault: Stator earth/phase fault, field fault, loss of excitation, unbalance, AVR/diode failure, overheating, bearing/vibration, cooling failure ও out-of-step। Maintenance-এ AC, DC field, prime mover, auxiliaries ও stored mechanical energy isolate করতে হয়।',example:'Main breaker open থাকলেও Rotor ঘুরে field present থাকলে dangerous Voltage generate হতে পারে; bus থেকেও backfeed আসতে পারে।',remember:'Isolate Stator + Field + Prime mover + Auxiliaries; verify before work।'},
{concept:'Cylindrical Alternator steam/gas turbine-এ, Salient Alternator hydro/diesel-এ, Synchronous Motor large industrial drive-এ এবং Synchronous Condenser reactive support-এ ব্যবহৃত হয়। Selection speed, poles, MW/MVAr, excitation, protection ও lifecycle cost দেখে হয়।',example:'Hydro plant turbine speed ও system frequency থেকে pole number নির্বাচন করে, তারপর governor, AVR, synchronizer ও protection coordinate করে।',remember:'Mechanical source/load এবং electrical system—দুই দিক মিলিয়ে machine নির্বাচন করো।'}];
banglaHelp[20]=[
{concept:'Motor Starting হলো standstill থেকে load-সহ Motor-কে নিরাপদে operating speed-এ তোলা। Starting Current, Motor Torque, Load Torque, inertia, acceleration time এবং starts-per-hour একসঙ্গে বিবেচনা করতে হয়।',example:'Light fan সহজে accelerate করে, কিন্তু loaded conveyor-এর inertia ও load torque বেশি হওয়ায় strong controlled torque দরকার।',remember:'Tacc=Tm−TL; positive accelerating torque ছাড়া speed বাড়বে না।'},
{concept:'ভিন্ন Motor-এর starter দরকারের কারণ ভিন্ন। DC Motor-এ start-এ Back EMF শূন্য; Induction Motor high inrush নেয়; basic Single-Phase Motor-এর starting torque শূন্য; Synchronous Motor সরাসরি magnetic lock ধরতে পারে না।',example:'বড় pump direct start করলে supply Voltage dip ও pipe pressure shock দুটোই হতে পারে।',remember:'Starter শুধু Current কমায় না—torque, acceleration, switching ও protection-ও manage করে।'},
{concept:'DC Motor start-এ Ia=V/(Ra+Rstart)। External Resistance Current সীমিত করে এবং speed/Back EMF বাড়লে ধাপে ধাপে সরানো হয়। Three-point ও Four-point starter traditional solution; modern DC drive Voltage/Current electronically ramp করে।',example:'Crane DC drive smooth Armature Voltage ramp দিয়ে load jerk ও Current peak কমায়।',remember:'Start-এ Eb=0; Series Motor কখনো unsafe no-load condition-এ চালিও না।'},
{concept:'DOL full Voltage ও maximum available torque দেয়; Star-Delta প্রায় এক-তৃতীয়াংশ Current ও torque দেয়; Autotransformer selectable reduced Voltage দেয়; Rotor Resistance Slip-Ring Motor-এ high controlled starting torque দেয়; Soft Starter Voltage ramp এবং VFD Voltage+Frequency control করে।',example:'Small pump=DOL, light fan=Star-Delta, fixed large pump=Soft Starter, variable-flow fan=VFD।',remember:'Load torque-speed curve না দেখে starter নির্বাচন করো না।'},
{concept:'Single-Phase starting-এ Auxiliary Winding, Capacitor, Shading Coil বা Universal Motor commutator principle directional torque তৈরি করে। Capacitor-Start high torque, PSC quiet running, Shaded-Pole low-cost কিন্তু weak।',example:'Fan hum করে না ঘুরলে Capacitor, start winding, switch, supply ও bearing পরীক্ষা করতে হয়।',remember:'Start Capacitor short-time duty; running অবস্থায় ভুলভাবে connected থাকলে overheat হতে পারে।'},
{concept:'DC speed relation N∝(V−IaRa)/Φ। Armature Voltage control base speed-এর নিচে efficient; Field Weakening base speed-এর ওপরে speed বাড়ায় কিন্তু torque কমায়; series Resistance heat নষ্ট করে।',example:'Rolling mill drive low speed-এ Armature Voltage ও high speed-এ controlled Field Weakening ব্যবহার করে।',remember:'Voltage control below base; weak field above base; overspeed protection জরুরি।'},
{concept:'Induction Motor speed N=(120f/P)(1−s)। VFD frequency বদলে wide-range efficient control দেয়; Pole Changing discrete speed; Stator Voltage fan-type load-এ limited; Rotor Resistance শুধু Slip-Ring Motor-এ এবং inefficient।',example:'Centrifugal pump VFD-তে speed কমিয়ে throttling-এর তুলনায় energy saving পাওয়া যায়।',remember:'Modern general solution=VFD; constant V/f Flux বজায় রাখতে সাহায্য করে।'},
{concept:'Synchronous Motor locked অবস্থায় Ns=120f/P। তাই continuous speed control-এর জন্য frequency বদলাতে হয়; pole change discrete speed দেয়। Field excitation Power Factor/Reactive Power বদলায়, fixed frequency-তে speed নয়।',example:'PMSM compressor inverter frequency ও Rotor-position control দিয়ে efficient variable speed দেয়।',remember:'Frequency sets speed; Excitation sets Flux/PF behavior।'},
{concept:'Soft Starter thyristor দিয়ে RMS Voltage ধীরে বাড়ায়। এতে inrush ও mechanical shock কমে, কিন্তু torque প্রায় V² অনুযায়ী কমে। Acceleration শেষে bypass contactor loss কমায়।',example:'Fixed-speed pump-এ Soft Start/Stop electrical inrush ও water hammer কমাতে পারে।',remember:'Soft Starter speed controller নয়; heavy load-এ অতিরিক্ত Voltage reduction stall করাতে পারে।'},
{concept:'VFD-এর Power path: Rectifier → DC Link → Inverter। Controller frequency, Voltage, ramp ও Current limit manage করে। PWM output Motor ও cable-এ dv/dt, common-mode ও bearing-current concern তৈরি করতে পারে।',example:'HVAC fan demand কমলে VFD speed কমিয়ে airflow control ও energy saving দেয়।',remember:'Input OFF হলেও DC-Link Capacitor hazardous Voltage ধরে রাখতে পারে।'},
{concept:'Routine Maintenance-এ noise, smell, vibration, temperature, phase Voltage/Current, terminal, earth, cooling, bearing, lubrication, alignment ও protection event নিয়মিত check ও record করতে হয়।',example:'Bearing vibration ও temperature ধীরে বাড়া early lubrication/alignment fault দেখাতে পারে।',remember:'Repeatable baseline ও trend একটি isolated reading-এর চেয়ে বেশি কার্যকর।'},
{concept:'Preventive Maintenance সময়/operating hour অনুযায়ী planned task; Predictive Maintenance vibration, thermography, MCSA, insulation ও temperature trend দেখে কাজের সময় ঠিক করে। Corrective Maintenance failure-এর পরে repair।',example:'Bearing-frequency vibration trend বাড়লে planned shutdown-এ bearing বদলে catastrophic failure এড়ানো যায়।',remember:'Preventive=schedule; Predictive=condition; effort asset criticality অনুযায়ী।'},
{concept:'Overheating, bearing failure, insulation failure, vibration, noise, overload ও phase failure-এর cause supply, control, Motor, coupling বা driven load—যেকোনো জায়গায় হতে পারে। Diagnosis safe evidence-based sequence-এ করতে হয়।',example:'Conveyor overload trip হলে relay setting না বাড়িয়ে jam, belt, gearbox, phase Current ও cooling পরীক্ষা করো।',remember:'Trip বারবার reset নয়—event data পড়ো, root cause fix করো।'},
{concept:'Fuse/MCB/MCCB short-circuit ও overcurrent function দেয়; Thermal Overload Relay sustained Motor heating detect করে কিন্তু short circuit clear করে না; RCCB residual Current detect করে; legacy Voltage-operated ELCB আলাদা principle।',example:'DOL circuit-এ short-circuit device, contactor, overload relay এবং প্রয়োজন অনুযায়ী phase/residual protection coordinate করা হয়।',remember:'একটি device সব fault protect করে না; RCCB সাধারণত overload protection নয়।'},
{concept:'Maintenance-এর আগে Main Supply, Control Supply, DC Field, VFD DC Link, Brake, Heater, Capacitor, pressure, gravity ও rotating inertia isolate/control করতে হয়। LOTO এবং absence-of-voltage verification অপরিহার্য।',example:'Input isolated VFD fan airflow-এ windmill করলে Motor থেকে electrical energy ফিরতে পারে; electrical ও mechanical দুটো hazard control দরকার।',remember:'Isolate → lock/tag → release stored energy → verify → secure → work।'},
{concept:'Industrial best practice load torque, supply strength, duty, process, environment, protection, EMC, cooling, energy ও lifecycle cost মিলিয়ে Motor/starter/drive নির্বাচন করে। Commissioning baseline এবং controlled parameter management reliability বাড়ায়।',example:'Pump fixed speed হলে Soft Starter, variable flow হলে VFD; crane/hoist-এ application-rated drive ও fail-safe brake দরকার।',remember:'Preferred technology দিয়ে নয়—load and process requirement দিয়ে selection শুরু করো।'}];
banglaHelp[21]=[
{concept:'Electrical Power Generation হলো primary Energy-কে নিয়ন্ত্রিতভাবে electrical Energy-তে রূপান্তর করা। অধিকাংশ বড় Power Plant-এ Prime Mover একটি Synchronous Generator ঘোরায়; Solar PV আলো থেকে সরাসরি DC তৈরি করে এবং inverter সেটিকে AC-তে রূপান্তর করে।',example:'Thermal Plant-এ Fuel → Heat → Steam → Turbine → Generator; Solar Plant-এ Sunlight → DC → Inverter → AC Grid।',remember:'Generation মানে Energy সৃষ্টি নয়—Energy conversion।'},
{concept:'Solar, Wind, Hydro, sustainable Biomass, Tidal ও Geothermal renewable; Coal, Oil, Gas ও Nuclear fuel non-renewable। Dispatchable source নির্দেশ অনুযায়ী output বদলাতে পারে, কিন্তু Solar/Wind resource অনুযায়ী variable।',example:'রাতে Solar output না থাকলে flexible plant, storage, import বা demand response দিয়ে Grid balance করতে হয়।',remember:'Renewable মানেই impact-free নয়; resource ও Grid integration বিবেচনা করো।'},
{concept:'Conventional Power Plant-এর মধ্যে Steam Thermal, Hydro, Nuclear, Diesel ও Gas-Turbine plant আছে। প্রতিটির Prime Mover, start time, efficiency, fuel, cost ও duty আলাদা। Combined Cycle exhaust Heat দিয়ে অতিরিক্ত Power তৈরি করে।',example:'Hospital backup-এ fast Diesel Generator; দীর্ঘ efficient generation-এ Combined Cycle উপযোগী হতে পারে।',remember:'Plant নির্বাচন duty, resource, response, cost ও reliability দেখে।'},
{concept:'Solar PV আলো থেকে DC, Wind বাতাস থেকে mechanical/electrical Power, Biomass fuel থেকে Heat বা gas, Tidal sea movement এবং Geothermal ভূগর্ভের Heat থেকে electricity তৈরি করে।',example:'Factory rooftop Solar দিনের Grid import কমায়; Biomass Cogeneration electricity ও useful Heat দুটোই দিতে পারে।',remember:'Solar/Wind variable; Biomass dispatchable হতে পারে; Tidal predictable।'},
{concept:'Power Plant-কে Energy-conversion chain দিয়ে বোঝা যায়। Gross Generation থেকে pump, fan, cooling ও control-এর Auxiliary Power বাদ দিলে Net Generation পাওয়া যায়: Pnet = Pgross − Pauxiliary।',example:'Generator 110 MW তৈরি করে auxiliaries 8 MW নিলে Grid export 102 MW।',remember:'Gross output ও Net output এক নয়।'},
{concept:'Base Load হলো দীর্ঘ সময় থাকা minimum demand; Peak Load হলো অল্প সময়ের উচ্চ demand। Base-duty plant দীর্ঘ সময় economical, Peak-duty resource দ্রুত start ও ramp করতে পারে।',example:'সন্ধ্যার peak-এ fast Hydro, Gas Turbine বা Battery দ্রুত output বাড়াতে পারে।',remember:'Base/Peak হলো load duty—স্থায়ী technology label নয়।'},
{concept:'Load Curve chronological demand দেখায়। Load Duration Curve একই value বড় থেকে ছোট সাজিয়ে কত সময় কোনো level অতিক্রম হয়েছে দেখায়। দুই curve-এর area একই Energy।',example:'20 MW×6 h + 12 MW×10 h + 8 MW×8 h = 304 MWh; Average Load = 12.67 MW।',remember:'Load Curve বলে কখন; Load Duration Curve বলে কতক্ষণ; Area = Energy।'},
{concept:'Load Factor = Average Load/Maximum Demand। Capacity Factor = Actual Energy/(Rated Capacity×Total hours)। Plant Factor-এর সংজ্ঞা source ভেদে বদলাতে পারে, তাই formula আগে লিখতে হবে।',example:'100 MW plant 30 দিনে 43,800 MWh দিলে Capacity Factor = 43,800/(100×720) = 60.83%।',remember:'Period ও denominator স্পষ্ট না করে factor হিসাব করো না।'},
{concept:'Plant তুলনায় capital, fuel, start time, ramp, efficiency, maintenance, Grid support, environment, safety ও life একসঙ্গে দেখতে হয়। এক parameter দিয়ে best plant নির্ধারণ করা যায় না।',example:'Remote site-এ Solar+Battery+backup ভালো হতে পারে; national Grid-এ balanced portfolio দরকার।',remember:'Universal best plant নেই—defined need-এর জন্য best fit আছে।'},
{concept:'Bangladesh-এ public, private, joint-venture plant ও import মিলিয়ে supply দেওয়া হয়। Gas, coal, liquid fuel, Hydro, Solar ও Wind mix-এ আছে। Installed capacity actual output বা generated Energy নয়।',example:'Fuel shortage, outage বা transmission limit থাকলে nameplate 100 MW plant পুরো output দিতে পারে না।',remember:'Bangladesh data-তে BPDB/Power Division/SREDA source ও date দাও।'},
{concept:'Generation impact-এর মধ্যে greenhouse gas, air pollutant, water use, thermal discharge, waste, land, biodiversity, noise ও community effect আছে। Lifecycle assessment সব পর্যায় দেখে।',example:'গরম cooling-water discharge receiving water-এর temperature ও ecosystem ক্ষতিগ্রস্ত করতে পারে।',remember:'Avoid → minimize → control/monitor → restore → compensate।'},
{concept:'Power Plant-এ High Voltage-এর পাশাপাশি pressure, Heat, rotating shaft, fuel, chemical, water, gravity ও automatic-start hazard থাকে। PTW, LOTO ও verification দরকার।',example:'Boiler Feed Pump-এ breaker ছাড়াও hot water, pressure, shaft ও auto-start isolate করতে হয়।',remember:'Safe isolation মানে সব electrical ও non-electrical Energy control।'},
{concept:'Reliable generation শিল্প, hospital, water, transport ও communication চালু রাখে। Captive Generation নিজস্ব facility-কে supply দেয়; Cogeneration একই fuel থেকে electricity ও useful Heat দেয়।',example:'Textile factory Grid, rooftop Solar ও emergency Generator coordinated protectionসহ ব্যবহার করতে পারে।',remember:'Industry-এর দরকার reliable, quality, economical ও recoverable Power।'}];
banglaHelp[22]=[
{concept:'Transmission বড় পরিমাণ electrical Power generating station থেকে major Substation বা load center-এ বহন করে। Distribution সেই Power-কে MV ও LV ধাপে ভাগ করে consumer পর্যন্ত পৌঁছে দেয়। মাঝখানে Transformer, line, Substation, protection ও control একসঙ্গে কাজ করে।',example:'Power Plant-এর Voltage step-up করে Grid line-এ পাঠানো হয়; regional Substation-এ step-down করে feeder, Distribution Transformer ও service line দিয়ে factory বা বাসায় পৌঁছায়।',remember:'Transmission = bulk transfer; Distribution = consumer delivery।'},
{concept:'Balanced Three-Phase system-এ P=√3VLILcosφ। একই Power ও PF-এর জন্য Voltage বাড়ালে Current কমে; loss 3I²R হওয়ায় Current কমলে loss খুব দ্রুত কমে। তবে বেশি Voltage-এ insulation, clearance, Tower, Switchgear ও Corona control-এর খরচ বাড়ে।',example:'10 MW unity PF Power 11 kV-তে প্রায় 525 A, 132 kV-তে প্রায় 43.7 A নেয়; একই R হলে loss প্রায় 1/144 হয়।',remember:'Same Power: V↑ → I↓ → I²R loss↓↓; কিন্তু Voltage-এর economic limit আছে।'},
{concept:'Overhead Line bare Conductor-কে Tower/Insulator দিয়ে ওপরে বহন করে—cost কম ও repair সহজ, কিন্তু weather ও lightning exposure বেশি। Underground Cable insulated ও কম দৃশ্যমান, কিন্তু cost, joint repair, Heat dissipation ও charging Current challenge। HVDC বিশেষ long cable বা asynchronous link-এ উপযোগী হতে পারে।',example:'Open rural route-এ Overhead Line economical; dense city বা river/submarine crossing-এ Underground/Submarine Cable justified হতে পারে।',remember:'Overhead accessible but exposed; Underground protected but costly and capacitive।'},
{concept:'Transmission Line-এর phase Conductor Current বহন করে, Tower clearance রাখে, Insulator grounded structure থেকে আলাদা করে, Earth Wire lightning shield দেয়। Clamp, spacer, vibration damper, joint, Surge Arrester, relay ও communication reliability বাড়ায়।',example:'River crossing-এ long span-এর জন্য taller Tower, strong Conductor এবং wind-temperature অনুযায়ী sag clearance দরকার।',remember:'Electrical performance + mechanical strength + safe clearance—তিনটিই line design-এর অংশ।'},
{concept:'Line parameter হলো R, L, C ও G। R active loss ও Voltage drop দেয়; L magnetic field ও Inductive Reactance XL=2πfL তৈরি করে; C electric field ও charging Current IC=2πfCV তৈরি করে; G insulation leakage বোঝায়।',example:'Lightly loaded long line বা Cable-এর Capacitance receiving-end Voltage বাড়াতে পারে এবং compensation দরকার হতে পারে।',remember:'Series: R,L → Z; Shunt: G,C → Y। Cable-এ C কখনো অকারণে ignore করো না।'},
{concept:'Short Line model-এ Capacitance neglect করে শুধু Series Z রাখা হয়। Medium Line-এ Nominal-π বা Nominal-T দিয়ে Capacitance lump করা হয়। Long Line-এ R,L,C,G continuously distributed ধরা হয়। Length boundary textbook guide—universal rule নয়।',example:'Short Overhead feeder-এ simple Z model চলতে পারে, কিন্তু একই দৈর্ঘ্যের high-capacitance Cable-এ π model দরকার হতে পারে।',remember:'Model নির্বাচন parameter significance দেখে; শুধু kilometre দেখে নয়।'},
{concept:'Distribution path সাধারণত Grid Substation → Primary Feeder → Distribution Transformer → LV Distributor → Service Main → Consumer। Voltage control, phase balance, selective protection এবং alternative switching path consumer service quality নির্ধারণ করে।',example:'City ring network-এ faulted cable section isolate করে healthy load অন্য দিক থেকে restore করা যায়।',remember:'Distribution হলো Transformer, feeder, protection, metering ও service-এর coordinated system।'},
{concept:'Primary Distribution Medium Voltage-এ Substation থেকে Distribution Transformer বা বড় MV consumer-কে supply দেয়। Radial, ring বা interconnected feeder হতে পারে। Design-এ ampacity, Voltage drop, fault level, protection ও future load দেখা হয়।',example:'Industrial estate 11 kV বা 33 kV feeder নিয়ে প্রতিটি factory-র own Substation-এ Power ভাগ করতে পারে।',remember:'Primary = MV feeder stage; Distributed Generation bidirectional flow তৈরি করতে পারে।'},
{concept:'Secondary Distribution Distribution Transformer-এর LV side থেকে consumer পর্যন্ত যায়। একই Power-এ LV Current বেশি হওয়ায় conductor size ও Voltage drop গুরুত্বপূর্ণ। Single-Phase load তিন phase-এ balance না করলে Neutral Current, unbalance ও heating বাড়ে।',example:'Pole-mounted Transformer থেকে LV Distributor যায়, তারপর আলাদা Service Main দিয়ে বাড়ি ও দোকানে supply পৌঁছায়।',remember:'Secondary = LV consumer stage; Neutral-কে কখনো Current-free ধরে নিও না।'},
{concept:'Distribution Transformer MV-কে LV-তে নামায় এবং সাধারণত kVA-তে rated। Core loss energized থাকলেই হয়; Copper loss load Current-এর I² অনুযায়ী বাড়ে। Load center-এর কাছে বসালে long high-current LV run কমে।',example:'দূরের Transformer থেকে বড় LV load supply দিলে drop ও loss বেশি; কাছে Transformer দিলে path ছোট হয়।',remember:'Core loss≈fixed energized loss; Copper loss∝I²; location lifecycle loss বদলায়।'},
{concept:'Feeder Substation থেকে area-তে bulk Distribution Power বহন করে; Distributor-এর পথে অনেক tapping থাকে; Service Main একটি consumer-এর final connection। Feeder design-এ ampacity/fault duty, Distributor-এ Voltage drop এবং Service-এ consumer demand গুরুত্বপূর্ণ।',example:'11 kV Feeder কয়েকটি Transformer supply করে; প্রতিটি Transformer-এর LV Distributor থেকে বাড়ির Service Main বের হয়।',remember:'Feeder → Distributor → Service Main → Consumer।'},
{concept:'Technical loss physical network-এ হয়—Conductor I²R, Transformer Core/Copper, Cable dielectric, Corona ও leakage। Non-technical loss unauthorized use, meter tampering, faulty metering বা data/billing error থেকে হয়। একই boundary ও period ছাড়া loss percentage অর্থপূর্ণ নয়।',example:'Factory একই kW low PF-এ নিলে Current বাড়ে, ফলে feeder, Transformer ও cable-এর I²R loss বাড়ে।',remember:'Installed/entered Energy − correctly delivered Energy; cause শনাক্ত করতে feeder-wise metering দরকার।'},
{concept:'Loss কমাতে suitable high Voltage, adequate Conductor, correct PF compensation, phase balancing, harmonic control, efficient Transformer ও short LV path ব্যবহার করা হয়। Loose joint repair ও accurate metering technical/non-technical দু ধরনের loss control করে।',example:'Load-এর কাছে Transformer, balanced phases এবং properly controlled Capacitor Bank একসঙ্গে Voltage ও loss উন্নত করতে পারে।',remember:'Current, Resistance বা unnecessary path length কমাও; safety ও economics যাচাই করো।'},
{concept:'Grid Generator, line, Substation, Distribution ও load-কে interconnect করে। Substation Voltage transform, circuit switch, fault protect, quantity measure ও Power route করে। Breaker fault Current interrupt করে; Disconnector approved no-load isolation দেয়।',example:'132/33 kV Substation একাধিক 33 kV feeder supply করে; একটি feeder fault হলে relay শুধু সেই Breaker trip করার চেষ্টা করে।',remember:'Grid balances Power; Substation transforms, switches, protects, measures and controls।'},
{concept:'Radial system এক দিক থেকে supply—simple ও cheap কিন্তু downstream fault-এ outage বড়। Ring alternative direction দেয়। Interconnected system multiple source/path দিয়ে highest flexibility দেয়, তবে fault level, operation ও protection complexity বেশি।',example:'Rural area radial হতে পারে; hospital district ring বা interconnected arrangement ব্যবহার করতে পারে।',remember:'More paths → better continuity, but more cost and protection complexity।'},
{concept:'Industrial Distribution-এ incoming capacity, Transformer location, Motor-start dip, harmonics, PF, fault level, selectivity, redundancy ও maintenance একসঙ্গে দেখতে হয়। নতুন বড় load শুধু cable addition নয়—পুরো system study প্রয়োজন।',example:'Factory expansion-এ load flow, short circuit, protection setting, Transformer loading ও harmonic study update করতে হয়।',remember:'Capacity + Voltage + fault + protection + Power quality + reliability = industrial review।'}];
banglaHelp[16]=[
{concept:'DC Machine একই construction ব্যবহার করে Generator বা Motor হিসেবে কাজ করতে পারে। Generator mechanical energy-কে DC electrical energy-তে, আর Motor DC electrical energy-কে mechanical energy-তে রূপান্তর করে।',example:'একই laboratory machine prime mover দিয়ে ঘোরালে Generator, DC supply দিলে Motor হিসেবে কাজ করতে পারে।',remember:'Generator: mechanical→electrical; Motor: electrical→mechanical।'},
{concept:'DC Generator Faraday’s Law অনুযায়ী কাজ করে। Armature conductor magnetic flux কাটলে EMF তৈরি হয় এবং Commutator terminal-এ একমুখী output দেয়।',example:'Engine দিয়ে Armature ঘোরালে conductor-এ induced EMF তৈরি হয়ে load-এ DC current দেয়।',remember:'Generator direction নির্ণয়ে Fleming’s Right-Hand Rule।'},
{concept:'Yoke, pole, field winding, laminated armature, winding, commutator, brush, shaft ও bearing DC Generator-এর প্রধান অংশ। প্রতিটির magnetic, electrical বা mechanical কাজ আছে।',example:'Laminated armature core eddy-current loss কমায়; carbon brush rotating commutator থেকে current সংগ্রহ করে।',remember:'Field flux তৈরি করে, Armature conversion করে, Commutator switching করে।'},
{concept:'Generated EMF: Eg=PΦZN/(60A)। এখানে P=poles, Φ=flux/pole, Z=conductors, N=rpm এবং A=parallel paths। Fixed machine-এ Eg∝ΦN।',example:'4-pole wave winding, Φ=.02 Wb, Z=600, N=1000 হলে A=2 এবং Eg=400 V।',remember:'Simplex Lap: A=P; Wave: A=2।'},
{concept:'Excitation অনুযায়ী Generator permanent-magnet, separately excited, shunt, series বা compound হয়। Shunt field parallel এবং Series field load current বহন করে।',example:'প্রায় constant voltage-এর জন্য Shunt, controllable voltage-এর জন্য separately excited Generator উপযোগী।',remember:'Self-excitation-এর জন্য residual magnetism, correct polarity, speed ও field resistance জরুরি।'},
{concept:'DC Motor-এ magnetic field-এর মধ্যে current-carrying conductor force পায়। Armature-এর বহু conductor-এর force মিলে torque তৈরি করে: T=kΦIa।',example:'Crane Motor-এ বেশি Armature current ও suitable flux উচ্চ starting torque তৈরি করে।',remember:'Motor direction: Fleming’s Left-Hand Rule।'},
{concept:'Motor ও Generator-এর major parts একই, কিন্তু Motor armature electrical input নেয় এবং shaft mechanical output দেয়। Cooling, alignment ও brush condition reliability নির্ধারণ করে।',example:'Bearing misalignment vibration ও heating বাড়ায়; blocked ventilation winding temperature বাড়ায়।',remember:'Nameplate voltage, current, speed, duty ও insulation limit মানতে হবে।'},
{concept:'Motor ঘুরলে Armature-এ supply-এর বিপরীত EMF তৈরি হয়—এটাই Back EMF। Eb=kΦN এবং V=Eb+IaRa; এটি running current সীমিত করে।',example:'220 V Motor, Ia=20 A, Ra=.5 Ω হলে Eb=210 V।',remember:'Start-এ N=0, তাই Eb=0 এবং starting current খুব বেশি হতে পারে।'},
{concept:'Shunt Motor প্রায় constant speed, Series Motor খুব বেশি starting torque এবং Compound Motor দুটির বৈশিষ্ট্যের সমন্বয় দেয়। Series Motor load ছাড়া চালানো বিপজ্জনক।',example:'Lathe-এ Shunt, crane-এ Series এবং elevator-এ cumulative Compound Motor ব্যবহার করা যায়।',remember:'Shunt→speed regulation; Series→high starting torque।'},
{concept:'Speed relation N∝(V−IaRa)/Φ। Armature voltage দিয়ে base speed-এর নিচে, field weakening দিয়ে base speed-এর ওপরে এবং resistance দিয়ে inefficient control করা যায়।',example:'Field current কমালে flux কমে speed বাড়ে, কিন্তু torque capability কমে ও overspeed risk বাড়ে।',remember:'Voltage control efficient; resistance control heat নষ্ট করে।'},
{concept:'Motor characteristics হলো T–Ia, N–Ia এবং N–T সম্পর্ক। Shunt Motor-এ T প্রায় Ia-এর সমানুপাতিক; unsaturated Series Motor-এ T প্রায় Ia²-এর সমানুপাতিক।',example:'Load বাড়লে Shunt speed সামান্য কমে; Series Motor speed load-এর সঙ্গে অনেক বদলায়।',remember:'Characteristic curve দেখে load-এর জন্য Motor নির্বাচন করো।'},
{concept:'DC Generator-এর traditional use battery charging, excitation, electroplating, welding ও laboratory supply। বর্তমানে অনেক ক্ষেত্রে electronic rectifier ব্যবহৃত হয়।',example:'Separately excited laboratory Generator-এ field current বদলে output voltage নিয়ন্ত্রণ করা যায়।',remember:'Application অনুযায়ী excitation ও voltage characteristic নির্বাচন জরুরি।'},
{concept:'DC Motor crane, hoist, rolling mill, conveyor, machine tool, traction ও ছোট actuator-এ ব্যবহৃত হয়। Selection torque, speed, duty, environment ও control-এর ওপর নির্ভর করে।',example:'High starting torque crane-এ, constant speed lathe-এ এবং compact PMDC vehicle wiper-এ উপযোগী।',remember:'Motor type নয়—load requirement দিয়ে selection শুরু করো।'},
{concept:'DC Machine-এর সুবিধা high torque ও wide speed control; limitation হলো brush/commutator wear, sparking ও maintenance। আধুনিক AC drive অনেক application প্রতিস্থাপন করেছে।',example:'Hazardous dust বা gas area-তে brush sparking বড় risk, তাই suitable certified alternative দরকার।',remember:'Performance, safety, efficiency ও lifecycle cost একসঙ্গে বিচার করো।'},
{concept:'Maintenance-এর আগে Armature, field, control ও mechanical energy isolate করতে হবে। Brush, commutator, bearing, insulation, cooling ও protection নিয়মিত পরীক্ষা করে record রাখতে হবে।',example:'Heavy sparking হলে energized অবস্থায় adjustment নয়—machine isolate করে brush setting, surface, load ও winding fault পরীক্ষা করতে হবে।',remember:'Isolate→verify→inspect→test→record; Series Motor কখনো unloaded নয়।'}];
banglaHelp[25]=[
{concept:'Electrical Estimation project-এর load, equipment rating, Cable/protection schedule, material quantity, labour ও cost নির্ধারণ করে। Design technical suitability প্রমাণ করে, Estimation সেই design বাস্তবায়নে কত material ও অর্থ লাগবে তা পরিমাপ করে। Scope ও exclusion পরিষ্কার না থাকলে estimate অসম্পূর্ণ হয়।',example:'Office estimate-এ DB, lighting, socket, AC feeder, containment, Earthing, testing ও as-built drawing included কি না লিখতে হয়।',remember:'Scope → Load → Design → Quantity → Cost → Review।'},
{concept:'Estimation-এর লক্ষ্য শুধু কম দাম নয়; safe capacity, accurate procurement, realistic schedule ও lifecycle economy নিশ্চিত করা। Load পরিবর্তন হলে Cable, protection, containment, Transformer demand এবং cost—সব document update করতে হয়।',example:'30 kW Motor-এর বদলে 55 kW Motor নিলে শুধু Motor price নয়, feeder ও starting system-ও বদলায়।',remember:'Design change পুরো estimate-এ propagate করতে হবে।'},
{concept:'Resistive load সাধারণত PF প্রায় unity, Motor starting Current ও Reactive Power নেয়, electronic load harmonic তৈরি করতে পারে, intermittent load অল্প সময় চলে এবং critical load-এর continuity বেশি গুরুত্বপূর্ণ। Load type demand ও protection decision বদলায়।',example:'Commercial building-এ LED, lift, VFD pump, UPS, computer ও heater-এর behavior এক নয়।',remember:'Nameplate kW-এর আগে load behavior classify করো।'},
{concept:'Connected Load হলো নির্দিষ্ট boundary-এর সব connected equipment-এর electrical input rating-এর যোগফল। Quantity × unit rating করে common unit-এ যোগ করতে হয়। এটি installed inventory; সব load একসঙ্গে চলবে এমন অর্থ নয়।',example:'12×12 W lamp + 6×75 W fan + 1.5 kW heater + 1.2 kW refrigerator = 3.294 kW।',remember:'Input rating ব্যবহার করো; kW ও kVA সরাসরি যোগ করো না।'},
{concept:'Maximum Demand হলো stated demand interval ও period-এ সর্বোচ্চ average load। এটি instantaneous spike-এর সমান নাও হতে পারে। Load group অনুযায়ী justified demand allowance বা measured profile ব্যবহার করা হয়।',example:'120 kW Connected Load ও Demand Factor 0.65 হলে MD = 78 kW।',remember:'MD বললে interval, period ও calculation basis লিখতে হবে।'},
{concept:'Demand Factor = Maximum Demand / Connected Load। একই boundary ও unit ব্যবহার করলে এটি সাধারণত 1-এর বেশি হয় না। Building type, occupancy, climate ও operation অনুযায়ী value বদলায়।',example:'Connected 200 kW, MD 130 kW হলে DF = 130/200 = 0.65।',remember:'Demand Factor installed load থেকে expected peak বের করে।'},
{concept:'Diversity Factor = individual noncoincident Maximum Demand-গুলোর যোগফল / combined coincident Maximum Demand। বিভিন্ন load আলাদা সময়ে peak করায় এটি সাধারণত 1 বা বেশি হয়।',example:'30, 40, 50 kW individual peak এবং group peak 90 kW হলে Diversity Factor = 120/90 = 1.33।',remember:'Demand Factor ও Diversity Factor আলাদা formula; double diversity করো না।'},
{concept:'Load Factor = Average Load / Maximum Demand = Energy/(Maximum Demand×time)। এটি একই period-এ asset কত uniformভাবে ব্যবহৃত হয়েছে বোঝায়। Peak কমিয়ে useful production বজায় রাখলে Load Factor বাড়ে।',example:'36,000 kWh/720 h = 50 kW average; MD 100 kW হলে LF = 50%।',remember:'Energy, peak ও time period অবশ্যই একই হতে হবে।'},
{concept:'Power Factor = kW/kVA। একই kW ও Voltage-এ PF কম হলে Current, I²R loss, Voltage drop ও kVA demand বাড়ে। Correct capacitor compensation upstream Current কমায়, কিন্তু harmonics, resonance ও overcompensation পরীক্ষা দরকার।',example:'90 kW load PF 0.75-এ প্রায় 173 A, PF 0.95-এ প্রায় 137 A নেয়।',remember:'PF correction kWh load মুছে দেয় না; Reactive Current কমায়।'},
{concept:'Residential calculation-এ lighting, fan, socket ও fixed appliance আলাদা তালিকা করে locally approved demand allowance প্রয়োগ করা হয়। তারপর MD থেকে Current, circuit division, Motor starting ও phase balance দেখা হয়। Example percentage official code নয়।',example:'Apartment-এ common lift/pump load ও প্রতিটি flat-এর demand আলাদা হিসাব করে main service coincidence করা হয়।',remember:'বাসার সব appliance-এর nameplate একসঙ্গে 100% ধরা বা arbitrary factor দেওয়া—দুটিই ভুল।'},
{concept:'Commercial load calculation-এ lighting, IT, HVAC, lift, pump, kitchen, tenant ও emergency load তাদের operating schedule অনুযায়ী আলাদা করা হয়। HVAC demand, electronic harmonic, Neutral loading ও critical backup বিশেষ গুরুত্বপূর্ণ।',example:'210 kW connected commercial load justified group demand দিয়ে 152 kW MD হতে পারে; final value code ও operation দিয়ে verify করতে হবে।',remember:'Commercial building-এ এক blanket demand factor ব্যবহার করো না।'},
{concept:'Cable selection: Design Current Ib হিসাব → installation method → correction factor → corrected ampacity Iz → Voltage drop → fault withstand → protective coordination। Simplifiedভাবে Ib ≤ In ≤ Iz, তবে exact code condition অনুসরণ করতে হয়।',example:'30 kW Motor-এর Current 55.4 A হলেও hot grouped route বা long distance-এর কারণে বড় Cable প্রয়োজন হতে পারে।',remember:'Calculated load Current final Cable size নয়।'},
{concept:'Protective device normal ও starting Current বহন করবে, Cable protect করবে এবং prospective fault Current safely interrupt করবে। MCB/MCCB curve, breaking capacity, poles, residual protection, Earthing ও selectivity দেখতে হয়।',example:'55.4 A load দেখে সরাসরি 63 A breaker বলা যায় না; Cable Iz, inrush, fault level ও trip curve verify করতে হয়।',remember:'Rating + curve + breaking capacity + coordination—চারটি check।'},
{concept:'Electrical Energy constant load-এর জন্য E = P×t। Watt-কে kW এবং সময়কে hour-এ নিয়ে kWh হিসাব করা হয়। Thermostat বা variable-speed load-এর actual duty nameplate×time থেকে আলাদা হতে পারে।',example:'10টি 12 W lamp, 6 h/day, 30 day: 10×0.012×6×30 = 21.6 kWh।',remember:'Power হলো rate; Energy হলো Power × operating time।'},
{concept:'Electricity bill-এ kWh Energy charge ছাড়াও Maximum-Demand, fixed, PF, time-of-use, tax ও regulatory charge থাকতে পারে। Meter multiplier, tariff category ও billing period verify করতে হয়। Example rate current Bangladesh tariff নয়।',example:'500 kWh×illustrative 10 + fixed 300 = 5300—এটি শেখানোর example, official bill নয়।',remember:'Current tariff শুধু BERC/utility-এর dated official source থেকে নাও।'},
{concept:'Energy Management cycle হলো Policy → Measure → Analyze → Plan → Implement → Verify → Improve। Baseline reference use দেখায়; EnPI যেমন kWh/unit production performance তুলনা করে; relevant variable দিয়ে adjustment না করলে saving ভুল হতে পারে।',example:'Textile plant production volume adjust করে kWh/kg fabric track করে।',remember:'দুই মাসের bill কমলেই verified saving প্রমাণ হয় না।'},
{concept:'Home-এ efficient lighting ও cooling control, office-এ HVAC schedule ও occupancy sensor, industry-তে compressed-air leak repair, pressure optimization, efficient Motor ও suitable VFD Energy কমাতে পারে। Safety, ventilation বা product quality কমানো conservation নয়।',example:'Variable-flow fan-এ speed কমালে throttling-এর তুলনায় বড় saving হতে পারে, তবে minimum flow ও harmonic check দরকার।',remember:'Waste remove → maintain → control → efficient technology → verify।'},
{concept:'Efficient equipment purchase price দিয়ে নয়, actual load, part-load efficiency, standby loss, reliability, harmonics, maintenance ও Total Cost of Ownership দিয়ে তুলনা করতে হয়। Oversized equipment অনেক সময় কম efficient region-এ চলে।',example:'Continuous pump Motor-এ premium efficiency অর্থনৈতিক হতে পারে, rare standby Motor-এ benefit আলাদা।',remember:'Right-size এবং lifecycle cost compare করো।'},
{concept:'Estimation procedure: scope/standard define, drawing/site review, load schedule, demand, SLD, Cable/protection sizing, safety checks, quantity take-off, labour/cost, reconciliation ও assumptions document। Route length-এ vertical drop ও controlled allowance যুক্ত হয়।',example:'Tender package-এ BOQ, specification, load summary, assumptions ও revision number একসঙ্গে issue করা হয়।',remember:'Quantity take-off-এর আগে scope ও coordinated drawing দরকার।'},
{concept:'Practical worksheet-এ item, quantity, input rating, Connected Load, demand basis, MD, phase, PF, hours, circuit ও remarks থাকা উচিত। Example assumption আলাদাভাবে চিহ্নিত করতে হয়; preliminary Current-এর পরে Cable/fault/protection study বাকি থাকে।',example:'28.5 kW connected workshop instructional factors দিয়ে 25.4 kW MD এবং প্রায় 43.1 A পেতে পারে।',remember:'Worked example reproducible হতে হবে—formula ও assumption দুটোই দেখাও।'},
{concept:'Common mistake: output kW-কে input kW ধরা, kW+kVA যোগ, diversity দুবার apply, line/phase Voltage মিশানো, Motor starting ও harmonic ignore, standby duplicate এবং পুরোনো tariff ব্যবহার। Formula ঠিক হলেও input ভুল হলে result unsafe।',example:'22 kW mechanical-output Motor-এর electrical input 22 kW-এর বেশি, কারণ efficiency 100% নয়।',remember:'Units, boundary, PF, efficiency, diversity ও scenario audit করো।'},
{concept:'Safe estimate-এ Earthing, Cable fault withstand, device breaking capacity, RCD যেখানে দরকার, isolation, working space, fire stopping, IP/environment, critical supply এবং testing রাখা বাধ্যতামূলক। Budget কমাতে safety বাদ দেওয়া যায় না।',example:'Hospital estimate থেকে fire-rated emergency Cable বাদ দিয়ে cost কমানো acceptable নয়।',remember:'Safety ও verification optional allowance নয়।'},
{concept:'Industry-তে estimation safe expansion ও procurement নিশ্চিত করে; Energy management submeter ও EnPI দিয়ে operating cost কমায়। নতুন Motor, production line, Solar বা compressor demand, fault level, Power quality, Transformer এবং protection বদলাতে পারে।',example:'নতুন compressor কেনার আগে leak reduction, storage, demand, Cable/protection upgrade ও lifecycle cost তুলনা করা হয়।',remember:'Expansion = capacity + safety + cost + Energy performance review।'}];
banglaHelp[24]=[
{concept:'Electrical Protection-এর কাজ হলো abnormal condition শনাক্ত করে যত দ্রুত এবং যত ছোট অংশ সম্ভব বিচ্ছিন্ন করা। বড় system-এ CT/VT measurement দেয়, Relay সিদ্ধান্ত নেয় এবং Circuit Breaker fault Current interrupt করে। Reliability, Selectivity, Speed, Sensitivity ও Stability একসঙ্গে দরকার।',example:'একটি factory feeder fault হলে শুধু সেই feeder breaker trip করবে; healthy feeder চালু থাকবে—এটাই selective protection।',remember:'Sense → Decide → Trip → Interrupt; Relay সিদ্ধান্ত নেয়, Breaker Current কাটে।'},
{concept:'Fault Current খুব অল্প সময়েই conductor heating, magnetic force, Arc Flash এবং insulation damage তৈরি করতে পারে। দ্রুত clearing damage কমায়, আর সঠিক coordination অপ্রয়োজনীয় বড় outage ঠেকায়। তবে কোনো protective device unlimited নয়—rating ও application মিলতে হবে।',example:'Motor overload relay Motor-কে দীর্ঘ heating থেকে রক্ষা করে, upstream incomer বন্ধ না করেই শুধু Motor circuit trip করতে পারে।',remember:'Protection মানুষ, equipment, stability ও continuity—চারটিই রক্ষা করে।'},
{concept:'Earthing selected system point ও exposed metal part-কে Earth/Earthing system-এর সঙ্গে যুক্ত করে। Protective Conductor fault Current-এর low-impedance path দেয়; Bonding conductive partগুলোর potential difference কমায়। Earth ideal zero-resistance point নয়, তাই Touch ও Step Voltage গুরুত্বপূর্ণ।',example:'Line wire metal Motor frame-এ লাগলে PE path দিয়ে fault Current ফিরে protection operate করে।',remember:'Earthing path দেয়; Bonding potential difference কমায়।'},
{concept:'Earthing-এর লক্ষ্য automatic disconnection, Voltage reference স্থির রাখা, fault ও surge Current-এর পথ দেওয়া এবং dangerous Touch/Step Voltage সীমিত করা। শুধু কম Earth Resistance পেলেই safe বলা যায় না—complete path, bonding, fault Current ও trip time দেখতে হয়।',example:'Substation grid frame, fence ও structure bond করে fault-এর সময় local Voltage gradient নিয়ন্ত্রণ করে।',remember:'Low ohm alone ≠ complete safety।'},
{concept:'Plate electrode বড় contact area দেয় কিন্তু excavation বেশি; Pipe economical হতে পারে; Rod compact ও depth বাড়ানো সহজ; Strip/Ring/Grid বড় site ও Substation-এ potential control করে। Soil Resistivity, corrosion, জায়গা ও fault duty অনুযায়ী type নির্বাচন হয়।',example:'Factory-তে একক rod-এর বদলে buried ring/grid এবং একাধিক rod ব্যবহার করা যেতে পারে।',remember:'কোনো electrode type সব soil ও সব installation-এর জন্য best নয়।'},
{concept:'Earth Resistance soil Resistivity, moisture, temperature, electrode depth/spacing, corrosion ও parallel path-এর উপর নির্ভর করে। Fall-of-potential test-এ Current ও Potential probe লাগে; clamp test-এর জন্য parallel loop দরকার; Wenner method soil Resistivity মাপে। Universal acceptable ohm value নেই।',example:'Dry season-এ reading বাড়লে design criterion ও previous trend-এর সঙ্গে তুলনা করে electrode ও joint inspect করতে হয়।',remember:'1 Ω বা 5 Ω project target হতে পারে—universal safety law নয়।'},
{concept:'Equipment Earthing exposed frame/enclosure-কে PE system-এ যুক্ত করে Shock protection ও fault clearing দেয়। System Earthing Transformer/Generator Neutral-এর মতো system point-কে Earth-এর সঙ্গে যুক্ত করে fault magnitude ও overvoltage control করে। Neutral ও PE এক জিনিস নয়।',example:'Motor frame-এর Earth হলো Equipment Earthing; Transformer Neutral Earthing Resistor হলো System Earthing।',remember:'Frame protection ≠ Neutral reference; PE normal load return নয়।'},
{concept:'Short Circuit unintended low-impedance path এবং খুব বড় Current দিতে পারে; Open Circuit path ভেঙে Current বন্ধ করে; Earth Fault live part থেকে Earth/metal-এ যায়; Overload normal path-এ rating-এর বেশি sustained Current। প্রতিটির detection আলাদা।',example:'Jammed Motor overload তৈরি করে, কিন্তু winding frame-এ লাগলে Earth Fault হয়।',remember:'Short, Open, Earth Fault ও Overload এক ধরনের fault নয়।'},
{concept:'Fuse melt হয়ে circuit খোলে ও বদলাতে হয়। MCB resettable final-circuit Overcurrent protection দেয়। MCCB বড় Current/fault duty এবং adjustable trip দিতে পারে। RCCB residual Current দেখে কিন্তু সাধারণত overload নয়। পুরোনো voltage ELCB আলাদা technology; RCBO residual ও Overcurrent দুটোই দেয়।',example:'Home socket-এ RCBO এবং factory incomer-এ adjustable MCCB ব্যবহার হতে পারে।',remember:'RCCB alone overload protection নয়; device marking ও standard পড়ো।'},
{concept:'Protective Relay CT/VT signal থেকে Current, Voltage, frequency, direction বা differential quantity দেখে setting ও logic অনুযায়ী trip command দেয়। Pickup, time delay ও characteristic curve coordination নির্ধারণ করে। Relay ঠিক হলেও DC supply, trip coil বা Breaker fail করলে protection অসম্পূর্ণ।',example:'Feeder relay inverse-time Overcurrent ও Earth-Fault element দিয়ে Breaker trip করাতে পারে।',remember:'Complete chain: CT/VT → Relay → DC trip circuit → Breaker।'},
{concept:'Switchgear হলো Breaker, Disconnector, Earthing Switch, Busbar, CT, VT, Relay, meter ও control-এর coordinated assembly। এটি load switching, fault interruption, isolation, Earthing, protection ও measurement করে। Interlock unsafe switching sequence ঠেকায়।',example:'11 kV panel-এ VCB, CT, numerical Relay, shutters ও Earthing Switch থাকতে পারে।',remember:'Switchgear শুধু একটি Switch বা Breaker নয়।'},
{concept:'Circuit Breaker contact খুললে Arc তৈরি হয়; interrupting medium Arc control করে এবং dielectric strength ফিরিয়ে আনে। ACB সাধারণত LV, VCB MV, OCB legacy oil system এবং SF₆ CB HV/EHV-তে ব্যবহৃত। Breaking capacity system fault level-এর সমান বা বেশি হতে হবে।',example:'415 V main board-এ ACB এবং 11 kV feeder-এ VCB ব্যবহৃত হতে পারে।',remember:'ACB–air, VCB–vacuum, OCB–oil, SF₆ CB–gas; duty ও rating মিলাও।'},
{concept:'SPD normal Voltage-এ high impedance থাকে, surge এলে conductive হয়ে Current Earth/protective network-এ divert করে ও Voltage clamp করে। Type 1 service entrance lightning-current duty, Type 2 DB surge duty এবং Type 3 sensitive load-এর কাছাকাছি fine protection দেয়।',example:'Main entrance Type 1, downstream DB Type 2 এবং control equipment-এর কাছে coordinated Type 3 বসানো যেতে পারে।',remember:'SPD transient কমায়; sustained overvoltage বা overload protect করে না।'},
{concept:'Lightning Protection System risk assessment-এর ভিত্তিতে Air Termination দিয়ে strike intercept, Down Conductor দিয়ে Current নামায় এবং Earth Termination দিয়ে disperse করে। Internal bonding ও SPD dangerous sparking ও incoming surge কমায়।',example:'Telecom tower-এর air terminal, multiple down path, bonded metal service ও Power/communication SPD একসঙ্গে কাজ করে।',remember:'Air terminal alone সম্পূর্ণ Lightning Protection নয়।'},
{concept:'Protection coordination-এ downstream device-এর time–Current curve upstream-এর সঙ্গে মিলিয়ে দেখা হয় যেন nearest suitable device আগে trip করে। Breaking capacity, selectivity range, backup/cascading manufacturer data এবং Arc-Flash clearing time একসঙ্গে দেখতে হয়।',example:'32 A MCB branch fault আগে clear করবে, 250 A MCCB closed থাকবে—কিন্তু actual fault Current ও curve দিয়ে প্রমাণ করতে হবে।',remember:'Coordination অনুমান নয়; fault study ও verified curve দরকার।'},
{concept:'Protection system দীর্ঘদিন operate না করেও hidden failure তৈরি করতে পারে। Secondary injection Relay logic দেখে; primary injection measurement path-এর বেশি অংশ পরীক্ষা করে। Breaker timing, contact resistance, trip coil, battery, interlock, RCD এবং Earthing recordসহ test করতে হয়।',example:'Shutdown-এ Relay inject করে actual Breaker trip, DC battery এবং measured operating time একসঙ্গে verify করা হয়।',remember:'শুধু Relay test নয়—sensor থেকে Breaker পর্যন্ত complete trip chain test করো।'},
{concept:'Safe work-এ সব source identify, load safely interrupt, isolate, LOTO, tester prove, circuit dead prove, stored Energy discharge এবং প্রয়োজন হলে Earth apply করতে হয়। Arc-rated PPE শেষ layer; isolation-এর বিকল্প নয়। Switching schedule, authorization ও communication জরুরি।',example:'MV Breaker rack করার আগে approved switching order, interlock, status verification ও required PPE মানতে হয়।',remember:'Identify → Isolate → Lock → Prove dead → Work → Restore safely।'},
{concept:'বাসা থেকে factory ও 11 kV feeder পর্যন্ত protection design-এ load, fault Current, Earthing, device rating, Relay setting, selectivity, Arc risk ও maintenance একসঙ্গে দেখা হয়। নতুন Generator, Solar বা বড় Motor fault level ও Current direction বদলাতে পারে, তাই study update করতে হয়।',example:'Standby Generator যোগ করলে Breaker rating, Neutral Earthing, transfer logic ও Relay setting পুনরায় যাচাই করা হয়।',remember:'System change মানে protection ও Earthing review।'}];
