banglaHelp[26]=[
{concept:'Semiconductor এমন পদার্থ যার conductivity conductor ও insulator-এর মাঝামাঝি এবং doping, temperature, light বা electric field দিয়ে নিয়ন্ত্রণ করা যায়। Silicon সবচেয়ে বেশি ব্যবহৃত হয়, কারণ এর oxide স্থিতিশীল এবং device তৈরি সহজ।',example:'Mobile charger, computer chip, solar cell ও sensor—সবখানেই নিয়ন্ত্রিত semiconductor conduction ব্যবহার হয়।',remember:'Semiconductor-এর মূল শক্তি হলো controllable conductivity।'},
{concept:'Conductor-এ প্রচুর free carrier থাকায় current সহজে চলে; insulator-এ carrier প্রায় নেই; semiconductor-এ carrier সীমিত কিন্তু নিয়ন্ত্রণযোগ্য। Energy bandgap এই পার্থক্যের প্রধান ব্যাখ্যা।',example:'Copper wire conductor, PVC insulation insulator এবং silicon diode semiconductor।',remember:'Conductor: high conductivity; insulator: very low; semiconductor: controllable।'},
{concept:'Valence band-এ bound electron থাকে, conduction band-এর electron current বহন করতে পারে। মাঝের forbidden gap বা bandgap অতিক্রম করতে electron-এর পর্যাপ্ত energy দরকার।',example:'তাপ বা আলো পেলে silicon-এর কিছু electron conduction band-এ উঠে electron-hole pair তৈরি করে।',remember:'ছোট bandgap হলে carrier তৈরি তুলনামূলক সহজ।'},
{concept:'Intrinsic semiconductor হলো ইচ্ছাকৃত impurity ছাড়া বিশুদ্ধ material। তাপের কারণে electron-hole pair তৈরি হয় এবং equilibrium-এ electron ও hole concentration সমান: n = p = nᵢ।',example:'বিশুদ্ধ silicon crystal গরম হলে carrier সংখ্যা বাড়ে এবং resistance সাধারণত কমে।',remember:'Intrinsic material-এ electron ও hole সমান সংখ্যায় তৈরি হয়।'},
{concept:'Extrinsic semiconductor তৈরি হয় অতি অল্প impurity বা dopant যোগ করে। এই doping carrier concentration অনেক বাড়িয়ে material-কে প্রয়োজনমতো N-type বা P-type করে।',example:'Silicon crystal-এ phosphorus বা boron-এর নিয়ন্ত্রিত পরিমাণ যোগ করে device region তৈরি করা হয়।',remember:'Doping conductivity নিয়ন্ত্রণ করে।'},
{concept:'N-type-এ donor impurity অতিরিক্ত electron দেয়, তাই electron majority carrier। P-type-এ acceptor impurity hole তৈরি করে। দুই material-ই মোটের ওপর electrically neutral।',example:'Phosphorus-doped silicon N-type এবং boron-doped silicon P-type হতে পারে।',remember:'N মানে net negative নয়, P মানে net positive নয়।'},
{concept:'P ও N region যুক্ত হলে carrier diffusion ও recombination ঘটে। ফলে mobile carrier-কম depletion region, fixed ion এবং built-in electric field তৈরি হয়।',example:'এই PN junction-ই সাধারণ diode, LED, photodiode ও solar cell-এর মৌলিক অংশ।',remember:'Depletion region-এ mobile carrier খুব কম।'},
{concept:'Forward bias-এ P-side positive ও N-side negative হলে barrier কমে এবং current বাড়ে। Reverse bias-এ polarity উল্টো হলে depletion width বাড়ে, সামান্য leakage ছাড়া current বন্ধ থাকে—breakdown পর্যন্ত।',example:'Silicon diode-এর forward drop প্রায় 0.7 V হতে পারে, তবে exact value current ও temperature-এর ওপর নির্ভর করে।',remember:'Forward: barrier কম; Reverse: barrier বেশি।'},
{concept:'Diode V-I curve linear নয়। Forward knee-এর পরে current দ্রুত বাড়ে; reverse অঞ্চলে leakage ছোট থাকে; breakdown voltage ছাড়ালে reverse current হঠাৎ বেড়ে যায়।',example:'Curve tracer দিয়ে forward knee, leakage ও breakdown region দেখা যায়।',remember:'Diode-কে fixed resistor ধরে বিশ্লেষণ করা ঠিক নয়।'},
{concept:'Zener regulation দেয়; LED আলো দেয়; photodiode আলো শনাক্ত করে; Schottky কম forward drop ও দ্রুত switching দেয়; varactor voltage-controlled capacitance দেয়।',example:'Indicator-এ LED, receiver-এ photodiode, fast supply-তে Schottky এবং tuner-এ varactor ব্যবহৃত হয়।',remember:'Function ও rating মিলিয়ে diode নির্বাচন করো।'},
{concept:'Diode rectification, reverse-polarity protection, flyback suppression, clipping, clamping, detection, regulation ও optical sensing-এ ব্যবহৃত হয়।',example:'Relay coil-এর across flyback diode transistor-কে induced voltage থেকে রক্ষা করে।',remember:'Current, reverse voltage, surge, power ও speed rating যাচাই করো।'},
{concept:'Rectifier AC-কে একমুখী pulsating DC-তে রূপান্তর করে। Half-wave এক half-cycle এবং full-wave দুই half-cycle ব্যবহার করে। Bridge-এ চার diode থাকে, প্রতি half-cycle-এ দুইটি conduct করে।',example:'Adapter-এর transformer secondary থেকে bridge rectifier pulsating DC তৈরি করে।',remember:'Rectifier output perfectly smooth DC নয়।'},
{concept:'Ripple factor হলো DC output-এর AC RMS অংশের সঙ্গে DC অংশের অনুপাত। Ideal unfiltered half-wave প্রায় 1.21 এবং full-wave প্রায় 0.482।',example:'50 Hz supply-এ half-wave ripple 50 Hz, full-wave ripple 100 Hz।',remember:'Full-wave-এর ripple কম ও frequency দ্বিগুণ।'},
{concept:'Rectifier efficiency η = Pdc/Pac × 100%। Ideal maximum half-wave প্রায় 40.6% এবং full-wave প্রায় 81.2%; practical loss থাকায় বাস্তব মান কম।',example:'Full-wave source-এর দুই half-cycle কাজে লাগিয়ে বেশি DC power দেয়।',remember:'Efficiency ও ripple factor এক নয়।'},
{concept:'Filter pulsating DC-এর ripple কমায়। Capacitor peak-এর কাছে charge হয়ে মাঝের সময়ে load-কে energy দেয়; inductor current change বাধা দেয়।',example:'Load current বাড়লে capacitor দ্রুত discharge হয়; আনুমানিক ΔVpp ≈ IL/(frC)।',remember:'C বা ripple frequency বাড়লে সাধারণত ripple কমে।'},
{concept:'Filter ripple কমায়, regulator input বা load বদলালেও output voltage স্থির রাখে। Zener shunt regulator-এ series resistor ও power rating ঠিক রাখতে হয়।',example:'Rectifier ও capacitor-এর পরে Zener stage ছোট reference supply স্থির রাখে।',remember:'Rectifier → Filter → Regulator।'},
{concept:'Diode charger, adapter, control supply, automotive electronics, solar converter, sensor, protection ও communication equipment-এ ব্যবহৃত হয়।',example:'PLC supply-তে bridge rectifier, filter capacitor, regulator ও protection diode একসঙ্গে কাজ করে।',remember:'PIV, current, surge, recovery ও temperature rating দেখো।'}];
const chapterSemiconductorImages=['ch26-topic-01-semiconductor.svg','ch26-topic-02-materials.svg','ch26-topic-03-energy-bands.svg','ch26-topic-04-intrinsic.svg','ch26-topic-05-extrinsic.svg','ch26-topic-06-n-p-type.svg','ch26-topic-07-pn-junction.svg','ch26-topic-08-biasing.svg','ch26-topic-09-characteristics.svg','ch26-topic-10-diode-types.svg','ch26-topic-11-applications.svg','ch26-topic-12-rectifiers.svg','ch26-topic-13-ripple.svg','ch26-topic-14-efficiency.svg','ch26-topic-15-filters.svg','ch26-topic-16-regulation.svg','ch26-topic-17-industrial.svg'].map(name=>'assets/chapter-26-semiconductor-fundamentals-diodes-and-rectifiers/'+name),shortQuestionsBeforeSemiconductor=shortQuestions;shortQuestions=(raw,chapter)=>{const html=shortQuestionsBeforeSemiconductor(raw,chapter);if(chapter.number!==26)return html;let i=0;return html.replace(/<div class="ecm-qbody">/g,m=>{const src=chapterSemiconductorImages[i],title=chapter.topics[i++]||chapter.title;return `${m}<figure class="ecm-topic-visual"><img src="${src}" alt="${esc(title)} educational visualization" loading="lazy"><figcaption>${inline(title)} — visual explanation</figcaption></figure>`})};
banglaHelp[27]=[
{concept:'Transistor হলো তিন terminal-এর semiconductor device, যা ছোট input দিয়ে বড় output control করে। Active region-এ signal amplify এবং cutoff–ON region ব্যবহারে electronic switch হিসেবে কাজ করে।',example:'Temperature sensor-এর ছোট signal amplifier বড় করে; controller-এর pin transistor দিয়ে relay চালায়।',remember:'Transistor supply energy control করে—energy তৈরি করে না।'},
{concept:'BJT-এর তিন terminal Emitter, Base ও Collector। দুই ধরনের carrier অংশ নেয় বলে এটি bipolar। Fundamental relation I_E = I_C + I_B এবং active region-এ প্রায় I_C ≈ βI_B।',example:'Base-এ অল্প current দিলে Collector path-এ বড় relay current নিয়ন্ত্রণ করা যায়।',remember:'β স্থির universal সংখ্যা নয়; datasheet condition অনুযায়ী বদলায়।'},
{concept:'NPN হলো N–P–N এবং PNP হলো P–N–P। Emitter বেশি doped, Base খুব thin/lightly doped এবং Collector voltage ও heat সামলাতে design করা হয়।',example:'NPN সাধারণত low-side এবং PNP ছোট high-side switch-এ দেখা যায়।',remember:'NPN arrow out; PNP arrow in।'},
{concept:'Active region-এ E–B junction forward এবং C–B junction reverse biased। Cutoff প্রায় OFF; saturation প্রায় ON। Saturation-এ load circuit current সীমিত করে, βI_B exact formula নয়।',example:'Audio stage active region-এ; relay driver cutoff ও saturation-এর মধ্যে চলে।',remember:'Active = amplify; cutoff/saturation = switch।'},
{concept:'Biasing signal না থাকলেও DC operating point বা Q-point স্থাপন করে। Voltage-divider ও Emitter resistor device variation ও temperature effect কমাতে সাহায্য করে।',example:'Microphone preamp-এর Q-point মাঝামাঝি রাখলে positive ও negative signal swing clipping ছাড়া পাওয়া যায়।',remember:'AC signal DC Q-point-এর চারপাশে পরিবর্তিত হয়।'},
{concept:'CB-তে low input resistance ও current gain 1-এর কম; CE-তে voltage/current gain বেশি এবং 180° inversion; CC বা emitter follower-এ gain প্রায় 1, high input ও low output resistance।',example:'CE voltage amplifier, CC sensor buffer এবং CB high-frequency stage-এ উপযোগী।',remember:'CE amplify; CC buffer; CB high-frequency/low input resistance।'},
{concept:'Input, output ও transfer characteristic terminal relation দেখায়। DC load line external supply ও resistor-এর অনুমোদিত I_C–V_CE combination দেখায়; Q-point এই line-এর ওপর থাকে।',example:'Measured V_CE খুব কম হলে stage saturation-এর কাছে, খুব বেশি হলে cutoff-এর কাছে থাকতে পারে।',remember:'Curve device behavior; load line external circuit limit।'},
{concept:'FET voltage-controlled device। Gate-to-Source voltage electric field দিয়ে Source–Drain channel current নিয়ন্ত্রণ করে। Steady Gate current খুব কম, তাই input resistance বেশি।',example:'High-impedance sensor input-এ FET loading কমায়।',remember:'FET Gate current ছোট হলেও switching-এ Gate capacitance charge করতে হয়।'},
{concept:'JFET reverse-biased junction Gate ব্যবহার করে এবং সাধারণত zero bias-এ ON। Enhancement MOSFET insulated Gate ব্যবহার করে ও zero V_GS-এ সাধারণত OFF।',example:'MOSFET LED strip বা motor switch করে; JFET low-noise input stage-এ ব্যবহার হয়।',remember:'V_GS(th) full-ON voltage নয়—R_DS(on) condition দেখো।'},
{concept:'Amplifier input signal অনুসারে DC supply energy output-এ দেয়। Bias, headroom, loading ও linearity ঠিক না থাকলে waveform clipping বা distortion হয়।',example:'Thermocouple-এর millivolt signal ADC-এর আগে amplify করা হয়।',remember:'Required output = input × gain, তবে supply limit-এর ভেতরে।'},
{concept:'Voltage, Current ও Power amplifier ছাড়াও frequency, coupling এবং operating class অনুযায়ী classification হয়। Class A linear কিন্তু কম efficient; Class D switching হওয়ায় বেশি efficient।',example:'Sensor preamp small-signal class; speaker output Power stage; efficient audio output Class D হতে পারে।',remember:'একটি amplifier সব source, load ও frequency-এর জন্য best নয়।'},
{concept:'Gain হলো output/input ratio। Frequency response gain ও phase-এর frequency অনুযায়ী পরিবর্তন; basic bandwidth BW = f_H − f_L। Cutoff প্রায় −3 dB হতে পারে।',example:'f_L=100 Hz ও f_H=10 kHz হলে BW=9.9 kHz।',remember:'High gain মানেই wide bandwidth নয়।'},
{concept:'Op-Amp high-gain differential amplifier: V_o=A_OL(V_+−V_−)। Open-loop gain অনেক বড় বলে সাধারণত negative feedback দিয়ে stable closed-loop gain বানানো হয়।',example:'Pressure sensor signal Op-Amp দিয়ে amplify ও filter করে controller-এ পাঠানো হয়।',remember:'Input common-mode ও output swing supply rail পর্যন্ত নাও যেতে পারে।'},
{concept:'Ideal Op-Amp-এর input resistance infinite, output resistance zero, gain/bandwidth infinite। Linear negative feedback-এ input current zero এবং V_+≈V_− ধরা হয়।',example:'এই ideal rules দিয়ে resistor ratio থেকে closed-loop gain দ্রুত হিসাব করা যায়।',remember:'Saturation বা positive/open-loop অবস্থায় V_+≈V_− rule প্রযোজ্য নয়।'},
{concept:'Inverting gain −R_f/R_in; Non-Inverting gain 1+R_f/R_g; Voltage Follower gain 1। Follower voltage বাড়ায় না, কিন্তু high-input/low-output impedance দিয়ে buffer করে।',example:'R_f=20kΩ, R_in=10kΩ হলে inverting gain −2।',remember:'Ideal output supply, bandwidth, slew-rate ও current limit-এর ভেতরে থাকতে হবে।'},
{concept:'Op-Amp sensor signal process করে, Transistor relay/motor/load drive করে। Flyback protection, decoupling, heat sinking, grounding ও ESD control reliable system-এর অংশ।',example:'Automatic fan controller-এ Op-Amp temperature signal process করে এবং MOSFET fan current control করে।',remember:'Signal stage ও power stage-এর rating আলাদাভাবে verify করো।'},
{concept:'BJT, JFET, MOSFET ও Op-Amp-এর নিজস্ব advantage ও limitation আছে। Voltage, current, power, SOA, temperature, noise, bandwidth, stability ও environment মিলিয়ে selection করতে হয়।',example:'Dead control card troubleshoot করতে supply → bias → input → output → load ক্রমে safe measurement করা হয়।',remember:'Ideal formula-এর পরে datasheet ও thermal check আবশ্যক।'}];
const chapterTransistorImages=['ch27-topic-01-transistor.svg','ch27-topic-02-bjt.svg','ch27-topic-03-npn-pnp.svg','ch27-topic-04-bjt-operation.svg','ch27-topic-05-biasing.svg','ch27-topic-06-configurations.svg','ch27-topic-07-characteristics.svg','ch27-topic-08-fet.svg','ch27-topic-09-jfet-mosfet.svg','ch27-topic-10-amplifier.svg','ch27-topic-11-amplifier-types.svg','ch27-topic-12-gain-bandwidth.svg','ch27-topic-13-opamp.svg','ch27-topic-14-ideal-opamp.svg','ch27-topic-15-opamp-configurations.svg','ch27-topic-16-applications.svg','ch27-topic-17-industrial.svg'].map(name=>'assets/chapter-27-transistors-amplifiers-and-operational-amplifiers/'+name),shortQuestionsBeforeTransistor=shortQuestions;shortQuestions=(raw,chapter)=>{const html=shortQuestionsBeforeTransistor(raw,chapter);if(chapter.number!==27)return html;let i=0;return html.replace(/<div class="ecm-qbody">/g,m=>{const src=chapterTransistorImages[i],title=chapter.topics[i++]||chapter.title;return `${m}<figure class="ecm-topic-visual"><img src="${src}" alt="${esc(title)} educational visualization" loading="lazy"><figcaption>${inline(title)} — visual explanation</figcaption></figure>`})};
banglaHelp[28]=[
{concept:'Digital Electronics-এ তথ্যকে নিরবচ্ছিন্ন মানের বদলে নির্দিষ্ট স্তর দিয়ে প্রকাশ করা হয়। সাধারণত দুটি স্তর Logic 0 ও Logic 1 ব্যবহৃত হয়। এগুলো একক নির্দিষ্ট voltage নয়; IC datasheet-এ প্রতিটির গ্রহণযোগ্য voltage range দেওয়া থাকে।',example:'PLC কোনো proximity sensor-এর ON/OFF অবস্থা 0 ও 1 হিসেবে পড়ে এবং সেই শর্ত অনুযায়ী motor চালু বা বন্ধ করে।',remember:'Digital মানে discrete state; বাস্তব circuit-এ প্রতিটি state একটি voltage range।'},
{concept:'Analog signal সময়ের সঙ্গে ধারাবাহিকভাবে বদলায়, কিন্তু Digital signal নির্দিষ্ট ধাপে বদলায়। বাস্তব জগতের তাপমাত্রা বা শব্দ Analog হলেও controller-এ কাজ করার আগে ADC দিয়ে Digital data-তে রূপান্তর করা হয়।',example:'Microphone-এর Analog waveform ADC হয়ে mobile phone-এ Binary sample হিসেবে সংরক্ষিত হয়।',remember:'Analog = continuous, Digital = discrete; conversion-এর সময় resolution ও sampling গুরুত্বপূর্ণ।'},
{concept:'Number System হলো সংখ্যা প্রকাশের নিয়ম। Decimal-এর base 10, Binary-এর 2, Octal-এর 8 এবং Hexadecimal-এর 16। কোনো digit-এর মান তার digit ও positional weight-এর গুণফলের উপর নির্ভর করে।',example:'Binary 1011-এ positional weights 8, 4, 2, 1; তাই মান 8+0+2+1=11।',remember:'Base যত, বৈধ digit 0 থেকে base−1 পর্যন্ত। Hex-এ A–F দিয়ে 10–15 বোঝায়।'},
{concept:'Binary থেকে Decimal করতে প্রতিটি bit-কে 2-এর উপযুক্ত power দিয়ে গুণ করে যোগ করতে হয়। Decimal integer থেকে Binary করতে বারবার 2 দিয়ে ভাগ করে remainder নিচ থেকে ওপরে পড়তে হয়। Octal-এর জন্য 3-bit এবং Hex-এর জন্য 4-bit group ব্যবহার করা যায়।',example:'13₁₀ = 1101₂; আবার 1111₂ = F₁₆।',remember:'Conversion শেষে বিপরীত পদ্ধতিতে ফল যাচাই করলে ভুল কমে।'},
{concept:'Binary arithmetic-এর নিয়ম Decimal-এর মতো column-wise, তবে digit শুধু 0 ও 1। 1+1=10₂ হলে sum 0 এবং carry 1; 0−1 করতে পরের ঘর থেকে borrow নিতে হয়।',example:'101₂ + 011₂ = 1000₂, অর্থাৎ 5+3=8।',remember:'Carry ও Borrow পরের higher position-এ যায়; প্রতিটি ধাপ লিখে হিসাব করো।'},
{concept:'8421 BCD-তে প্রতিটি Decimal digit আলাদা চার bit দিয়ে লেখা হয়। তাই 59-এর BCD হলো 0101 1001; এটি 59-এর pure Binary 111011-এর সমান coding নয়।',example:'Digital energy meter বা seven-segment display-তে Decimal digit দেখাতে BCD-based processing ব্যবহার হতে পারে।',remember:'একটি BCD digit-এর বৈধ code 0000 থেকে 1001; 1010–1111 অবৈধ।'},
{concept:'Gray Code-এ পাশাপাশি দুটি code word-এর মধ্যে মাত্র একটি bit বদলায়। ফলে position sensor এক অবস্থান থেকে পরের অবস্থানে গেলে একাধিক bit একসঙ্গে পরিবর্তনের কারণে ভুল পড়ার ঝুঁকি কমে।',example:'Rotary encoder shaft-এর angle নির্ভরযোগ্যভাবে শনাক্ত করতে Gray Code track ব্যবহার করে।',remember:'Gray Code non-weighted এবং adjacent code-এ one-bit change হয়।'},
{concept:'Logic Gate Binary condition অনুযায়ী output দেয়। AND-এ সব input 1 হলে output 1; OR-এ যেকোনো input 1 হলেই 1; NOT input উল্টায়। NAND ও NOR universal, XOR difference এবং XNOR equality শনাক্ত করে।',example:'Machine guard closed AND start button pressed—দুটি শর্ত পূরণ হলেই motor enable করা একটি AND function।',remember:'Gate symbol, Boolean expression ও Truth Table—তিনটিই একই function-এর ভিন্ন প্রকাশ।'},
{concept:'Truth Table একটি Logic function-এর সব সম্ভাব্য input combination ও সংশ্লিষ্ট output দেখায়। nটি Binary input থাকলে row হয় 2ⁿ। প্রতিটি row-তে expression ধাপে ধাপে evaluate করলে ভুল কমে।',example:'তিন input-এর circuit-এ 2³=8টি input combination থাকে।',remember:'Truth Table হলো circuit behavior-এর সম্পূর্ণ তালিকা।'},
{concept:'Boolean Algebra-তে variable শুধু 0 বা 1 এবং + দিয়ে OR, · দিয়ে AND, bar বা prime দিয়ে NOT বোঝায়। এটি সাধারণ arithmetic নয়; যেমন 1+1 Boolean OR-এ 1।',example:'A·B expression দিয়ে দুইটি safety condition একসঙ্গে সত্য হওয়া প্রকাশ করা যায়।',remember:'Boolean symbol দেখেই ordinary arithmetic প্রয়োগ করো না।'},
{concept:'Identity, Null, Idempotent, Complement, Commutative, Associative, Distributive ও Absorption law ব্যবহার করে expression ছোট করা হয়। যেমন A+A=A এবং A+AB=A।',example:'A+AB circuit সরল করে শুধু A করলে একই output কম gate দিয়ে পাওয়া যায়।',remember:'Law প্রয়োগের পর Truth Table দিয়ে equivalence যাচাই করা যায়।'},
{concept:"De Morgan's Theorem অনুযায়ী complement bar ভাঙলে প্রতিটি variable complement হয় এবং AND↔OR বদলে যায়: overline(AB)=A̅+B̅ এবং overline(A+B)=A̅B̅।",example:'NAND output-কে complemented inputs-এর OR হিসেবেও বোঝানো যায়।',remember:'Bar ভাঙো, প্রতিটি term উল্টাও, AND ও OR অদলবদল করো।'},
{concept:'Logic simplification একই Truth Table রেখে কম term ও কম Gate-এর circuit তৈরি করে। এতে cost, wiring, propagation delay, Power Consumption এবং fault point কমতে পারে।',example:'A+AB সরল করে A করলে একটি অতিরিক্ত AND path বাদ যায়।',remember:'শুধু expression ছোট হলেই হবে না—সব input-এর output অপরিবর্তিত থাকতে হবে।'},
{concept:'K-Map হলো Gray Code order-এ সাজানো visual simplification grid। adjacent 1-গুলোকে 1,2,4,8 ইত্যাদি power-of-two group করতে হয়। বড় valid group সাধারণত বেশি variable বাদ দেয়।',example:'চারটি adjacent 1-এর group-এ যে variables বদলায় সেগুলো বাদ দিয়ে constant variable রাখা হয়।',remember:'Edge wrapping বৈধ, diagonal adjacency বৈধ নয়; largest group আগে খুঁজুন।'},
{concept:'Combinational circuit-এর বর্তমান output শুধু বর্তমান input-এর উপর নির্ভর করে। Half/Full Adder যোগ করে, Subtractor বিয়োগ করে, MUX input নির্বাচন করে, DEMUX destination নির্বাচন করে, Encoder code বানায় এবং Decoder code বুঝে output সক্রিয় করে।',example:'4-to-1 MUX দুই Select line দিয়ে চারটি sensor signal-এর একটি controller input-এ পাঠায়।',remember:'MUX many-to-one; DEMUX one-to-many; Full Adder-এ Carry-in থাকে।'},
{concept:'Digital Logic computer, PLC, relay protection, communication, digital meter, traffic controller ও embedded system-এর decision-making ভিত্তি। বাস্তব প্রয়োগে sensor interface, Logic level, timing এবং output driver একসঙ্গে বিবেচনা করতে হয়।',example:'Automatic water pump controller level sensors-এর Digital state দেখে pump ও alarm নিয়ন্ত্রণ করে।',remember:'Logic function সঠিক হলেও voltage, timing ও load rating ভুল হলে বাস্তব circuit কাজ নাও করতে পারে।'},
{concept:'Digital system সহজে data store, copy, process ও program করতে পারে এবং নির্দিষ্ট noise margin পর্যন্ত নির্ভরযোগ্য। তবে quantization error, finite speed, Power, EMI, interface এবং software dependency সীমাবদ্ধতা তৈরি করে।',example:'Industrial controller শক্তিশালী হলেও 24 V sensor-কে 5 V Logic input-এ সরাসরি দিলে circuit নষ্ট হতে পারে; interface দরকার।',remember:'Function, electrical rating, timing, environment ও safety—সব মিলিয়ে Digital design নির্বাচন করতে হয়।'}];
const chapterDigitalImages=['ch28-topic-01-digital.svg','ch28-topic-02-analog-digital.svg','ch28-topic-03-number-systems.svg','ch28-topic-04-conversions.svg','ch28-topic-05-binary-arithmetic.svg','ch28-topic-06-bcd.svg','ch28-topic-07-gray-code.svg','ch28-topic-08-logic-gates.svg','ch28-topic-09-truth-table.svg','ch28-topic-10-boolean-algebra.svg','ch28-topic-11-boolean-laws.svg','ch28-topic-12-demorgan.svg','ch28-topic-13-simplification.svg','ch28-topic-14-kmap.svg','ch28-topic-15-combinational.svg','ch28-topic-16-applications.svg','ch28-topic-17-industry.svg'].map(name=>'assets/chapter-28-digital-electronics-and-basic-logic-circuits/'+name),shortQuestionsBeforeDigital=shortQuestions;shortQuestions=(raw,chapter)=>{const html=shortQuestionsBeforeDigital(raw,chapter);if(chapter.number!==28)return html;let i=0;return html.replace(/<div class="ecm-qbody">/g,m=>{const src=chapterDigitalImages[i],title=chapter.topics[i++]||chapter.title;return `${m}<figure class="ecm-topic-visual"><img src="${src}" alt="${esc(title)} educational visualization" loading="lazy"><figcaption>${inline(title)} — visual explanation</figcaption></figure>`})};
banglaHelp[29]=[
{concept:'Power Electronics হলো semiconductor switch ও control circuit ব্যবহার করে electrical power-এর রূপ, voltage, current ও frequency নিয়ন্ত্রণের প্রযুক্তি। এর চারটি মূল conversion হলো AC-DC, DC-DC, DC-AC এবং AC-AC।',example:'একটি solar inverter panel-এর DC power-কে ঘর বা grid-এর উপযোগী AC power-এ রূপান্তর করে।',remember:'Power stage শক্তি বহন করে; control stage কখন ও কীভাবে switch হবে তা ঠিক করে।'},
{concept:'Power Electronics উচ্চ efficiency, দ্রুত control, ছোট আকার এবং automation সম্ভব করে। Motor drive, charger, UPS, renewable energy, electric vehicle ও industrial heating—সবখানেই এটি গুরুত্বপূর্ণ।',example:'VFD pump-এর speed চাহিদা অনুযায়ী কমিয়ে throttling loss ও mechanical stress কমাতে পারে।',remember:'সঠিক conversion শুধু output দেয় না—efficiency, reliability ও process quality-ও উন্নত করে।'},
{concept:'Power Diode uncontrolled; SCR gate pulse-এ ON হয়ে latch করে; TRIAC দুই দিকে AC control করে; DIAC TRIAC trigger করে; MOSFET দ্রুত switching-এ উপযোগী; IGBT medium/high-power drive-এ প্রচলিত।',example:'SMPS-এ MOSFET, VFD inverter-এ IGBT এবং সাধারণ dimmer-এ DIAC-TRIAC ব্যবহার দেখা যায়।',remember:'Device নির্বাচন করতে voltage, current, frequency, loss, SOA ও temperature একসঙ্গে দেখুন।'},
{concept:'Switching control-এ device দ্রুত ON ও OFF হয়। Duty cycle D=tON/T এবং switching frequency fs=1/T। PWM pulse width বদলে average output নিয়ন্ত্রণ করে; বাস্তবে conduction ও switching loss থাকে।',example:'DC motor PWM controller duty cycle বাড়ালে average armature voltage ও সাধারণত speed বাড়ে।',remember:'Dead time bridge-এর upper ও lower switch একসঙ্গে ON হয়ে shoot-through হওয়া ঠেকায়।'},
{concept:'Rectifier AC-কে DC করে। Diode rectifier uncontrolled, SCR rectifier firing angle দিয়ে controlled এবং active front end input current shape ও regeneration করতে পারে।',example:'সাধারণ VFD-এর input-এ diode bridge AC-কে DC-link voltage-এ রূপান্তর করে।',remember:'Inductive load-এর current হঠাৎ থামে না—freewheeling path ও device rating জরুরি।'},
{concept:'DC-DC converter একটি DC level-কে অন্য DC level-এ বদলায়। Buck step-down, Boost step-up এবং Buck-Boost topology অনুযায়ী up/down করতে পারে। Inductor energy transfer করে, capacitor ripple কমায় এবং feedback output regulate করে।',example:'24 V source থেকে regulated 5 V control supply তৈরি করতে Buck converter ব্যবহার করা যায়।',remember:'Ideal continuous Buck-এ Vo≈DVin; practical output loss ও operating mode-এর উপরও নির্ভর করে।'},
{concept:'Inverter DC source বা DC link থেকে controlled AC তৈরি করে। Bridge switches polarity বদলায় এবং PWM fundamental voltage, frequency ও waveform নিয়ন্ত্রণ করে।',example:'Three-phase VFD inverter ছয়টি controlled switch দিয়ে motor-এর জন্য variable-frequency output তৈরি করে।',remember:'Gate timing ভুল হলে shoot-through হতে পারে; output harmonics ও motor insulation stress বিবেচনা করুন।'},
{concept:'AC-DC converter diode, SCR অথবা actively controlled switch দিয়ে AC input থেকে DC output দেয়। DC link converter stage-গুলোর মধ্যে energy buffer; pre-charge inrush কমায় এবং discharge path stored energy নামায়।',example:'Regenerative drive-এর active front end braking energy supply-তে ফেরত দিতে পারে।',remember:'Input disconnect করলেও DC-link capacitor বিপজ্জনক voltage ধরে রাখতে পারে।'},
{concept:'AC-AC controller AC output-এর RMS voltage, frequency অথবা উভয় নিয়ন্ত্রণ করে। TRIAC/SCR phase control voltage বদলায় কিন্তু সাধারণত frequency একই থাকে; VFD indirect AC-DC-AC conversion করে।',example:'Heater controller phase angle বদলে heating power নিয়ন্ত্রণ করে।',remember:'Phase control harmonics, EMI ও poor power factor তৈরি করতে পারে।'},
{concept:'Motor Drive source, converter, motor, controller, sensing, command ও protection-এর সমন্বিত system। এটি start, stop, speed, torque, direction, acceleration ও braking নিয়ন্ত্রণ করে।',example:'Conveyor drive PLC-এর speed reference নিয়ে smooth acceleration দেয় এবং overload হলে trip করে।',remember:'Drive শুধু inverter module নয়—সম্পূর্ণ controlled motor system।'},
{concept:'DC Drive brushed DC motor নিয়ন্ত্রণ করে; VFD AC motor-এর voltage-frequency বদলায়; Servo Drive precise position/torque দেয়; Stepper Drive pulse sequence এবং BLDC Drive electronic commutation ব্যবহার করে।',example:'CNC axis-এ Servo Drive, water pump-এ VFD এবং printer mechanism-এ Stepper Drive ব্যবহার হতে পারে।',remember:'Motor type, load torque, speed range, accuracy ও duty অনুযায়ী Drive নির্বাচন করুন।'},
{concept:'VFD-এর প্রধান stage Rectifier → DC Link → PWM Inverter। Fixed AC প্রথমে DC হয়, পরে variable-voltage variable-frequency AC হয়ে motor-এ যায়। Ns=120f/P অনুযায়ী frequency বদলে synchronous speed বদলায়।',example:'চার-pole motor-এ 30 Hz দিলে synchronous speed 900 rpm; induction rotor speed slip-এর কারণে একটু কম।',remember:'Motor nameplate data, acceleration, current limit ও protection parameter সঠিকভাবে set করুন।'},
{concept:'Soft Starter SCR দিয়ে starting voltage ধীরে বাড়িয়ে inrush current ও mechanical shock কমায়; start শেষে bypass contactor loss কমায়। VFD frequency-ও বদলায় বলে continuous speed control ও energy saving দিতে পারে।',example:'Fixed-speed pump-এ smooth start দরকার হলে Soft Starter; variable flow দরকার হলে VFD উপযুক্ত।',remember:'Soft Starter start/stop নিয়ন্ত্রণ করে; VFD running speed-ও নিয়ন্ত্রণ করে।'},
{concept:'Industrial Motor Control System-এ isolator, breaker, contactor, overload, Drive, PLC, sensor, HMI ও emergency circuit সমন্বিতভাবে কাজ করে। Interlock conflict আটকায়, permissive readiness নিশ্চিত করে, trip fault-এ থামায়।',example:'Lubrication pressure healthy না হলে compressor motor start permissive পাওয়া উচিত নয়।',remember:'Forward ও reverse contactor কখনও একসঙ্গে energize হতে দেওয়া যাবে না।'},
{concept:'Suitable centrifugal pump/fan-এ flow∝speed, pressure∝speed² এবং power∝speed³। তাই demand কমলে VFD speed কমিয়ে throttling-এর বদলে উল্লেখযোগ্য energy বাঁচাতে পারে।',example:'80% speed-এ idealized power ratio 0.8³=0.512; বাস্তব saving system curve ও loss-এর উপর নির্ভর করে।',remember:'প্রতিটি VFD installation energy saving নিশ্চিত করে না—baseline ও duty profile মাপুন।'},
{concept:'Power Electronics-এর সুবিধা high efficiency, fast control, compact size ও automation। সীমাবদ্ধতা switching loss, harmonics, EMI, cooling, insulation stress, complexity ও trained maintenance।',example:'Long motor cable-এ VFD output dv/dt motor insulation stress বাড়াতে পারে; reactor বা filter লাগতে পারে।',remember:'Efficient মানে lossless নয়; thermal, EMC ও protection design অপরিহার্য।'},
{concept:'Pump, fan, conveyor, crane, furnace, welding, UPS, solar plant ও EV-তে converter ও Drive process command-কে controlled power-এ রূপ দেয়। Feedback ও interlock operation নির্ভরযোগ্য করে।',example:'Pressure transmitter → controller → VFD → pump chain set-point অনুযায়ী water pressure ধরে রাখে।',remember:'Successful application-এর জন্য sizing, installation, commissioning ও maintenance সব সঠিক হতে হবে।'},
{concept:'Industrial converter-এ hazardous AC, high DC-link voltage, stored capacitor energy, arc-flash ও unexpected motor movement থাকতে পারে। LOTO, discharge time, absence-of-voltage verification, PPE ও protective earth বাধ্যতামূলক।',example:'VFD Stop চাপা electrical isolation নয়; input isolate করেও manufacturer time অপেক্ষা করে tester দিয়ে DC link যাচাই করতে হয়।',remember:'Isolate → lock/tag → wait → prove tester → test for dead → re-prove tester।'}];
