function setEcmDark(dark){
  document.documentElement.classList.toggle('dark',dark);
  var root=document.getElementById('eee-masterbook');
  if(root)root.classList.toggle('dark',dark);
}
/* Dark-mode sync: parent Blogger body.dark sends {ecmDark:true|false}. Direct paste watches body.dark. */
window.addEventListener('message',function(e){
  try{if(e.data&&typeof e.data.ecmDark==='boolean')setEcmDark(e.data.ecmDark)}catch(err){}
});
try{
  if(window.parent===window){
    var syncLocalDark=function(){setEcmDark(!!(document.body&&document.body.classList.contains('dark')))};
    syncLocalDark();
    if(window.MutationObserver&&document.body)new MutationObserver(syncLocalDark).observe(document.body,{attributes:true,attributeFilter:['class']});
  }
}catch(err){}
